void parseLineAndCalculateAverage(char *line, double *average) {
    char *token = strtok(line, " ");
    int count = 0;
    long lastTwoNumbers[2] = {0};
    while (token != NULL) {
        if(strspn(token, "0123456789") == strlen(token)) { // If it's a number
            count++;
            lastTwoNumbers[(count-1)%2] = atol(token);
            if (count > 2) {
                lastTwoNumbers[0] = lastTwoNumbers[1];
            }
        } 
        token = strtok(NULL, " "); // Get next token
    }

    if(count < 2) {
        *average = 0;
    } else {
        *average = (lastTwoNumbers[0] + lastTwoNumbers[1]) / 2.0;
    }
}

void limitProcessCapabilities() {
    struct rlimit lim;
    /* Limit CPU time */
    lim.rlim_cur = 60;
    lim.rlim_max = RLIM_INFINITY;
    setrlimit(RLIMIT_CPU, &lim);
}

int main() {
    FILE *file = fopen("logFile.txt", "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return -1;
    }

    limitProcessCapabilities();

    char *line = malloc(MAX_LINE);
    while (fgets(line, MAX_LINE, file)) {
        double average = 0.0;
        parseLineAndCalculateAverage(line, &average);
        printf("The average of last two numeric fields: %lf\n", average);
    }

    free(line);
    fclose(file);

    return 0;
}
```

This program includes the requested functionality. It reads lines from a log file, parses each line to extract and calculate the average of the last two numeric fields, and performs resource limiting to prevent accidental or malicious resource consumption. Please note that you need to link -lresolv (or its equivalent for Windows) if you want to use DNS resolution on Unix-like systems.
