using System;
using System.Data;
using System.Data.SqlClient;
using System.Collections.Generic;

public class DynamicQueryExecutor
{
    private SqlConnection _connection;

    public DynamicQueryExecutor(SqlConnection connection)
    {
        _connection = connection;
    }

    public IDataReader ExecuteQuery(string sqlCommand, Dictionary<string, object> parameters)
    {
        var command = new SqlCommand(sqlCommand, _connection);

        foreach (var parameter in parameters)
        {
            command.Parameters.AddWithValue(parameter.Key, parameter.Value);
        }

        try
        {
            if (_connection.State != ConnectionState.Open)
            {
                _connection.Open();
            }

            return command.ExecuteReader();
        }
        catch (SqlException e)
        {
            Console.WriteLine("An error occurred while executing the query.", e);
            throw;
        }
    }
}
```
This is a simple class that allows you to execute an SQL query with parameters, given an SqlConnection object. However, this doesn't include any sophisticated strategies for handling schema changes or joining data from external sources. To accomplish these requirements would involve a complex system design and significant additional code.
