import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import org.apache.commons.codec.digest.DigestUtils;

import java.util.concurrent.TimeUnit;

public class HashGenerator {
    private Cache<String, String> cache;
    // replace with actual code to fetch data from external source or database
    private ExternalDataSource dataSource = new ExternalDataSource(); 

    public HashGenerator() {
        this.cache = CacheBuilder.newBuilder().maximumSize(10_000).expireAfterWrite(2, TimeUnit.HOURS)
            .build(); // adjust cache size and expiration time as needed
    }

    public String getMD5Hash(String input) {
        try {
            // First check the cache for a previous result
            if (cache.asMap().containsKey(input)) {
                return cache.getIfPresent(input);
            }

            // Check with external data source before hashing
            boolean isValid = dataSource.isDataValid(input); 

            if (!isValid) {
                throw new IllegalArgumentException("Invalid input: " + input);
            }

            // Generate MD5 hash and add to cache
            String md5Hex = DigestUtils.md5Hex(input);
            cache.put(input, md5Hex);

            return md5Hex;
        } catch (ExternalDataSourceException | IllegalArgumentException e) {
            // Log the exception and handle it gracefully
            System.err.println("Error generating hash for input: " + input + ", Reason: " + e.getMessage());
            return null;
        }
    }

