        boolean isDataValid(String input) throws ExternalDataSourceException {
            // Implement logic to validate data against an external data source here.
            return false;
        }
    }

    public class ExternalDataSourceException extends Exception{
       public ExternalDataSourceException(String message){
           super(message);
       }
    }
}
```
