["Here's a basic JavaScript solution using Node.js `fs` module and promises for asynchronous operations:

```javascript
const fs = require('fs');
const path = require('path');
const util = require('util');

// Promisify the required functions from 'fs' to use them with async/await syntax
const readdir = util.promisify(fs.readdir);
const stat = util.promisify(fs.stat);

async function getFilesFromPathsWithLastModifiedTime(paths, extensions) {
  let files = [];

  for (let path of paths) {
    try {
      // Read directory contents asynchronously
      const dirContent = await readdir(path);

      for (let fileName of dirContent) {
        const filePath = path + '/' + fileName;

        // Get stats about a file/directory, including last modified time
        let statResult = await stat(filePath);

        if (!statResult.isDirectory() && extensions.includes(path.extname(filePath))) {
          files.push({ name: fileName, lastModified: statResult.mtime });
        }
      }
    } catch (err) {
      // Handle errors gracefully - for instance, log the error and continue processing other paths
      console.error('Error occurred while reading directory or getting stats about a file/directory:', err);
    }
  }

  return files;
}
```

Note that this code does not handle any form of filtering based on additional metadata (file size, creation time). It's recommended to use a library like `walkdir` if you need more control over file traversal and filtering, as it allows for recursive directory walking and provides options for including/excluding files based on specified criteria. 

