            }
        }
    } catch (err) {
        endTime = performance.now();
        statsCollector.addFailedRunStatistics({label, execution_time: (endTime - startTime)}); // Assuming stats collector has this method
        logger.error(`Test '${f.name}' for module '${label}' failed permanently after ${(endTime - startTime).toFixed(2)}ms with error: ${err}.`);
    } finally {
        blueslip.reset();
    }
}

