function renderScripts(scriptObjects, config = {}) {
    const tagMap = {};

    let html = '';
    for (const scriptObject of scriptObjects) {
        const key = scriptObject.key;

        if (!tagMap[key]) {
            tagMap[key] = 0;
        } else {
            tagMap[key]++;
        }

        let id = key + (tagMap[key] ? `_${tagMap[key]}` : '');
        html += `<script id="${id}" ${config.async ? 'async' : ''} ${config.defer ? 'defer' : ''} ${config.crossorigin ? `crossorigin=${config.crossorigin}` : ''}>${scriptObject.code || ''}</script>\n`;
    }

    return html;
}
