        for (const auto& name : fieldNames) {
            if (*it == name) {
                matched = true;
                ++it; // Move the iterator to next element before inserting new element
                it = list.insert_after(it, "refreshed"); 
            } else {
                ++it;
            }
        }
    }

    if (!matched) {
        list.push_front("refreshed");
    }

    std::string update = "";
    for (const auto& str : list) {
        update += str + " ";
