// Cache object to store loaded scripts
var scriptCache = {};

function loadScript(url, callback) {
  // If the script is in cache, return it immediately
  if (scriptCache[url]) {
    callback && callback();
    return;
  }

  var head = document.getElementsByTagName('head')[0];
  var script = document.createElement('script');
  script.type = 'text/javascript';
  // Attach event listener for loading the script
  if (callback) {
    script.onload = function () {
      callback();
      scriptCache[url] = true;
    }
  } else {
    script.onerror = function () {
      console.warn('Failed to load ' + url);
    }
  }

  var done = false;
  // Attach event listener for retrying loading the script
  script.onerror = script.onload = function() {
    if (!done) {
      setTimeout(function(){
        loadScript(url, callback);
      }, Math.pow(2, times++)); // Exponential backoff
      done = true;
    }
  };

  script.src = url;
  head.appendChild(script);
}

// A simple C-like function that modifies the filename based on rules
function cFunction(filename, newExtension) {
  // Here are some example rule: count all letters in filename and append it to the original file name
  var numberOfDigits = ('' + filename.length).replace(/[^0-9]/g,"").length;

  return filename + '.' + numberOfDigits + newExtension;
}
