<?php
require 'vendor/autoload.php';  // Autoload Composer dependencies
use Psr\Log\LoggerInterface;
use Cache\Adapter\Apcu\ApcuCachePool;

class ConfigLoader {
    private $cache;
    private $logger;

    function __construct(ApcuCachePool $cache, LoggerInterface $logger) {
        $this->cache = $cache;
        $this->logger = $logger;
    }

    public function loadConfig($env){
        try{
            $cachedConfig = $this->cache->get('config_' . $env);
            if ($cachedConfig) {
                $this->logger->info("Fetching config from cache");
                return $cachedConfig;
            } else {
                $filePath = __DIR__ . '/config/'.$env.'.php';

                if(!file_exists($filePath)){
                    throw new Exception('Configuration file not found');
                }

                $config = require $filePath;

                $this->cache->set('config_' . $env, $config);
                $this->logger->info("Caching config");
            }

