extern crate snmp;
use std::ffi::CString;
use std::os::unix::process::ExitStatusExt;
use std::io::Write;
use std::fs::File;
use std::path::Path;
use std::env;
use std::sync::{Arc, Mutex};
use std::time::Instant;
use rustc_driver::*;
use snmp::hooks::SyncLazyHook;
use libc::size_t;
extern "C" {
    pub fn va_start(ap: *mut std::os::raw::VaList) -> *mut ();
    pub fn va_end(__builtin_va_list: *mut std::os::raw::VaList);
    pub unsafe extern "C" fn snprintf(s: *mut i8, n: size_t, fmt: *const i8, __builtin_va_arg_pack: ...) -> i32;
}

fn custom_logging() {
    let start = Instant::now();
    let status = Arc::new(Mutex::new(ExitStatusExt::unixWait()));
    let rustc_driver = CString::new("rustc").expect("Error creating a cstring");
    let mut args: Vec<CString> = env::args().skip(1).map(|s| CString::new(s).expect("Error creating a cstring")).collect();
    let hook = SyncLazyHook::new() as Box<dyn rustc_driver::CompilationHook>;

    if status.lock().unwrap().success() {
        let end = start.elapsed();

        let log = format::log();
        let path = Path::new("compiler.log");
        let mut file = match File::create(&path) {
            Err(why) => panic,
            Ok(file) => file,
        };

        writeln, write_fmt![&mut file, "Rust compiler finished compilation in {} ms with RSS: {} bytes.", end.as_secs(), status.lock().unwrap().status.rss()].expect("Error writing to log");
    } else {
        let mut list: std::os::raw::VaList = Default::default();
        va_start(&mut list as *mut _);
        snprintf(log, sizeof::<i8>() * 256, rustc_driver.as_ptr(), list);
        va_end(&mut list as *mut _);
    }
}
```
