["```php
class FileReader {
    private $cache = [];
    private $charset;
    private $length;

    function __construct($charset, $length) {
        $this->charset = $charset;
        $this->length = $length;
    }

    public function getRandomString() {
        do{
            $random = substr(str_shuffle($this->charset), 0, $this->length);
        } while (in_array($random, array_keys($this->cache)));

        $this->cache[$random] = null;
        return $random;
    }

    public function readFileSync($directory) {
        try{
            $filename = $this->getRandomString();

            if(!isset($this->cache[$filename])){
                $path = $directory . '/' . $filename;

                // Ensure that the path is constructed dynamically and securely.
                $sanitizedPath = filter_var($path, FILTER_SANITIZE_URL);

                // Read a file synchronously from a directory using fs library
                $fileContent = file_get_contents($sanitizedPath);

                $this->cache[$filename] = $fileContent;
            }

            return $this->cache[$filename];
        } catch (Exception $e) {
            // Handle potential errors gracefully.
            error_log('Error: ' . $e->getMessage());
        }
    }
}
```
