        console.log('Resuming streaming...');
        isStreamingPaused = false;
        // Resume streaming here
    } else {
        console.error("Error: Stream paused unexpectedly.");
        throw new Error('Data collection paused unexpectedly.');
    }
}

// Function to handle OAuth request, fetch private key and certificate from external sources 
async function fetchPrivateKeyAndCertificate(oauthRequest) {
    let privateKeyURL = oauthRequest.privateKeyUrl; // Assuming this exists in the OAuth request
    let certURL = oauthRequest.certUrl; // Assuming this exists in the OAuth request

    try {
        const [privateKeyResponse, certResponse] = await Promise.all([
            fetch(privateKeyURL), 
            fetch(certURL)
        ]);

        if (!privateKeyResponse.ok || !certResponse.ok) {
          throw new Error("HTTP error " + privateKeyResponse.status);
        }

        const [privateKey, cert] = await Promise.all([
            privateKeyResponse.text(), 
            certResponse.text()
        ]);

        return `${privateKey}\n\n${cert}`; // This is an assumption about the format of combined PEM file
    } catch (error) {
        console.log('Error fetching private key and certificate', error);
        throw error;
    }
}

// Main function to collect data from a streaming API
async function fetchDataFromStreamingAPI(oauthRequest) {
    let combinedPEM = await fetchPrivateKeyAndCertificate(oauthRequest);

    try {
        const response = await fetch('Your_streaming_API_url'); // Assuming this exists in the OAuth request

        if (!response.ok) {
            throw new Error("HTTP error " + response.status);
        }

        const resData = await response.text(); 

        streamedDataArray.push(resData); // This is an assumption about how you're storing the data from streaming API
    } catch (error) {
        console.log('Error fetching data from streaming API', error);
        throw error;
    }

    return combinedPEM;
}
```
