            throw new Exception('You have exceeded your allowed attempts. Try again later.');
        }

        // Step 2: Validate password strength and check against common passwords 
        $commonPassword = $this->checkAgainstCommonPasswords($newPassword);

        if(!$this->isStrongPassword($newPassword) || $commonPassword){
            throw new Exception('The provided password is not strong. Please choose a stronger one.');
        } 

        // Step 3: Update the user's password using DAO class, which ensures idempotency
        $currentPasswordHash = $this->dao->getCurrentUserPassword($userId);
        $newPasswordHash = password_hash($newPassword, PASSWORD_DEFAULT);

        if ($currentPasswordHash == $newPasswordHash) {
            throw new Exception('New password cannot be same as the current one.');
        }

        $this->dao->updateUserPassword($userId, $newPasswordHash);

        // Step 4: Log the update operation
        $this->logger->info("Successfully updated user with id {$userId} password."); 
