['```cpp
#include <iostream>
#include <fstream>
#include <thread>
#include <vector>
#include <mutex>
#include <chrono>
#include <random>

// Assume energy and attack consumption for 2 attacks are constants
const int ATTACK_ENERGY[2] = {10, 20}; //energy required for each attack
int characterEnergy = 50; //initial energy level of the character
std::mutex mtx; // mutex to handle concurrent calls

void logAttack(int attackNumber) {
    static std::ofstream file("game_log.txt", std::ios_base::app); //open file for appending
    auto now = std::chrono::system_clock::now();
    auto time_t = std::chrono::system_clock::to_time_t(now);
    tm utc_tm = *gmtime(&time_t); //convert to UTC time

    std::lock_guard<std::mutex> lock(mtx); 
    file << "Attack: "<< attackNumber + 1 <<" at " << asctime(&utc_tm) << "\n";
}

void performAttack() {
    // Ensure thread-safety with a mutex
    std::lock_guard<std::mutex> lock(mtx); 

    if (characterEnergy < *std::min_element(std::begin(ATTACK_ENERGY), std::end(ATTACK_ENERGY))) {
        // Not enough energy to perform an attack, return immediately.
        return;
    }

    static thread_local std::random_device rd;  // obtain a random number from hardware
    static thread_local std::mt19937 gen(rd()); // seed the generator
    std::uniform_int_distribution<> distr(0, 1); // define the range for attack selection

    int attackNumber = distr(gen);
    characterEnergy -= ATTACK_ENERGY[attackNumber];
    logAttack(attackNumber);

    std::cout << "Performing Attack: "<< attackNumber + 1 << "\n";
    std::this_thread::sleep_for (std::chrono::seconds(9)); //cooldown period of 9 seconds
}
```
This code block includes a performAttack() function that ensures thread-safety using a mutex. It also uses the C++14 `std::uniform_int_distribution` to randomly select an attack and checks if the character has enough energy for it. If the character does not have enough energy, no attack is performed and the function returns immediately. The selected attack number is logged along with its timestamp in a file named `game_log.txt` using the C++ standard library's iostream and fstream libraries. The cooldown period of 9 seconds is implemented using the C++11 thread library's sleep_for function. This solution also manages memory usage efficiently by not storing unnecessary data and minimizing overhead during logging.
