import threading
from abc import ABC, abstractmethod
from typing import Any

class DataSource(ABC):  # External data source
    @abstractmethod
    def get_min(self) -> int:
        pass

    @abstractmethod
    def get_max(self) -> int:
        pass

class RandomValueGenerator:  
    def __init__(self, data_source: DataSource):
        self._data_source = data_source
        self.lock = threading.Lock()  # Ensures atomicity of operations for concurrent requests

    def validate(self) -> bool:
        with self.lock:  
            try:
                min_value = self._data_source.get_min()
                max_value = self._data_source.get_max()

                if min_value is None or max_value is None:
                    return False

                if not (isinstance(min_value, int) and isinstance(max_value, int)):
                    return False

                if max_value < min_value:  
                    return False

            except Exception as e:  # Catches any errors in the process of getting data from data source
                print('Error occurred while validating configuration:', str(e))
                return False

        return True

    def generate(self) -> Any:
        if not self.validate():  
            raise ValueError("Invalid Configuration")  # Validate before generating random values

        with self.lock:  
            min_value = self._data_source.get_min()
            max_value = self._data_source.get_max()

        return randint(min_value, max_value)  # Generate random values within the range
