['Here's a simplified example of how you might implement this in C. Note, for simplicity, we assume that our config file follows format `[section]\nkey=value`. Also, we are using POSIX API functions (fopen, fgets) and libc error handling for this example, but real-world applications should use a platform-independent way to handle errors such as errno.

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>

typedef struct {
    char *key;
    char *value;
} KeyValuePair;

typedef struct {
    char *name;
    KeyValuePair **pairs;
    size_t pairCount;
} Section;

int loadConfig(const char* path, Section ***sections) {
    FILE* f = fopen(path, "r");

    if (!f) {
        perror("Failed to open config file!");
        return errno;
    }

    char line[256];
    size_t sectionCount = 0;
    Section **sects = malloc(sizeof(Section *)); // Dynamically allocate memory for sections
    KeyValuePair **pairs = NULL;
    size_t pairCount = 0, pairCapacity = 0;

    while (fgets(line, sizeof(line), f)) {
        if (line[0] == '[' && line[strlen(line) - 2] == ']') { // Found a section
            sects = realloc(sects, ++sectionCount * sizeof(Section *));

            Section *sect = malloc(sizeof(Section)); // Allocate memory for the new section
            sect->name = strndup(&line[1], strlen(line) - 3); // Copy the name without brackets and newline
            sect->pairs = pairs;
            sect->pairCount = pairCount;

            sects[sectionCount - 1] = sect;
            pairs = NULL;
            pairCapacity = pairCount = 0; // Reset the current section's key-value pairs
        } else if (line[0] != '\n') { // Found a key-value pair
            KeyValuePair *pair = malloc(sizeof(KeyValuePair)); // Allocate memory for new pair

            char* equalsSign = strchr(line, '=');
            if (!equalsSign) continue; // Skip malformed lines

            *equalsSign = '\0';
            pair->key = strdup(line); // Copy the key
            pair->value = strdup(equalsSign + 1); // Copy the value

            pairs = realloc(pairs, ++pairCount * sizeof(KeyValuePair *));
            pairs[pairCount - 1] = pair;
        }
    }

    fclose(f);

    *sections = sects;
    return sectionCount; // Return number of sections
}
```
You can then call the function like this:

```c
int main() {
    Section **sections = NULL;
    int count = loadConfig("config.txt", &sections);

    if (count < 0) return EXIT_FAILURE; // Handle error in loading config

    printf("Loaded %d sections.\n", count);

    // Use the loaded sections and free them when you're done...
}
```
Please note that this is a very simplistic implementation, real-world applications will likely require more complex error handling and possibly even use external libraries for parsing. Also, remember to free the allocated memory after using it.
']

