void append_version(char* filename, const char* version, const char* filetype) {
    if (filename == NULL || *filename == '\0') return;

    int i = 0, j = strlen(filename);
    for (; j > 0 && filename[j-1] != '.'; --j, ++i); // find the last '.'

    char* new_name = (char*) malloc((strlen(version) + strlen(filetype) + 256)*sizeof(char)); // allocate memory for new name

    if (new_name != NULL){ 
        strcpy(new_name, filename); // copy old filename

        int k = 0;
        while(!isalnum(filename[k]) && filename[k] != '\0') ++k; // find first alphanumeric character in filename

        if (k > 0) new_name[j-1] = '_'; // replace '.' with '_'

        sprintf(&new_name[strlen(new_name)-1], "_v%s.%s", version, filetype); // append the version and file type

        if (strlen(new_name) <= 255){ 
            strcpy(filename, new_name); // copy the new name back to the original variable
        } else {
            printf("Filename too long\n");
        }
    } else {
        printf("Memory allocation failed\n");
    }

    free(new_name); // deallocate memory
}
