    /* Extract the fields from the JSON object */
    json_object *access_token_obj, *expires_in_obj, *token_type_obj;

    if (!json_object_object_get_ex(jobj, "access_token", &access_token_obj)) {
        fprintf(stderr, "Missing access token\n");
        goto out;
    }

    if (!json_object_object_get_ex(jobj, "expires_in", &expires_in_obj)) {
        fprintf(stderr, "Missing expires_in field\n");
        goto out;
    }

    if (!json_object_object_get_ex(jobj, "token_type", &token_type_obj)) {
        fprintf(stderr, "Missing token_type field\n");
        goto out;
    }

    /* Validate the fields */
    if (strcmp(json_object_get_string(token_type_obj), "Bearer")) {
        fprintf(stderr, "Invalid token type\n");
        goto out;
    }

    int expires_in = json_object_get_int(expires_in_obj);
    if (getCurrentTime() > expires_in) {
        fprintf(stderr, "Access token has expired\n");
        goto out;
    }

    /* Populate the OAuth2Token struct with validated data */
    token->access_token = strdup(json_object_get_string(access_token_obj));
    token->expires_in = expires_in;
    token->token_type = strdup("Bearer");

    ret = true;

out:
    /* Clean up */
    json_object_put(jobj);

    return ret;
}
