['Here's a basic example of how you could implement this using C# with some third party libraries for encryption/decryption and handling asynchronous operations. 

Please note that the following code is just a simple demonstration and may not cover all requirements mentioned above. It also lacks error checking and exception handling, which should be added according to your specific needs and coding standards. 

```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Memory;

public class DecryptionService {
    private readonly IMemoryCache _cache;
    private readonly IExternalDataSource _externalDataSource;

    public DecryptionService(IMemoryCache cache, IExternalDataSource externalDataSource) {
        _cache = cache;
        _externalDataSource = externalDataSource;
    }

    public async Task<string> DecryptMessageAsync(string encryptedMessage, string keyHex, string ivHex) {
        if (string.IsNullOrEmpty(encryptedMessage)) {
            throw new ArgumentException("Encrypted message cannot be null or empty");
        }

        var key = HexToByteArray(keyHex);
        var iv = HexToByteArray(ivHex);
        TripleDES tripleDes = CreateTripleDes(key, iv);

        // Decrypt the message
        byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);

        using (var msDecrypt = new MemoryStream(encryptedBytes)) {
            using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, tripleDes.CreateDecryptor(), CryptoStreamMode.Read)) {
                byte[] fromEncrypt = new byte[encryptedBytes.Length];
                int decryptedCount = await csDecrypt.ReadAsync(fromEncrypt, 0, fromEncrypt.Length);

                return Encoding.UTF8.GetString(fromEncrypt, 0, decryptedCount);
            }
        }
    }

    private TripleDES CreateTripleDes(byte[] key, byte[] iv) {
        var tripleDes = new TripleDESCryptoServiceProvider();

        // Set the key and IV of the Triple DES algorithm
        tripleDes.Key = key;
        tripleDes.IV = iv;

        return tripleDes;
    }

    private byte[] HexToByteArray(string hex) {
        if (hex == null || hex.Length % 2 != 0) throw new ArgumentException("Invalid hex string length");

        int numberChars = hex.Length / 2;
        byte[] bytes = new byte[numberChars];

        for(int i = 0; i < numberChars; ++i){
            bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
        }

        return bytes;
    }
}
```

