import java.util.concurrent.ConcurrentHashMap;

public class Deserializer {
    private static final Logger logger = LogManager.getLogger(Deserializer.class);

    // Load your classes from an external configuration source,
    // here it's just a simple hardcoded example:
    private static final Map<String, Class<?>> allowedClasses = new ConcurrentHashMap<>();
    static {
        allowedClasses.put("com.example.MyClass", MyClass.class); 
    }

    // Caching mechanism:
    private final Map<byte[], Object> cache = new ConcurrentHashMap<>(1024, 0.75f, Runtime.getRuntime().availableProcessors());

    public synchronized <T> T deserialize(byte[] bytes, Class<T> clazz) {
        // check if the class is allowed for deserialization:
        if (!allowedClasses.containsKey(clazz.getName())) {
            throw new RuntimeException("Class " + clazz.getName() + " is not allowed for deserialization");
        }

        // check cache first:
        Object cachedValue = cache.get(bytes);
        if (cachedValue != null) {
            logger.debug("Cache hit for class {}", clazz.getName());
            return clazz.cast(cachedValue);
        }

        // deserialize the byte array:
        try (ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
             ObjectInput in = new ObjectInputStream(bis)) {
             T object = clazz.cast(in.readObject());
             cache.put(bytes, object);  // add to cache
             return object;
        } catch (IOException | ClassNotFoundException e) {
            logger.error("Deserialization failed for class {}", clazz.getName(), e);
            throw new RuntimeException("Failed to deserialize bytes into a " + clazz.getName() + " instance", e);
        }
    }

