#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    double value;
} RecordType1;

typedef struct {
    char *name;
    float score;
} RecordType2;

// Global mutex for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

void* allocateMemory(size_t size, int recordType) {
    pthread_mutex_lock(&lock); // Lock the mutex before allocating memory

    void *ptr;

    if (recordType == 1) {
        ptr = malloc(sizeof(RecordType1) * size); 
    } else if (recordType == 2) {
        pthread_mutex_unlock(&lock); // Unlock the mutex before allocating memory for RecordType2
        return NULL;
    } else {
        printf("Invalid record type\n");
        pthread_mutex_unlock(&lock); // Unlock the mutex if an invalid record type is provided
        return NULL;
    }

    // If allocation fails, free the locked memory and unlock the mutex before returning
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&lock); 
        return NULL;
    }

    // Initialize the allocated memory
    memset(ptr, 0, size);

    pthread_mutex_unlock(&lock); // Unlock the mutex after memory allocation and initialization

    return ptr;
}
```
This function takes in the size of memory to be allocated and a record type. It locks a global mutex before allocating memory and unlock it after deallocating or returning without deallocating if allocation fails. For demonstration, it only handles two types of records (RecordType1 and RecordType2). You'll need to extend this based on your requirements.
']

