int main() {
    // Assume the limit is known, for example as an environment variable
    size_t memLimit = getenv("MEMORY_LIMIT") ? atoi(getenv("MEMORY_LIMIT")) : 0;

    if (!memLimit) {
        fprintf(stderr, "Memory limit not set or invalid\n");
        return EXIT_FAILURE;
    }

    // Allocate and initialize arrays
    long *offsets = malloc(sizeof(long));
    if (!offsets) {
        perror("Failed to allocate memory for offsets");
        return errno;
    }

    int *keys = calloc(1, sizeof(int));
    if (!keys) {
        free(offsets); // Free already allocated resources
        perror("Failed to allocate memory for keys");
        return errno;
    }

    Record *records = malloc(sizeof(Record));
    if (!records) {
        free(offsets);
        free(keys); // Free already allocated resources
        perror("Failed to allocate memory for records");
        return errno;
    }

    // Check total memory usage
    size_t totalMemUsage = sizeof(long) + sizeof(int) + sizeof(Record);

    if (totalMemUsage > memLimit) {
        free(offsets);
        free(keys);
        free(records);
        fprintf(stderr, "Total memory usage exceeded the limit\n");
        return EXIT_FAILURE;
    }

    // Initialize Java Channel and establish a connection to remote address
