['Here's how you could implement your requirements using Java for the hashing, C++ for random number generation, and RESTful API communication in a microservices architecture:

Java part (MD5 hash with caching):
```java
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.concurrent.locks.ReentrantLock;

public class MD5Hasher {
    private static final HashMap<String, String> cache = new HashMap<>();
    private static final ReentrantLock lock = new ReentrantLock();

    public static String getMD5Hash(String str) throws Exception {
        lock.lock();
        try {
            if (cache.containsKey(str)) return cache.get(str);

            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(str.getBytes(StandardCharsets.UTF_8));

            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }

            String hash = sb.toString();
            if (cache.size() < 10_000) cache.put(str, hash); // Cache up to 10,000 hashes
            return hash;
        } finally {
            lock.unlock();
        }
    }
}
```
C++ part (Random number generation):
```cpp
#include <random>
#include <mutex>

namespace MyNamespace {

class RandomGenerator {
private:
    std::mt19937 generator;
    static std::mutex mtx;  // mutex for locking when generating random numbers.
public:
    RandomGenerator() : generator(std::random_device{}()) {}
    ~RandomGenerator() = default;
    int generateNumber(int min, int max) {
        std::lock_guard<std::mutex> guard(mtx);  // lock mutex for thread safety.
        std::uniform_int_distribution<> distr(min, max);
        return distr(generator);
    }
};
}
```
