```Java
import java.util.*;

class UnionFind {
    private int[] parent; 
    private int[] rank; 

    public UnionFind(int size) { 
        parent = new int[size]; 
        rank = new int[size]; 
        for (int i = 0; i < size; i++) {
            parent[i] = i; 
        }
    }

    public int find(int x) { 
        if (parent[x] != x) {
            parent[x] = find(parent[x]); 
        }
        return parent[x]; 
    }

    public void union(int x, int y) { 
        int xroot = find(x), yroot = find(y); 
        if (rank[xroot] < rank[yroot]) {
            parent[xroot] = yroot; 
        } else if (rank[xroot] > rank[yroot]) {
            parent[yroot] = xroot; 
        } else {
            parent[yroot] = xroot; 
            rank[xroot]++; 
        } 
    }
}

public class DisjointPairsCounter {
    private UnionFind uf;

    public DisjointPairsCounter(int size) {
        this.uf = new UnionFind(size);
    }

    public int countDisjointPairs(int[] arr, boolean printTime) {
        long start = System.currentTimeMillis(); 

        Set<Integer> seen = new HashSet<>();
        for (int i = 0; i < arr.length - 1; i++) {
            if (!seen.contains(uf.find(arr[i]))) {
                seen.add(uf.find(arr[i]));
            } else {
                uf.union(arr[i], arr[i+1]);
            }
        }

        long end = System.currentTimeMillis(); 
        if (printTime) {
            System.out.println("Time taken: " + (end - start)); 
        }

        return seen.size();
    }
}
```

