```c
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <fcntl.h>
#include <errno.h>
#include <stdlib.h>

#define MAX_LEN 255

int changeFileExt(char *filename, char *command) {
    if (filename == NULL || strlen(filename) == 0) {
        printf("Error: Invalid filename\n");
        return -1;
    }

    // Check for invalid characters in the filename
    if (strcspn(filename, "/\\*?\"<>|") < strlen(filename)) {
        printf("Error: Filename contains invalid characters\n");
        return -1;
    }

    char *dot = strrchr(filename, '.');
    size_t len = 0;
    if (dot != NULL) {
        len = dot - filename + 1;  // length of the extension including '.'
    } else {
        len = strlen(filename);
    }

    char *newFilename = malloc(MAX_LEN + 1);  
    if (newFilename == NULL) {
        printf("Error: Memory allocation failed\n");
        return -1;
    }

    memset(newFilename, 0, MAX_LEN + 1);
    sprintf(newFilename, "%.*s.%zu", (int)len, filename, len);

    if (strlen(newFilename) > MAX_LEN) {
        printf("Error: New filename exceeds maximum length\n");
        free(newFilename);
        return -1;
    }

    strcat(newFilename, ".txt");  

    FILE *file = fopen(newFilename, "w");
    if (file == NULL) {
        printf("Error: Failed to open file\n");
        free(newFilename);
        return -1;
    }

    fclose(file);

    pid_t pid = fork();
    if (pid == 0) {  // Child process
        execl("/bin/sh", "sh", "-c", command, NULL);
        exit(EXIT_FAILURE);  
    } else if (pid < 0) {
        printf("Error: Fork failed\n");
        free(newFilename);
        return -1;
    } 

    int status;
    wait(&status);
    if (!WIFEXITED(status) || WEXITSTATUS(status)) {
        printf("Error: Command execution failed\n");
        free(newFilename);
        return -1;
    } else {
        free(newFilename);
        return 0;  // Successful command execution
    }
}
```
This function uses fork to execute a given command in the background. It also checks for errors during memory allocation, file creation and command execution, and returns appropriate status codes as per requirement. Please note that this code does not handle all possible edge cases or system dependencies, which would require more robust error checking and handling based on specific use-cases.
']

