typedef struct {
    char *input_file;
    char *output_file;
    char *rules;
    int buffer_size;
    int log_level;
} CommandLineArgs;

CommandLineArgs parseArguments(int argc, char **argv){
    // Implementation to parse command line arguments.
}

void processFile(const CommandLineArgs args) {
    FILE *input = fopen(args.input_file, "rb");
    if (input == NULL) {
        printf("Failed to open input file %s\n", args.input_file);
        exit(1);
    }

    gzFile decompressedInput = gzdopen(fileno(input), "rb");
    if (decompressedInput == NULL) {
        printf("Failed to open decompress input file %s\n", args.input_file);
        exit(1);
    }

    FILE *output = fopen(args.output_file, "wb");
    if (output == NULL) {
        printf("Failed to open output file %s\n", args.output_file);
        exit(1);
    }

    char *buffer = malloc(args.buffer_size);
    int bytesRead;
    while ((bytesRead = gzread(decompressedInput, buffer, args.buffer_size)) > 0) {
        // Apply rules to buffer

        fwrite(buffer, 1, bytesRead, output);
    }

    free(buffer);
    gzclose(decompressedInput);
    fclose(input);
    fclose(output);
}

int main(int argc, char **argv) {
    CommandLineArgs args = parseArguments(argc, argv);

    clock_t startTime = clock();
    processFile(args);
    double elapsedSeconds = (double)(clock() - startTime) / CLOCKS_PER_SEC;

    if (args.log_level > 0) {
        printf("Processed file %s in %f seconds\n", args.input_file, elapsedSeconds);
    }

    return 0;
}
```
