```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <jansson.h> // JSON parsing library
#include <applog.h> // Logging library

typedef struct {
    long timestamp;
    void* address;
} allocation_info_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
allocation_info_t** allocations;
int num_allocations = 0;
int max_memory = 1024 * 1024 * 1024; // Default maximum memory limit is 1 GB
char* config_file = "config.json";
time_t last_write_timestamp;

// Function to parse JSON configuration file and apply settings
void parse_configuration(const char* filename) {
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);

    // Handle parsing errors
    if(!root) {
        fprintf(stderr, "Failed to parse JSON: %s\n", error.text);
        return;
    }

    json_t *max_memory_setting = json_object_get(root, "max_memory");
    max_memory = json_integer_value(max_memory_setting);

    // Handle other settings here...
}

// Function to allocate memory for a new record
void* allocate_record(size_t size) {
    pthread_mutex_lock(&lock);
    if (num_allocations * sizeof(*allocations) + size > max_memory) {
        fprintf(stderr, "Memory limit exceeded!\n");
        return NULL;
    }

    // Allocate memory and add to tracking list
    void* address = malloc(size);
    allocation_info_t* info = malloc(sizeof(*info));
    info->timestamp = time(NULL);
    info->address = address;
    allocations[num_allocations++] = info;

    log_debug("Allocated %zu bytes at %p", size, address);

    pthread_mutex_unlock(&lock);
    return address;
}

// Function to track record write activity
void update_last_write_timestamp() {
    last_write_timestamp = time(NULL);
}

// Function to periodically check for inactivity and free up allocated memory
void* monitor_inactivity() {
    while (1) {
        pthread_mutex_lock(&lock);
        time_t current_time = time(NULL);

        // Free all records not written in the last 10 seconds
        for (int i = 0; i < num_allocations; ++i) {
            if (current_time - allocations[i]->timestamp > 10) {
                free(allocations[i]->address);
                free(allocations[i]);

                // Shift remaining records to fill the gap
                for (int j = i; j < num_allocations - 1; ++j)
                    allocations[j] = allocations[j + 1];

                --num_allocations;
            }
        }

        pthread_mutex_unlock(&lock);
        sleep(10); // Check every 10 seconds
    }
}

// Main function to demonstrate functionality
int main() {
    allocations = malloc(max_memory / sizeof(*allocations));

    parse_configuration(config_file);

    void* record = allocate_record(sizeof(char) * 1024); // Allocate a new record

    update_last_write_timestamp(); // Update timestamp to indicate activity

    pthread_t thread;
    pthread_create(&thread, NULL, monitor_inactivity, NULL); // Start inactivity monitoring thread

    sleep(15); // Simulate inactivity period (no write in the last 10 seconds)

    void* record2 = allocate_record(sizeof(char) * 1024); // Allocate a new record after inactivity

    update_last_write_timestamp(); // Update timestamp to indicate activity again

    sleep(5); // Allow some time for memory cleaning

    pthread_cancel(thread); // Stop the monitoring thread
}
```

This code represents a basic framework to achieve your requirements. Please note that you would need additional code to handle the specifics of each record type, parse JSON configuration files correctly, and implement compression if necessary. Additionally, this example does not handle all edge cases for thread safety and error checking. You should thoroughly test this code in an actual environment before using it in a production system.
