#include <time.h>
#define MAX_MEMORY_USAGE 1024 * 1024 * 1024 // 1GB

typedef struct {
    double value;
    char* label;
} data_point;

int create_data_points(int num_points, double min, double max, data_point** points) {
    if (num_points <= 0 || max <= min) {
        return 1; // Invalid input
    }

    size_t memory_usage = sizeof(data_point*) + num_points * sizeof(data_point);
    if (memory_usage > MAX_MEMORY_USAGE) {
        return 2; // Memory limit exceeded
    }

    srand((unsigned int)time(NULL));

    *points = calloc(num_points, sizeof(data_point));
    if (*points == NULL) {
        return 3; // Out of memory
    }

    for (int i = 0; i < num_points; i++) {
        double random_value = min + ((double)rand() / RAND_MAX) * (max - min);
        (*points)[i].value = random_value;

        char* label = malloc(16); // Allocate memory for the label
        if (label == NULL) {
            free(*points);  // Free previously allocated points
            return 3; // Out of memory
        }

        sprintf(label, "Point %d", i + 1); // Set the label dynamically
        (*points)[i].label = label;
    }

    return 0; // Success
}

void free_data_points(data_point* points, int num_points) {
    for (int i = 0; i < num_points; i++) {
        free(points[i].label); // Free the dynamically allocated label
    }

    free(points);  // Free the data points array
}
```
