    sem_t semaphore;       // Semaphore for managing concurrent access
    size_t recordSize;     // Size of each record in bytes
    int numRecords;        // Number of records to allocate memory for
} MemoryConfig;

// Allocate and initialize dynamic array of structures based on input parameters
void *allocateMemory(RecordType *recordTypes, MemoryConfig *config) {
    pthread_mutex_init(&config->mutex, NULL);  // Initialize mutex
    sem_init(&config->semaphore, 0, 1);        // Initialize semaphore with initial value of 1

    // Calculate the total size needed for all records including metadata
    config->recordSize = 0;
    for (int i = 0; i < recordTypes->numFields; ++i) {
        config->recordSize += sizeof(RecordField);
    }

    void *memory = malloc(config->recordSize * config->numRecords);  // Allocate memory for all records
    if (memory == NULL) {
        return NULL;  // Return an error code in case of allocation failure
    }

    pthread_mutex_lock(&config->mutex);  // Lock the mutex before accessing shared resource
    sem_wait(&config->semaphore);        // Decrease the semaphore count to control concurrent access

    RecordField *records = (RecordField *)memory;  // Cast the memory pointer into RecordField type
    for (int i = 0; i < config->numRecords; ++i) {
        records[i] = malloc(sizeof(RecordField) * recordTypes->numFields);  // Allocate memory for each field in a record

        // Initialize the fields based on provided definitions
        for (int j = 0; j < recordTypes->numFields; ++j) {
            records[i][j].data = malloc(recordTypes->fields[j]->size);  // Allocate memory for field data
            memcpy(records[i][j].data, recordTypes->fields[j]->data, recordTypes->fields[j]->size);  // Copy the provided initial value to the allocated memory
        }
    }

    pthread_mutex_unlock(&config->mutex);  // Unlock the mutex after accessing shared resource
    sem_post(&config->semaphore);          // Increase the semaphore count after use

    return records;  // Return a pointer to the allocated memory
}
