```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Record {
    int value;
    struct Record* next;
};

int init_records(long offsets[], int keys[], struct Record** records, int max_memory_usage) {
    // Allocate memory for arrays
    *records = malloc(sizeof(struct Record) * 500);
    if (*records == NULL) return -1;  // Memory allocation failed

    long* offsets = calloc(1000, sizeof(long));
    if (offsets == NULL) {
        free(*records);
        return -1;  // Memory allocation failed
    }

    int* keys = malloc(sizeof(int) * 1000);
    if (keys == NULL) {
        free(*records);
        free(offsets);
        return -1;  // Memory allocation failed
    }

    // Initialize linked list
    struct Record* current = *records;
    for (int i = 0; i < 499; ++i) {
        current->next = current + 1;
        ++current;
    }
    current->next = NULL;  // Mark end of linked list

    // Initialize records with random values in range [0, RAND_MAX]
    srand(time(NULL));  // Seed the random number generator
    for (struct Record* record = *records; record != NULL; record = record->next) {
        record->value = rand();
    }

    int total_memory_usage = sizeof(*records) + sizeof(offsets) + sizeof(keys);

    if (total_memory_usage > max_memory_usage) {
        free(*records);
        free(offsets);
        free(keys);
        return -2;  // Memory usage exceeds limit
    }

    return 0;  // Success
}
```
In this implementation, the total memory used is calculated as `sizeof(*records) + sizeof(offsets) + sizeof(keys)`. This does not account for any potential additional overhead from dynamic allocation or structure padding. To get a more accurate measurement, you'd need to use tools like Valgrind or implement your own tracking function. 

The linked list nodes are allocated as a contiguous block of memory using `calloc()`, which zeros out the memory for us. This simplifies initialization and reduces the risk of leaking uninitialized memory. If this was not acceptable, we'd need to loop over each node in the list and initialize its fields individually. 

Note that error handling is very basic - if any allocation fails, all previously allocated memory will be freed before returning an error code. A more robust implementation would likely include separate checks for each allocation, allowing partial deallocation of resources only when appropriate. This approach could be made even more complex by implementing a custom dynamic data structure to manage the linked list nodes, adding extra error checking and handling potential issues with memory fragmentation.
