public class GraphManager {
    private static final Random rand = new Random();

    public void addVerticesAndEdges(Graph graph, int numVertices, int maxNumEdges) {
        List<Vertex> vertices = new ArrayList<>();

        // Add vertices
        for (int i = 0; i < numVertices; i++) {
            Vertex v = graph.addVertex("property1", "value" + i, "property2", rand.nextInt());
            vertices.add(v);
        }

        // Add random edges (up to maxNumEdges per vertex)
        for (int i = 0; i < numVertices; i++) {
            Vertex from = vertices.get(i);

            int numEdges = rand.nextInt(maxNumEdges + 1); // add between 0 and maxNumEdges edges per vertex
            for (int j = 0; j < numEdges && !vertices.isEmpty(); j++) {
                Vertex to = vertices.get(rand.nextInt(vertices.size()));

                if (from != to) { // do not create self-loops
                    from.addEdge("edge" + i, to);
                }
            }
        }
    }
}
