void removeByIndex(int index) {
    pthread_mutex_lock(&lock);

    if (index >= count || index < 0) {
        printf("Error: index out of bounds!\n");
        return;
    }

    free(list[index]);

    for (int i = index; i < count - 1; i++) {
        list[i] = list[i + 1];
    }

    list[--count] = NULL;

    pthread_mutex_unlock(&lock);
}
