void getEmployeeInfo(char* supervisorID) {
    sqlite3 *db;
    char *errMsg = 0;

    int rc = sqlite3_open("test.db", &db);  // Open connection to database

    if (rc != SQLITE_OK) {
        fprintf(stderr, "Cannot open database: %s\n", sqlite3_errmsg(db));
        return;
    }

    char *query = sqlite3_mprintf("SELECT name, city, address FROM Employees WHERE supervisorID='%q';", supervisorID);  // Prevent SQL injection
    rc = sqlite3_exec(db, query, NULL, NULL, &errMsg);

    if (rc != SQLITE_OK) {
        fprintf(stderr, "Failed to execute statement: %s\n", errMsg);
        return;
    } 

    sqlite3_free(query);  // Free memory used by query string
    sqlite3_close(db);  // Close connection to database
}
