    try{
        userDao.updateUserPassword(userId, newPassword);
    } catch (Exception e) {
        printf("Error occurred while updating the password: %s\n", e.getMessage());
        return;
    }

    // send notification to user about password update
    try{
        NotificationAPI api = new NotificationAPI();
        api.sendNotification(userId, "Your Password has been updated");
    } catch (ConnectionTimeoutException e) {
        printf("Connection Timeout occurred\n");
    } catch (AuthenticationFailureException e) {
        printf("Authentication Failed: %s\n", e.getMessage());
    } catch (RetryLimitExceededException e) {
        printf("All retries exhausted while trying to send notification\n");
    } catch (Exception e) {
        printf("Unexpected error occurred while sending notification: %s\n", e.getMessage());
    }

    // log details of password update
    printf("User with ID: %d has updated their password\n", userId);
    int strength = calculatePasswordStrength(newPassword);
    printf("New Password Strength Rating: %d\n", strength);
}
