```rust
use std::sync::Arc;
use log;
use http;

type LongOffset = i64;
type IntKey = i32;
type DoubleValue = f64;
type RecordStructure = Arc<Vec<(IntKey, DoubleValue)>>;

#[derive(Debug)]
struct MemoryManager {
    memory_size: LongOffset,
}

impl MemoryManager {
    fn new() -> Self {
        MemoryManager {
            memory_size: 0,
        }
    }

    fn allocate(&mut self, size: usize) -> *const RecordStructure {
        let layout = std::alloc::Layout::array::<(IntKey, DoubleValue)>(size);
        let ptr = unsafe { std::alloc::alloc(layout) };
        if ptr.is_null() {
            log::error("Failed to allocate memory");
            return ptr;
        }
        self.memory_size += size as LongOffset;
        log::info(&format![ "Memory allocated, total: {}", self.memory_size]);
        ptr
    }

    fn deallocate(&mut self, pointer: *const RecordStructure, size: usize) {
        if !pointer.is_null() {
            unsafe { std::alloc::dealloc(pointer as *mut (IntKey, DoubleValue), layout); };
            self.memory_size -= size as LongOffset;
            log::info(&format![ "Memory deallocated, total: {}", self.memory_size]);
        }
    }
}

