```C
#include <pthread.h>
#include <glib.h>
#include <stdlib.h>
#include <time.h>

#define MAX_CCCI 1000
#define CRC_FLAG_CHANCE 50 // chance out of 100 that the crc flag will be set to true

typedef struct {
    char UEID[20];
    int numCCEs;
    char CCEs[10][20];
    bool CRCFlag;
    time_t lastAccessed;
} CCCI;

GHashTable* hashTable;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* init_hash_table() {
    // Initialize the hash table with string keys and pointer values
    return g_hash_table_new(g_str_hash, g_str_equal);
}

CCCI* create_ccci(char* UEID) {
    if (g_hash_table_contains(hashTable, UEID)) {
        fprintf(stderr, "UEID already exists in the hash table\n");
        return NULL;
    }

    CCCI* newCcci = malloc(sizeof(CCCI));
    if (newCcci == NULL) {
        fprintf(stderr, "Failed to allocate memory for new CCCI structure\n");
        return NULL;
    }

    strcpy(newCcci->UEID, UEID);
    newCcci->numCCEs = 0;
    // generate random CRC flag
    srand((unsigned int) time(NULL));
    newCcci->CRCFlag = rand() % 100 < CRC_FLAG_CHANCE;

    return newCcci;
}

bool add_to_hash_table(CCCI* ccci) {
    pthread_mutex_lock(&mutex);
    if (g_hash_table_size(hashTable) >= MAX_CCCI) {
        fprintf(stderr, "Maximum number of CCCI structures reached\n");
        return false;
    }

    g_hash_table_insert(hashTable, ccci->UEID, ccci);
    pthread_mutex_unlock(&mutex);
    return true;
}
```
