typedef struct Node {
    LTE_UeradioResourceStatus_t data;
    struct Node* next;
} Node_T;

Node_T* head = NULL;
int size = 0;

void insert(LTE_UERadioResourceStatus_T newData) {
    Node_T *newNode = (Node_T*) malloc(sizeof(Node_T));

    if(!newNode) {  // Check for memory allocation error.
        printf("Failed to allocate memory.\n");
        return;
    }

    newNode->data = newData;
    newNode->next = head;
    head = newNode;
    size++;
}

void delete(int UE_ID) {
    Node_T *temp = head, *prev = NULL;

    if (temp != NULL && temp->data.UE_ID == UE_ID) {  // Check if the node to be deleted is at the head of the list.
        head = temp->next;
        free(temp);
        size--;
        return;
    }

    while (temp != NULL && temp->data.UE_ID != UE_ID) {  // Search for the node to be deleted.
        prev = temp;
        temp = temp->next;
    }

    if(temp == NULL) {  // If the key was not present in linked list.
        printf("The given UE_ID is not found.\n");
        return;
    }

    prev->next = temp->next;  // Bypass the node to be deleted from the linked list.
    free(temp);  // Free memory of the node that has been removed.
    size--;
}

