['The following is a simplified version of how you could implement this function using the standard library functions for resolving DNS in C. This code uses a simple counter to limit concurrent queries, but doesn't integrate with a configuration management system or log robust details about each query. Also, note that it does not actually handle memory usage limits or timeouts; these would need significant modifications to this function or additional threading and synchronization mechanisms:

```c
#include <stdio.h>
#include <string.h>
#include <netdb.h>
#include <arpa/inet.h>

int resolve_host(const char *hostname, u_char *ip_address, size_t ip_len, int timeout_ms, size_t max_concurrent_queries, size_t max_memory_usage_kb) {
    static size_t concurrency_counter = 0;

    if (hostname == NULL || ip_address == NULL || ip_len == 0) {
        return -1;  // Invalid input parameters.
    }

    if(concurrency_counter >= max_concurrent_queries){
        return -4; // Concurrent queries limit exceeded
    }
    ++concurrency_counter;

    struct hostent *he = gethostbyname(hostname);
    if (he == NULL) {
        --concurrency_counter;
        herror("gethostbyname");
        return -3;  // DNS resolution failure.
    }

    char ip[INET6_ADDRSTRLEN];
    struct in_addr **addr_list = (struct in_addr **)he->h_addr_list;
    for(int i = 0; addr_list[i] != NULL; ++i){
        strncpy(ip, inet_ntoa(*addr_list[i]), ip_len);
        ++addr_list[i];
    }

    if (strlen(ip) > ip_len - 1) {
        --concurrency_counter;
        return -2;  // Memory allocation failure.
    }

    strncpy((char *)ip_address, ip, ip_len);
    --concurrency_counter;

    return 0;
}
```
This code has some limitations and doesn't cover all edge cases and potential errors gracefully. It only supports IPv4 addresses and does not support IPv6 or other advanced features of DNS resolution. Also, it assumes that `gethostbyname` will always be able to allocate enough memory for the IP address without exceeding the specified limits.
']

