typedef struct MAC_Header {
    unsigned char address[6];
} MAC_Header;

typedef struct PHY_Header {
    int length;
} PHY_Header;

typedef struct Data_Payload {
    void *data;
} Data_Payload;

typedef struct L2_Packet {
    MAC_Header mac;
    PHY_Header phy;
    Data_Payload payload;
} L2_Packet;

int generate_packets(L2_Packet **packets, int initial_size) {
    srand((unsigned int) time(NULL));
    int total = 0;

    *packets = (L2_Packet *) malloc(initial_size * sizeof(L2_Packet));
    if (*packets == NULL) return -1;  // Memory allocation failure

    unsigned char last_mac[6] = {0};
    while (total < initial_size) {
        L2_Packet packet;

        // Generate unique MAC address
        for(int i = 0; i < 6; i++) {
            do {
                packet.mac.address[i] = rand() % 256;
            } while (packet.mac.address[i] == last_mac[i]);
        }

        // Copy the address to compare later
        memcpy(last_mac, packet.mac.address, sizeof(unsigned char) * 6);

        packet.phy.length = 100 + rand() % (1000 - 100 + 1);
        if ((total + 1) * packet.phy.length > 1500) break; // If total size exceeds, stop creating packets

        packet.payload.data = malloc(packet.phy.length);
        if (packet.payload.data == NULL) return -2;  // Memory allocation failure

        *((*packets) + total) = packet;  // Copy to array
        total++;

        if (total >= initial_size) {
            L2_Packet *temp = realloc(*packets, sizeof(L2_Packet) * total * 2);  // Reallocate more space
            if (temp == NULL) return -1;  // Memory allocation failure
            else *packets = temp;
        }
    }

    return total;  // Return number of successfully generated packets
}
```
