typedef struct {
    int key;
    float value;
    char string[16];
} dataRecord;

void *generateData(void *arg) {
    long offset = (long)arg;
    srand((unsigned int)time(NULL) + offset);

    long *offsets = malloc(sizeof(long) * 3);
    for (int i = 0; i < 3; ++i) {
        offsets[i] = rand();
    }

    int *keys = malloc(sizeof(int) * 3);
    float *values = malloc(float, sizeof(float) * 3);
    for (int i = 0; i < 3; ++i) {
        keys[i] = rand() % 100; // Within a range of 0-99
        values[i] = (float)(rand() % 100) / 10.0f; // Within a range of 0-9.9
    }

    dataRecord *records = malloc(sizeof(dataRecord) * 3);
    for (int i = 0; i < 3; ++i) {
        records[i].key = keys[i];
        records[i].value = values[i];

        // Generate a random string of fixed length
        for (int j = 0; j < sizeof(records[i].string); ++j) {
            int c = rand() % 26 + 'a';
            records[i].string[j] = c;
        }
    }

    // Sort the dataRecord array based on key field using a stable sort algorithm
    qsort(records, 3, sizeof(dataRecord), [](const void *a, const void *b) {
        int lhs = ((const dataRecord*)a)->key;
        int rhs = ((const dataRecord*)b)->key;
        return (lhs > rhs) - (lhs < rhs);  // could be replaced with a stable sorting algorithm for performance improvements
    });

    free(offsets);
    free(keys);
    free(values);

    return records;
}

int main() {
    pthread_t threads[3];
    long offsets[3] = {0, 1, 2};

    // Generate and sort data in parallel using three threads
    for (int i = 0; i < 3; ++i) {
        if (pthread_create(&threads[i], NULL, generateData, (void*)offsets[i]) != 0) {
            printf("Failed to create thread\n");
            return 1;
        }
    }

    dataRecord *records[3];
    for (int i = 0; i < 3; ++i) {
        if (pthread_join(threads[i], (void**)&records[i]) != 0) {
            printf("Failed to join thread\n");
            return 1;
        }
    }

    // Use the generated and sorted data...

    for (int i = 0; i < 3; ++i) {
        free(records[i]);
    }

    return 0;
}
