typedef struct {
    char *title;
    char *author;
    int publication_year;
    double rating;
} Book;

unsigned long total_memory = 0;
const unsigned long MAXIMUM_MEMORY = 1024 * 1024; // 1 MB

int book_array(char* password, size_t length, char* charset, Book** books) {
    if (total_memory + sizeof(Book) > MAXIMOMUM_MEMORY) {
        return -1; // exceeded maximum memory limit
    }

    *books = malloc(sizeof(Book) * length);
    if (*books == NULL) {
        return -2; // error during allocation
    }
    total_memory += sizeof(Book) * length;

    unsigned char hash[SHA_DIGEST_LENGTH];
    SHA1((unsigned char*)password, strlen(password), hash);

    srand(time(NULL)); // initialize random seed for rand()

    for (size_t i = 0; i < length; ++i) {
        (*books)[i].title = malloc(sizeof(char) * 100);
        (*books)[i].author = malloc(sizeof(char) * 50);

        if ((*books)[i].title == NULL || (*books)[i].author == NULL) {
            return -2; // error during allocation
        }
        total_memory += sizeof(char) * 150;

        for (size_t j = 0; j < 99; ++j) {
            (*books)[i].title[j] = charset[rand() % strlen(charset)];
        }
        (*books)[i].title[99] = '\0'; // null terminate the string

        for (size_t j = 0; j < 49; ++j) {
            (*books)[i].author[j] = charset[rand() % strlen(charset)];
        }
        (*books)[i].author[49] = '\0'; // null terminate the string

        (*books)[i].publication_year = 1900 + rand() % 200; // random year from 1900 to 2099
        (*books)[i].rating = (double)rand() / RAND_MAX * 5.0; // random rating between 0 and 5
    }

    return 0; // success
}

void free_memory(Book* books, size_t length) {
    for (size_t i = 0; i < length; ++i) {
        if (books[i].title != NULL) {
            free(books[i].title);
        }
        if (books[i].author != NULL) {
            free(books[i].author);
        }
    }
    total_memory -= sizeof(Book) * length;

    free(books);
    total_memory -= sizeof(Book) * length;
}
```

