["Here is a simple implementation in C using POSIX threads for thread safety, pthread_mutex_t for locking, and gcc's __sync_* atomic built-ins for maintaining counts and sizes. Note that real-world usage would require more comprehensive error checking and logging mechanisms. The maximum size of the list is set to 1000 as per your requirement:

```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <stdatomic.h>

#define MAX_SIZE 1000

typedef struct {
    char UEID[256];
    void* CCEs; // Assume each CCE takes up a large amount of memory, not shown here for simplicity
} CCCI;

// Global variables
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static atomic_uint count = 0;
static CCCI* list[MAX_SIZE];
static char hashTable[4096][256] = { 0 }; // Assume a simple hash table with fixed size of 4096 for demonstration

// Add an item to the list
void addItem(const char* UEID, void* CCEs) {
    assert(UEID != NULL);

    pthread_mutex_lock(&mutex);
    if (count >= MAX_SIZE) {
        // Log error: list is full
        goto exit;
    }

    const unsigned hash = __sync_fetch_and_add(&count, 1);
    assert(hash < MAX_SIZE);

    for (size_t i = 0; i < 4096; ++i) {
        if (strcmp(hashTable[i], UEID) == 0) {
            // Log error: duplicate UEID
            goto exit;
        }
    }

    list[hash] = malloc(sizeof(CCCI));
    strncpy(list[hash]->UEID, UEID, sizeof(list[hash]->UEID) - 1);
    list[hash]->CCEs = CCEs; // Assume proper handling of CCEs data structure

exit:
    pthread_mutex_unlock(&mutex);
}
```

Please note that this code is a simple demonstration and doesn't cover all your requirements. It assumes a fixed size for simplicity but in a real-world scenario, it would be better to use dynamic memory allocation or consider other data structures like balanced trees or hash tables. Also, proper error checking should be used when accessing list items to avoid segmentation faults.
