```rust
use std::sync::Arc;
use std::collections::HashMap;
use hyper::{Client, Uri};
use once_cell::sync::Lazy;
use parking_lot::Mutex;

static HTTP_CLIENT: Lazy<Mutex<Option<Client<hyper::client::HttpConnector>>>> = Lazy::new(|| Mutex::new(None));

struct Record {
    int_value: i32,
    double_value: f64,
}

impl Record {
    fn new(int_value: i32, double_value: f64) -> Self {
        Self {
            int_value,
            double_value,
        }
    }
}

fn get_client() -> Client<hyper::client::HttpConnector> {
    let client = HTTP_CLIENT.lock().unwrap();
    match *client {
        Some(ref c) => c.clone(),
        None => {
            let https_connector = hyper::client::HttpsConnector::new()
                .map_err(|e| format_error_message("Error creating HTTP client", e))?;

            let client = Client::builder()
                .build::<_, hyper::Body>(https_connector);

            *client = Some(client);
            client.clone().unwrap()
        }
    }
}

fn create_request(url: &str, disable_certificate_validation: bool) -> Result<hyper::Request<hyper::Body>, Error> {
    let uri = Uri::try_from(url)?;

    if disable_certificate_validation {
        // Create an HTTP client that disables certificate validation. This is a simplified example and not practical in real-world scenarios due to security concerns. 
        let https_connector = hyper::client::HttpsConnector::new()
            .map_err(|e| format_error_message("Error creating HTTP client", e))?;

        let client = Client::builder().build::<_, hyper::Body>(https_connector);
    } else {
        let client = get_client();
    }

    Ok(client.get(uri).body(hyper::Body::empty()).unwrap())
}
```

