['Here is a simplified example of how you could implement this in C. This does not include all the details and design choices you specified but it provides an overall layout for what your function could look like:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    uint32_t ueid;
    uint8_t cces[10];
    bool crc_flag;
} CcciElement;

typedef struct {
    CcciElement *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} CcciList;

void init_list(CcciList *list) 
{
    list->size = 0;
    list->capacity = 10;
    list->array = (CcciElement *)malloc(list->capacity * sizeof(CcciElement));
    pthread_mutex_init(&list->mutex, NULL);
}

void resize_list(CcciList *list) 
{
    list->capacity *= 2;
    CcciElement *newArray = (CcciElement *)malloc(list->capacity * sizeof(CcciElement));

    for(size_t i = 0; i < list->size; ++i) {
        newArray[i] = list->array[i];
    }
    free(list->array);
    list->array = newArray;
}

void add_element(CcciList *list, CcciElement elem) 
{
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        resize_list(list);
    }
    list->array[list->size++] = elem;

    pthread_mutex_unlock(&list->mutex);
