    int UEID;
    time_t lastAccessTime;
    CCE CCEs[MAX_CCE];
} CCCI;

CCCI *hashTable[HASH_TABLE_SIZE] = {0};
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int currentSize = 0;

void addCCCI(int UEID, CCE CCEs[]) {
    pthread_mutex_lock(&lock);

    if (currentSize >= MAX_SIZE) {
        printf("Maximum size reached. Cannot add more CCCI structures.");
        pthread_mutex_unlock(&lock);
        return;
    }

    int hashIndex = UEID % HASH_TABLE_SIZE;
    while (hashTable[hashIndex] != NULL) {
        if (hashTable[hashIndex]->UEID == UEID) {
            printf("Duplicate UEID found. Cannot add more CCCI structures.");
            pthread_mutex_unlock(&lock);
            return;
        }

        hashIndex = (hashIndex + 1) % HASH_TABLE_SIZE;
    }

    CCCI *newCCCI = malloc(sizeof(CCCI));
    newCCCI->UEID = UEID;
    memcpy(newCCCI->CCEs, CCEs, sizeof(CCE) * MAX_CCE);
    hashTable[hashIndex] = newCCCI;

    currentSize++;

    pthread_mutex_unlock(&lock);
}

void cleanupStaleCCCI() {
    time_t currentTime = time(NULL);

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        if (hashTable[i] != NULL && difftime(currentTime, hashTable[i]->lastAccessTime) > 60) {
            free(hashTable[i]);
            hashTable[i] = NULL;
            currentSize--;
