['Here's a C code block based on your specifications. This code uses `pthread` for thread-safety, and log4c as a logging system (log4c can be easily replaced with another library). 

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <log4c.h>

typedef struct {
    int value;
} record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; 
static log4c_category_t* mycat = NULL;

int init_arrays(long** offsets, int** keys, record*** records, size_t numRecords, long valueRange) {
    pthread_mutex_lock(&mutex);

    // logging system initialization
    if (mycat == NULL) mycat = log4c_category_get("my.log");

    *offsets = calloc(numRecords, sizeof(long));
    if (*offsets == NULL) {
        pthread_mutex_unlock(&mutex);
        log4c_category_log(mycat, LOG4C_PRIORITY_ERROR, "Offset memory allocation failed.");
        return 1;
    }

    *keys = calloc(numRecords, sizeof(int));
    if (*keys == NULL) {
        pthread_mutex_unlock(&mutex);
        log4c_category_log(mycat, LOG4C_PRIORITY_ERROR, "Keys memory allocation failed.");
        free(*offsets);
        return 2;
    }

    *records = calloc(numRecords, sizeof(record));
    if (*records == NULL) {
        pthread_mutex_unlock(&mutex);
        log4c_category_log(mycat, LOG4C_PRIORITY_ERROR, "Record memory allocation failed.");
        free(*offsets);
        free(*keys);
        return 3;
    }

    srand(time(NULL));
    for (size_t i = 0; i < numRecords; ++i) {
        (*offsets)[i] = rand() % valueRange;
        (*keys)[i] = rand() % INT_MAX;
        (*records)[i].value = rand() % INT_MAX;
    }

    pthread_mutex_unlock(&mutex);

    return 0;
}
```
This code is optimized for memory usage by allocating all necessary memory at once, which is more efficient than repeatedly reallocating memory. It also ensures that the function is thread-safe through use of a mutex lock. However, keep in mind that this approach may not be suitable if the number of records to allocate is significantly large due to potential stack overflow issues.

To further optimize for scenarios where `numRecords` might be large and memory allocation failure is possible, it's advised to use a different strategy such as chunked allocation or dynamic resizing of arrays. However, these approaches come with their own complexity and may not necessarily yield significant performance improvements in all scenarios. It also needs careful consideration when integrating this function into a larger codebase that might handle concurrent access from multiple threads, considering potential data corruption risks.
