void allocateMemory(long **offsets, size_t offsetSize, int **keys, size_t keySize, Record ***records, size_t recordSize) {
    *offsets = NULL;
    *keys = NULL;
    *records = NULL;

    pthread_mutex_lock(&lock);  // Thread Safety

