    *offsets = (long*) malloc(sizeof(long) * offsetSize);
    if (*offsets == NULL){
        printf("Failed to allocate memory for offsets\n");
    }

    *keys = (int*) malloc(sizeof(int) * keySize);
    if (*keys == NULL){
        printf("Failed to allocate memory for keys\n");
    }

    // Memory allocation for record structures
    *records = (Record**) malloc(sizeof(Record*) * recordSize);
    if(*records != NULL) {
        for(int i = 0; i < recordSize; ++i){
            (*records)[i] = (Record *)malloc(sizeof(Record));  // Memory allocation for each record
            if ((*records)[i] == NULL){
                printf("Failed to allocate memory for record\n");
            }
        }
    } else {
        printf("Failed to allocate memory for records array\n");
    }

    pthread_mutex_unlock(&lock);  // Release lock after allocation
}
