```rust
use hyper::{Client, Uri};
use serde_json;
use std::sync::Arc;
use std::thread;
use log::info;

#[derive(Debug)]
struct Record {
    value: i32,
    double: f64,
}

fn create_client() -> Client<hyper::client::HttpConnector> {
    let client = hyper::Client::new();
    client
}

fn build_request(url: &str) -> Result<hyper::Request<hyper::Body>, Box<dyn std::error::Error>> {
    let uri = Uri::from_static(&format![url]);
    let request = hyper::Request::get(uri).body(hyper::Body::empty());

    Ok(request)
}

fn make_client_request(client: &Client<hyper::client::HttpConnector>, request: hyper::Request<hyper::Body>) -> Result<String, Box<dyn std::error::Error>> {
    let response = client.request(request).await?;

    let bytes = hyper::body::to_bytes(response.into_body()).await?;
    let body = String::from_utf8(bytes)?;

    Ok(body)
}

fn parse_json(data: &str) -> Result<Vec<Record>, serde_json::Error> {
    let v: Vec<Record> = serde_json::from_str(&data)?;
    Ok(v)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    info![starting program];
    let client = create_client();
    let request = build_request("http://example.com")?;
    let response = make_client_request(&client, request).await?;
    let records = parse_json(&response)?;

    info![parsed records: {:#?} , records];
    Ok(())
}
```
This is a basic example that makes HTTP requests and parses the response as JSON into our defined structs. 

A few things to note here:
- The `create_client` function creates an instance of a Hyper client, which can be used for making HTTP requests in Rust.
- The `build_request` function creates a request object with the given URL.
- The `make_client_request` sends this request using our client and returns the response body as a string.
- The `parse_json` function parses this JSON string into a vector of `Record` instances using Serde, Rust's JSON serialization framework.
- This example uses the Tokio async runtime which allows us to make HTTP requests in parallel with other tasks. 

