typedef struct {
    UEContext *list;
    size_t capacity;
    size_t length;
} UELIST;

UELIST* createUEList() {
    UELIST *uelist = malloc(sizeof(UELIST));
    if (uelist == NULL) return NULL;  // handle memory allocation failure

    srand((unsigned int)time(NULL));
    ue_list->capacity = 10;  // initialize with a small capacity
    ue_list->length = 0;
    ue_list->list = malloc(ue_list->capacity * sizeof(UEContext));

    return ue_list;
}

int resizeList(UELIST* ue_list) {
    if (ue_list == NULL || ue_list->list == NULL) return -1; // invalid list
    ue_list->capacity *= 2;

    UEContext *new_list = realloc(ue_list->list, ue_list->capacity * sizeof(UEContext));
    if (new_list == NULL) return -1; // handle memory allocation failure

    ue_list->list = new_list;
    return 0; // success
}

int addToList(UELIST* ue_list, UEContext context) {
    if (ue_list == NULL || ue_list->list == NULL) return -1; // invalid list

    if (ue_list->length >= ue_list->capacity) {
        int resize_status = resizeList(ue_list);
        if (resize_status != 0) return resize_status; // resize failure
    }
    ue_list->list[ue_list->length++] = context;

    return 0; // success
}

UEContext getRRCConnectionInfo() {
    UEContext context;
    context.rrcConnTag = 42; // replace this with actual data fetching from external source
    return context;
}

int populateList(UELIST* ue_list, int n) {
