#include <errno.h>

typedef struct {
    char* mac_address;
    GList* ip_addresses;
    int status_flag;
} NIC;

GList* nics = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

NIC* create_nic(const char* mac, const char* ip) {
    NIC* nic = malloc(sizeof(NIC));
    if(!nic) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }

    nic->mac_address = strdup(mac);
    if(!nic->mac_address){
        free(nic);
        printf("Memory allocation for MAC address failed: %s\n", strerror(errno));
        return NULL;
    }

    nic->ip_addresses = g_list_append(NULL, strdup(ip));
    if(!nic->ip_addresses) {
        free(nic->mac_address);
        free(nic);
        printf("Memory allocation for IP address failed: %s\n", strerror(errno));
        return NULL;
    }

    nic->status_flag = 1; // Assume UP
    return nic;
}

void add_nic(const char* mac, const char* ip) {
    pthread_mutex_lock(&mutex);
    NIC* nic = create_nic(mac, ip);
    if(!nic) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    nics = g_list_append(nics, nic);
    pthread_mutex_unlock(&mutex);
}

void print_all_nics() {
    for (GList *l = nics; l != NULL; l = l->next) {
        NIC* nic = (NIC*)l->data;
        printf("MAC: %s, IP: ", nic->mac_address);

        for(GList *ip = nic->ip_addresses; ip != NULL; ip = ip->next) {
            printf("%s,", (char*)ip->data);
        }

        printf(" Status: %s\n", nic->status_flag ? "UP" : "DOWN");
    }
}
