    if (ccci == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for a CCCI structure!");
        return NULL;
    }

    // Generate a unique UEID and ensure its uniqueness
    srand(time(NULL));
    pthread_mutex_lock(&hashLock);
    do {
        ccci->ueid = rand() % MAX_UEID;
    } while (hashTable[ccci->ueid] != NULL);

    // Add the new CCCI to the hash table for quick lookup
    hashTable[ccci->ueid] = ccci;
    pthread_mutex_unlock(&hashLock);

    // Initialize random number of CCEs within a range
