['Here is an example of how you could implement this in C#. This code will read the configuration from an XML file, allocate arrays for double precision floating-point numbers, integer keys, and data_points structures, initialize these structures with random values within given ranges, track total memory usage, and handle potential errors:

```csharp
using System;
using System.Collections.Generic;
using System.Xml.Linq;
using System.Runtime.InteropServices;

public struct DataPoint
{
    public double Value;
    public IntPtr Label;
    public int Key;
}

class Program
{
    static void Main(string[] args)
    {
        const long MAX_MEMORY = 1024 * 1024; // 1 MB in bytes
        long memoryUsed = 0;

        XDocument doc = null;
        try
        {
            doc = XDocument.Load("config.xml");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading XML file: {ex.Message}");
            return;
        }

        // Load configuration settings from XML
        var config = new Dictionary<string, string>();
        foreach (var element in doc.Root.Elements())
        {
            config[element.Name.LocalName] = element.Value;
        }

        int numPoints = 0;
        double minValue = 0, maxValue = 1;
        if (!int.TryParse(config["NumPoints"], out numPoints) ||
            !double.TryParse(config["MinValue"], out minValue) ||
            !double.TryParse(config["MaxValue"], out maxValue))
        {
            Console.WriteLine("Invalid configuration settings");
            return;
        }

        // Allocate arrays for double precision floating-point numbers and integer keys
        var values = new double[numPoints];
        var keys = new int[numPoints];
        memoryUsed += Marshal.SizeOf(values) + Marshal.SizeOf(keys);

        if (memoryUsed > MAX_MEMORY)
        {
            Console.WriteLine("Memory limit exceeded");
            return;
        }

        // Initialize arrays with random values within given ranges
        Random rand = new Random();
        for (int i = 0; i < numPoints; i++)
        {
            values[i] = minValue + rand.NextDouble() * (maxValue - minValue);
            keys[i] = i;
        }

        // Allocate array for data_point structures and initialize them with values and keys
        var points = new DataPoint[numPoints];
        memoryUsed += Marshal.SizeOf(points);

        if (memoryUsed > MAX_MEMORY)
        {
            Console.WriteLine("Memory limit exceeded");
            return;
        }

        for (int i = 0; i < numPoints; i++)
        {
            points[i].Value = values[i];
            points[i].Label = Marshal.StringToHGlobalAnsi("example"); // Allocate string buffer
            memoryUsed += Marshal.SizeOf(points[i].Label);

            if (memoryUsed > MAX_MEMORY)
            {
                Console.WriteLine("Memory limit exceeded");
                return;
            }
        }

        // Clean up allocated memory before exiting
        for (int i = 0; i < numPoints; i++)
        {
            Marshal.FreeHGlobal(points[i].Label); // Free string buffer
        }
    }
}
```
