void resize_array(int **arrays, size_t *currentSize, size_t newSize) {
    int* newArrays = realloc(arrays, newSize * sizeof(int));

    if (newArrays == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    arrays = newArrays;
    *currentSize = newSize;
}

void init_arrays(double **doubles, char **chars, Node ***nodes) {
    const size_t initialCapacity = 1024;
    const double growthFactor = 1.5;

    size_t currentArraySize = initialCapacity;
    size_t currentNodeSize = currentArraySize / sizeof(Node);

    *doubles = malloc(currentArraySize * sizeof(double));
    *chars = malloc(currentArraySize * sizeof(char));
    *nodes = malloc(currentNodeSize * sizeof(Node*));

    if (*doubles == NULL || *chars == NULL || *nodes == NULL) {
