['Here is a possible implementation of your task in C. It uses mergesort for sorting because it does not require additional memory space as quicksort does and handles large datasets efficiently. The function to handle errors is called check_ptr(), which checks if the pointer returned by malloc() or realloc() is NULL, meaning the allocation failed:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

void* check_ptr(void *ptr) {
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

Record* allocate_records(long size, int range) {
    srand((unsigned int) time(NULL));

    Record *records = check_ptr(malloc(sizeof(Record) * size));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % range + 1;
    }
    return records;
}

void merge(Record* arr, int l, int m, int r) {
    int i, j, k;
    int n1 = m - l + 1;
    int n2 =  r - m;

    Record L[n1], R[n2];

    for (i = 0; i < n1; i++) {
        L[i] = arr[l + i];
    }
    for (j = 0; j < n2; j++) {
        R[j] = arr[m + 1+ j];
    }

    i = 0; 
    j = 0; 
    k = l; 

    while (i < n1 && j < n2) {
        if (L[i].value <= R[j].value) {
            arr[k] = L[i];
            i++;
        } else {
            arr[k] = R[j];
            j++;
        }
        k++;
    }

    while (i < n1) {
        arr[k] = L[i];
        i++;
        k++;
    }

    while (j < n2) {
        arr[k] = R[j];
        j++;
        k++;
    }
}

void mergeSort(Record* arr, int l, int r) {
    if (l < r) {
        int m = l+(r-l)/2;

        mergeSort(arr, l, m);
        mergeSort(arr, m+1, r);
        merge(arr, l, m, r);
    }
}

void sort_records(Record* records, long size) {
    mergeSort(records, 0, size - 1);
}
```
You can use these functions like this:
