    long offsets[] = {2L,3L,4L}; // replace with your values
    int keys[] = {5,6,7};       // replace with your values

    Record* records = allocate_records(sizeof(keys)/sizeof(int), 100);

    sort_records(records, sizeof(keys)/sizeof(int));

    for (int i = 0; i < sizeof(keys)/sizeof(int); i++) {
        printf("%d ", records[i].value);
    }

    free(records);

    return 0;
}
```
