    if (*nodeArray == NULL) {
        free(*doubleArray);
        free(*charArray);
        printf("Failed to allocate memory for node array\n");
        exit(EXIT_FAILURE);
    }

    *recordArray = (Record *)malloc(n * sizeof(Record));
    if (*recordArray == NULL) {
        free(*doubleArray);
        free(*charArray);
        free(*nodeArray);
        printf("Failed to allocate memory for record array\n");
        exit(EXIT_FAILURE);
    }

    // initialize arrays with random values within a range (0, 100)
