        }
        (*nodeArray)[i] = newNode;

        Record *newRecord = &(*recordArray)[i];
        newRecord->num = rand() % 100; // random integer value between 0 and 99
    }
}

void sortRecords(Record *records, int n) {
    qsort(records, n, sizeof(Record), compare);
}

int compare(const void *a, const void *b) {
    Record *recordA = (Record *)a;
    Record *recordB = (Record *)b;

    return recordA->num - recordB->num;
}
