#define MAX_DEVICE_COUNT 500

typedef struct device_config {
    int id;
    char *protocols;
    char status[2]; // assume 'OK' or 'ERR' as statuses
} device_config;

typedef struct hash_table {
    pthread_mutex_t lock;
    device_config* table[MAX_DEVICE_COUNT];
    int count;
} hash_table;

hash_table *create_hash_table() {
    hash_table* ht = malloc(sizeof(*ht));
    assert(ht != NULL); // fail if memory allocation failed.

    pthread_mutex_init(&ht->lock, NULL);
    memset(ht->table, 0, sizeof(device_config*) * MAX_DEVICE_COUNT);
    ht->count = 0;

    return ht;
}

void destroy_hash_table(hash_table* ht) {
    assert(ht != NULL);

    for (int i = 0; i < MAX_DEVICE_COUNT; ++i) {
        if (ht->table[i] != NULL) {
            free(ht->table[i]->protocols); // release memory.
            free(ht->table[i]); 
        }
    }

    pthread_mutex_destroy(&ht->lock);
    free(ht);
}

int add_device(hash_table* ht, device_config* d) {
    assert(d != NULL && ht != NULL);

    if (ht->count >= MAX_DEVICE_COUNT || d->id < 0 || d->id >= MAX_DEVICE_COUNT) return 1; // fail if list is full or device ID out of range.

    pthread_mutex_lock(&ht->lock);

    // Check if device ID already exists.
    if (ht->table[d->id] != NULL) {
        pthread_mutex_unlock(&ht->lock);
        return 2;
    }

    ht->table[d->id] = d;
    ht->count++;

    pthread_mutex_unlock(&ht->lock);

    return 0; // success.
}
