    // Log error message, could be writing to a file or printing to the console for example
    fprintf(stderr, "Error: %s\n", message);
}

int init_arrays(double** doubles, char** chars, data_t** data, size_t count) {
    // Allocate memory for all arrays
    *doubles = (double*)malloc(count * sizeof(double));
    *chars = (char*)malloc(count * sizeof(char));
    *data = (data_t*)malloc(count * sizeof(data_t));

    // Check if memory allocation was successful
    if (*doubles == NULL || *chars == NULL || *data == NULL) {
        log_error("Memory allocation failed");
        return ENOMEM;  // ENOMEM: Not enough space
    }

    // Initialize data structures with random values in the given range
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        (*data)[i].value = ((double) rand() / (RAND_MAX)) * (max - min) + min; // random value between max and min
    }

    return 0;
}

void free_arrays(double* doubles, char* chars, data_t* data) {
    free(doubles);
    free(chars);
    free(data);
}
```
The `init_arrays` function dynamically allocates memory for three arrays of specified size and initializes them. 
