['Here is an implementation of your requirements in C language. It uses quicksort algorithm due to its efficiency and good average case scenario. Note that actual error handling, data integrity checks and logging are not implemented for simplicity reasons but can be added as needed. 

```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct item {
    int value;
} Item;

void* safe_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && (size > 0)) {
        printf("Memory allocation error\n");
        exit(-1);
    }
    return ptr;
}

void quicksort(Item** array, char* keys, int low, int high) {
    if (low < high) {
        Item *pivot = array[high];
        int i = low - 1;
        for (int j = low; j <= high - 1; j++) {
            if (strcmp(&keys[array[j]->value], &keys[pivot->value]) < 0) {
                i++;
                Item *temp = array[i];
                array[i] = array[j];
                array[j] = temp;
            }
        }
        Item* temp = array[i+1];
        array[i+1] = array[high];
        array[high] = temp;

        int pi = i + 1;
        quicksort(array, keys, low, pi - 1);
        quicksort(array, keys, pi + 1, high);
    }
}

void sort_items(Item** array, double* floats, char* keys, int size) {
    srand((unsigned int) time(NULL));

    for (int i = 0; i < size; ++i) {
        array[i] = safe_malloc(sizeof(Item));
        array[i]->value = rand();  // generate random values in specified range here.

        floats[i] = ((double)rand() / (double)RAND_MAX);  // generate random float numbers here.

        keys[i] = 'A' + rand() % 26;  // generate random chars for lexicographical order sorting here.
    }

    quicksort(array, keys, 0, size - 1);
}
```

This code assumes the input to be a character array for 'keys' and a double array for 'floats'. The actual implementation may depend on your specific needs, such as handling of data from external sources or batch updates. Also, please note that this is just one approach, you might need to consider different algorithms based on your use case requirements.
']

