typedef struct {
    int value;
    long timestamp;
} Record;

int createArrays(long **offsets, int **keys, Record ***records, size_t size) {
    *offsets = malloc(sizeof(long) * size);
    if (*offsets == NULL) return -1;  // Allocation failed

    *keys = malloc(sizeof(int) * size);
    if (*keys == NULL) {  // Deallocate offsets on failure
        free(*offsets);
        return -2;
    }

    *records = malloc(sizeof(Record*) * size);
    if (*records == NULL) {  // Deallocate keys and offsets on failure
        free(*keys);
        free(*offsets);
        return -3;
    }

    srand((unsigned int)time(NULL));  // Seed random number generator

    for (size_t i = 0; i < size; ++i) {
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) {  // Deallocate previously allocated records on failure
            for (--i; i >= 0; --i) free((*records)[i]);
            free(*keys);
            free(*offsets);
            return -4;
        }

        (*records)[i]->value = rand();  // Initialize record's value with random number
        (*records)[i]->timestamp = 0;   // Initialize timestamp as zero for simplicity
    }

    return 0;  // Successful allocation and initialization of arrays
}
```
This function first allocates space for the three arrays using `malloc()`. If any allocation fails, it deallocates all previously allocated memory to prevent a memory leak. After successful allocation, each record's value is initialized with a random number, and their timestamp is set to zero (for simplicity). 

In case of failure during record initialization (record memory allocation), the function will deallocate all previous records to ensure no memory leaks occur. It returns an appropriate error code (-1 for offsets, -2 for keys, -3 for records, and -4 for individual records) when memory allocation fails.

The 'size' argument determines the size of the arrays allocated by this function. This allows developers to optimize both time and space complexity based on the anticipated dataset size or load. 

