    // Data members for the Control Channel Element
} CCE;

typedef struct {
    char UEID[20];  // Unique identifier for each UE
    CCE cceList[10];  // Array of up to 10 CCEs
    int cceCount;  // Number of currently stored CCEs
} CCCI;
```
2. Define Global Variables:
```c
#define MAX_ENTRIES 1000
#define LOAD_FACTOR 0.8

// List of all Control Channel Information structures
static CCCI* ccciList = NULL;
static int ccciCount = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
```
3. Implement Function to Check if a UEID is Unique:
```c
bool isUniqueUEID(char* UEID) {
    for (int i = 0; i < ccciCount; ++i) {
        if (strcmp(ccciList[i].UEID, UEID) == 0) {
            return false;  // The UEID already exists in the list
        }
    }
    return true;  // The UEID is unique
}
```
4. Implement Function to Add a CCCI:
```c
int addCCCI(char* UEID, CCE cceList[], int cceCount) {
    if (ccciCount >= MAX_ENTRIES) return -1;  // Check the limit of entries is not reached

    pthread_mutex_lock(&lock);  // Lock to ensure thread safety

    if (!isUniqueUEID(UEID)) {
        pthread_mutex_unlock(&lock);  // Unlock before returning
        return -1;  // The UEID already exists in the list
    }

    CCCI* newEntry = malloc(sizeof(CCCI));
    strcpy(newEntry->UEID, UEID);
    memcpy(newEntry->cceList, cceList, sizeof(CCE) * 10);
    newEntry->cceCount = cceCount;

    // Resize the list if it's nearly full
    if (ccciCount >= MAX_ENTRIES * LOAD_FACTOR) {
        ccciList = realloc(ccciList, sizeof(CCCI) * MAX_ENTRIES);
    }

    ccciList[ccciCount++] = newEntry;  // Add the new entry to the list

    pthread_mutex_unlock(&lock);  // Unlock after adding the entry

    return ccciCount - 1;  // Return index of added CCCI in the list
}
```
5. Implement Function to Retrieve CCCI by UEID:
```c
CCCI* getCCCIByUEID(char* UEID) {
    pthread_mutex_lock(&lock);  // Lock to ensure thread safety

    for (int i = 0; i < ccciCount; ++i) {
        if (strcmp(ccciList[i].UEID, UEID) == 0) {
            pthread_mutex_unlock(&lock);  // Unlock before returning
            return &ccciList[i];  // Return the found CCCI
        }
    }

    pthread_mutex_unlock(&lock);  // Unlock after checking all entries

    return NULL;  // No matching UEID was found
}
```
6. Implement Function to Remove CCCI by UEID:
```c
void removeCCCIByUEID(char* UEID) {
    pthread_mutex_lock(&lock);  // Lock to ensure thread safety

    for (int i = 0; i < ccciCount; ++i) {
        if (strcmp(ccciList[i].UEID, UEID) == 0) {
            free(ccciList[i]);  // Free the memory occupied by CCCI

            // Shift all entries after this one to fill the gap
            for (int j = i; j < ccciCount - 1; ++j) {
                ccciList[j] = ccciList[j + 1];
            }

            --ccciCount;  // Reduce count of entries

            break;
        }
    }

    pthread_mutex_unlock(&lock);  // Unlock after removing the entry
}
```
7. Implement Periodic Cleanup Mechanism:
```c
void cleanStaleEntries() {
    time_t currentTime = time(NULL);

    for (int i = 0; i < ccciCount;) {
        if (currentTime - ccciList[i].lastAccess > 60) {  // Check if entry is stale
            free(ccciList[i]);  // Free the memory occupied by CCCI

            // Shift all entries after this one to fill the gap
            for (int j = i; j < ccciCount - 1; ++j) {
                ccciList[j] = ccciList[j + 1];
            }

            --ccciCount;  // Reduce count of entries
        } else {
            ++i;  // Move to next entry
        }
    }
}
```
Remember to initialize your global variables properly:
```c
pthread_mutex_init(&lock, NULL);  // Initialize the mutex lock
ccciList = malloc(sizeof(CCCI) * MAX_ENTRIES);  // Allocate memory for the list of CCCIs
