#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

int* generateUniqueRandomNumbers(int lower, int upper, size_t count) {
    srand(time(0));

    if (count > (upper - lower + 1)) return NULL;  // error: range not enough to generate unique random numbers.

    int *uniqueNums = malloc(sizeof(int)*count);
    for (int i = 0; i < count; ++i) {
        int num;
        do{
            num = rand() % (upper - lower + 1) + lower;
        } while (memchr(uniqueNums, num, sizeof(int)*i)); // check if generated number already exists in array.

        uniqueNums[i] = num;
    }

    return uniqueNums;
}

Record* initializeRecords(size_t size) {
    if (size == 0) return NULL;  // return NULL if size is zero, no memory allocated.

    long *offsets = malloc(sizeof(long)*size);
    if (!offsets) goto error1;

    int *keys = malloc(sizeof(int)*size);
    if (!keys) goto error2;

    Record *records = malloc(sizeof(Record)*size);
    if (!records) goto error3;

    // Generate unique random numbers for keys.
    int* uniqueKeys = generateUniqueRandomNumbers(0, size - 1, size);
    if(!uniqueKeys) goto error4;

    // Set the value of each record's int field to a random unique key.
    for (size_t i = 0; i < size; ++i) {
        records[i].value = uniqueKeys[i];
    }

    free(uniqueKeys);  // Free unique keys array as it is no longer needed.

    return records;

error4:
    free(records);
error3:
    free(keys);
error2:
    free(offsets);
error1:
    return NULL;  // If any allocation fails, return NULL and free all previously allocated memory.
}
```
