typedef struct {
    long* offsets;
    int* keys;
} OffsetsAndKeys;

typedef struct {
    int value;
} Record;

typedef struct {
    Record* records;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;  // For thread safety
} RecordsArray;

RecordsArray records = {.count = 0, .capacity = 0};
OffsetsAndKeys offsetsAndKeys;
size_t memoryLimit;
int rangeMin, rangeMax;

void addRecord(int value) {
    pthread_mutex_lock(&records.mutex);
    if (records.count == records.capacity) {  // Resize arrays if necessary
        size_t newCapacity = records.capacity == 0 ? 1 : records.capacity * 2;
        Record* newRecordsArray = realloc(records.records, newCapacity * sizeof(Record));
        if (newRecordsArray == NULL) {
            printf("Error: Out of memory!\n");
            pthread_mutex_unlock(&records.mutex);
            return;
        }
        records.records = newRecordsArray;
        records.capacity = newCapacity;
    }
    // Initialize record
    Record* record = &records.records[records.count++];
    record->value = value;

    pthread_mutex_unlock(&records.mutex);
}

void processDataChunk(int* chunk, size_t chunkSize) {
    for (size_t i = 0; i < chunkSize; ++i) {
        addRecord(chunk[i]);  // Add new record to the array

        if ((records.count + offsetsAndKeys.count * sizeof(*offsetsAndKeys.keys)) * sizeof(Record) > memoryLimit) {
            flushRecords();
        }
    }
}

void flushRecords() {
    pthread_mutex_lock(&records.mutex);  // Lock for thread safety

    size_t recordsSize = records.count * sizeof(Record);
    if (recordsSize > 0) {  // If there are any remaining records, flush them
        // Do something with the records...

        free(records.records);  // Free the memory used by the records array
        records.records = NULL;
        records.count = 0;
        records.capacity = 0;
    }

    pthread_mutex_unlock(&records.mutex);
}

void init() {
    srand(time(NULL));  // Initialize random number generator
    offsetsAndKeys.offsets = malloc(100 * sizeof(*offsetsAndKeys.offsets));  // Allocate initial memory for the arrays
    offsetsAndKeys.keys = malloc(100 * sizeof(*offsetsAndKeys.keys));

    pthread_mutex_init(&records.mutex, NULL);
}

void cleanup() {
    free(offsetsAndKeys.offsets);  // Free the memory used by the arrays
    free(offsetsAndKeys.keys);
    flushRecords();  // Flush any remaining records before exiting

    pthread_mutex_destroy(&records.mutex);
}
```
