['Here is a C function that fulfills the requirements described. Please note that this code requires the `libcsv` library to read CSV files and doesn't have error checking for invalid sensor data or inconsistent number of fields, as these are best handled by the CSV file itself. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <csv.h>

struct sensor_data {
    float temperature;
    float humidity;
};

struct sensor_location {
    int index;
};

void initialize_sensor_data(const char *csv_file_path) {
    FILE *fp = fopen(csv_file_path, "r");

    if (fp == NULL) {
        printf("Error: Unable to open CSV file.\n");
        exit(EXIT_FAILURE);
    }

    csv_parser parser;
    char buf[1024];
    int count = 0;

    if (csv_init(&parser, CSV_APPEND_NULL) != 0) {
        printf("Error: Unable to initialize CSV parser.\n");
        exit(EXIT_FAILURE);
    }

    while ((fgets(buf, sizeof buf, fp)) != NULL) {
        if (csv_parse(&parser, buf, strlen(buf), NULL, 0) != 0) {
            printf("Error: Unable to parse CSV data.\n");
            exit(EXIT_FAILURE);
        }
        ++count;
    }

    csv_free(&parser);

    struct sensor_data *sensors = malloc((count - 1) * sizeof(*sensors));
    if (sensors == NULL) {
        printf("Error: Unable to allocate memory for sensors.\n");
        exit(EXIT_FAILURE);
    }

    struct sensor_location *locations = malloc((count - 1) * sizeof(*locations));
    if (locations == NULL) {
        printf("Error: Unable to allocate memory for locations.\n");
        free(sensors);
        exit(EXIT_FAILURE);
    }

    rewind(fp);
    csv_init(&parser, CSV_STRICT);
    fgets(buf, sizeof buf, fp); // skip header

    for (int i = 0; (fgets(buf, sizeof buf, fp)) != NULL; ++i) {
        if (csv_parse(&parser, buf, strlen(buf), NULL, 0) != 0) {
            printf("Error: Unable to parse CSV data.\n");
            free(sensors);
            free(locations);
            exit(EXIT_FAILURE);
        }

        sensors[i].temperature = atof(parser.fields[1]);
        sensors[i].humidity = atof(parser.fields[2]);
        locations[i].index = i;
    }

    csv_free(&parser);
    fclose(fp);
}
``` 

This function reads the CSV file line by line, counting the number of lines to determine how much memory to allocate for the sensor data and locations. It then rewinds the file pointer, reads the header line, and then reads each subsequent line into a `struct sensor_data` and a `struct sensor_location`.
']

