["Here's a simplified example of how you might implement this in C using dynamic memory allocation and random number generation:

```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <assert.h>

typedef struct point {
    int x;
    int y;
} Point;

typedef struct record {
    double value;
} Record;

void *alloc_and_init(size_t totalSize, size_t elemSize) {
    if (totalSize > SIZE_MAX / elemSize) return NULL;  // Check for overflow.

    void *result = malloc(totalSize);
    assert(result != NULL);

    memset(result, 0, totalSize);  // Initialize memory to zero.
    return result;
}

double rand_between(double min, double max) {
    static bool init = false;
    if (!init) {
        srand((unsigned int)time(NULL));
        init = true;
    }

    return min + ((double)rand() / RAND_MAX) * (max - min);
}

void manageMemory(size_t doubleCount, size_t stringLength, size_t pointCount, size_t recordCount,
                  double minValue, double maxValue, size_t limit) {
    assert(doubleCount <= limit / sizeof(double));
    assert(stringLength + 1 <= limit);  // +1 for null terminator.
    assert(pointCount * sizeof(Point) <= limit);
    assert(recordCount * sizeof(Record) <= limit);

    double *doubles = alloc_and_init(doubleCount * sizeof(double), sizeof(double));

    char *string = alloc_and_init(stringLength + 1, sizeof(char));  // +1 for null terminator.
    string[stringLength] = 0;  // Ensure string is null-terminated.

    Point *points = alloc_and_init(pointCount * sizeof(Point), sizeof(Point));

    Record *records = alloc_and_init(recordCount * sizeof(Record), sizeof(Record));
    for (size_t i = 0; i < recordCount; ++i) {
        records[i].value = rand_between(minValue, maxValue);
    }

    // Use the allocated memory...

    free(records);
    free(points);
    free(string);
    free(doubles);
}
```

