// Define a mutex to handle concurrent access to the log file
pthread_mutex_t lock;

void* dns_resolution(void *hostname) {
    struct hostent *he = gethostbyname((char *)hostname);

    if (he == NULL) {
        herror("gethostbyname");
        return NULL;
    }

    u_char ip_address[16]; // Enough space for IPv4 and IPv6 addresses
    memcpy(ip_address, he->h_addr_list[0], he->h_length);

    return (void *)ip_address;
}

void* read_log(FILE *file) {
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    int *numbers = malloc(1024 * sizeof(int)); // Start with a small allocation
    int count = 0, capacity = 1024;

    while ((read = getline(&line, &len, file)) != -1) {
        pthread_mutex_lock(&lock);

        char *token = strtok(line, " ");
        while (token != NULL) {
            if (count >= capacity) {
                capacity *= 2; // Double the size of our array if needed
                numbers = realloc(numbers, capacity * sizeof(int));
            }

            int number = atoi(token);
            if (number != 0) {
                numbers[count++] = number;
            }

            token = strtok(NULL, " ");
        }

        pthread_mutex_unlock(&lock);
    }

    free(line);

    // Compute the average of the last two non-zero numbers and append it to our array
    if (count > 1) {
        int sum = numbers[count - 2] + numbers[count - 1];
        float avg = (float)sum / 2;

        count++;
        if (count > capacity) { // Check again after incrementing count
            capacity *= 2;
            numbers = realloc(numbers, capacity * sizeof(int));
        }

        numbers[count - 1] = avg;
    }

    return (void *)numbers;
}

int main() {
    FILE *file = fopen("log.txt", "r"); // Assuming that the log file is named "log.txt"
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    pthread_t tid;
    pthread_create(&tid, NULL, read_log, file);

    // Set resource limits to prevent the program from becoming a performance bottleneck
    struct rlimit cpu_limit = {10, 20}; // CPU time limit of 10 seconds and 20 seconds after that
    if (setrlimit(RLIMIT_CPU, &cpu_limit) == -1) {
        perror("setrlimit");
        exit(EXIT_FAILURE);
    }

    struct rlimit mem_limit = {4096, 8192}; // Memory limit of 4KB and 8KB after that
    if (setrlimit(RLIMIT_AS, &mem_limit) == -1) {
        perror("setrlimit");
        exit(EXIT_FAILURE);
    }

    pthread_join(tid, NULL); // Wait for the log reading thread to finish

    fclose(file);
}
```
