using System;
using System.Xml;
using System.Linq;
using System.Collections.Generic;

public class ConfigurationManager
{
    private static readonly Dictionary<string, string> cache = new Dictionary<string, string>();

    public static string GetSettingValue(string xpathExpression)
    {
        if (cache.ContainsKey(xpathExpression))
            return cache[xpathExpression];

        var doc = new XmlDocument() { XmlResolver = null };
        doc.Load("config.xml");
        var nodes = doc.SelectNodes(xpathExpression);

        if (nodes == null || nodes.Count == 0) 
            throw new Exception("Element not found.");

        if (nodes.Count > 1) 
            throw new Exception("Multiple elements with the given name found.");

        var value = nodes[0].InnerText;
        cache[xpathExpression] = value; // add to cache for later use

        return value;
    }
}
