use std::env;
use std::fs::{self, DirEntry};
use std::sync::OnceLock;
use std::thread;
use std::error::Error;

pub struct Config {
    log_dir: OnceLock<String>,
}

impl Default for Config {
    fn default() -> Self {
        Self { 
            log_dir: OnceLock::new(), 
        } 
    }
}

impl Config {
    pub fn get_log_directory(&self) -> &str {
        self.log_dir.get(|| "LOG_DIR".to_string()).as_ref()
    }

    pub fn set_log_directory(&self, dir: String) {
        let _ = thread::spawn({
            let log_dir = env::var("LOG_DIR").unwrap();

            move || {
                if !fs::metadata(log_dir.as_str()).map_or(true, |e| e.is_dir()) {
                    fs::create_dir(&dir).expect("Unable to create directory");
                    env::set_var("LOG_DIR", dir);
                }
            }
        });
    }
