#include <assert.h>
#include <errno.h>

typedef struct {
    int value;
    long offset; // Assuming 'long' can be nullable.
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
atomic_int recordCount = 0;

Record* initRecords(size_t count, int rangeMin, int rangeMax, bool useExternalData) {
    Record* records = malloc(count * sizeof(Record)); // Allocate memory for the records array.
    if (records == NULL) return errno; // Error: allocation failed.

    long* offsets = calloc(count, sizeof(long)); // Allocate memory for the offsets array, initialize to 0.
    int* keys = malloc(count * sizeof(int)); // Allocate memory for the keys array.

    if (offsets == NULL || keys == NULL) { // If either allocation failed...
        free(records);
        free(offsets);
        free(keys);
        return errno; // Error: allocation failed.
    }

    for (size_t i = 0; i < count; ++i) { // Loop to set each record's int field to a random value within the given range.
        keys[i] = rand() % (rangeMax - rangeMin + 1) + rangeMin;

        if (useExternalData && getOffsetFromExternalSource(keys[i], &offsets[i]) == EXTERNAL_DATA_UNAVAILABLE) { // If external data source is unavailable...
            offsets[i] = generateFallbackOffset(); // Generate a fallback offset.
        }

        Record record = { .value = keys[i], .offset = offsets[i] };
        records[i] = record;
    }

    atomic_fetch_add(&recordCount, count); // Atomically increment the record counter.

    pthread_mutex_lock(&lock); // Lock the mutex to ensure thread-safe operation...
    assert(atomic_load(&recordCount) == count); // ...and validate that all records have been initialized correctly.
    pthread_mutex_unlock(&lock);

    free(offsets);
    free(keys);

    return records; // Return the allocated and initialized record array.
}
