typedef struct {
    int key;
    float* value;
} Record;

void allocate_and_read(char *filename, long **offsets, int **keys, float **dataValues, Record ***records) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Failed to open the file.\n");
        return;
    }

    // Initialize the arrays and records
    long size = 0L;
    *offsets = malloc(sizeof(long));
    *keys = malloc(sizeof(int));
    *dataValues = malloc(sizeof(float));
    *records = malloc(sizeof(Record*));

    if (*offsets == NULL || *keys == NULL || *dataValues == NULL || *records == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Read the CSV file and populate the arrays/records
    long offset = 0L;
    int key;
    float dataValue;

    while (fscanf(fp, "%ld,%d,%f", &offset, &key, &dataValue) == 3) {
        (*offsets)[size] = offset;
        (*keys)[size] = key;
        (*dataValues)[size] = dataValue;

        // Allocate memory for each record and populate it
        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }

        record->key = key;
        record->value = &(*dataValues)[size];
        (*records)[size] = record;

        size++;

        // Reallocate the arrays and records for the next entry
        *offsets = realloc(*offsets, (size + 1) * sizeof(long));
        *keys = realloc(*keys, (size + 1) * sizeof(int));
        *dataValues = realloc(*dataValues, (size + 1) * sizeof(float));
        *records = realloc(*records, (size + 1) * sizeof(Record*));

        if (*offsets == NULL || *keys == NULL || *dataValues == NULL || *records == NULL) {
            printf("Memory allocation failed.\n");
            return;
        }
    }

    fclose(fp);
}
