#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <ctype.h>

typedef struct node {
    char value;
    struct node* next;
} Node;

void initialize_data(double** values, int** keys, Node*** nodes, int size) {
    // handle invalid inputs
    if (size <= 0 || isalpha(*values) || isalpha(*keys) || isalpha(*nodes)) {
        printf("Invalid input. Please enter a positive integer for array size.\n");
        return;
    }

    srand(time(NULL));  // initialize random seed

    *values = (double*)malloc(sizeof(double) * size);
    if (*values == NULL) {
        printf("Memory allocation failed for 'values' array.\n");
        return;
    }

    *keys = (int*)calloc(size, sizeof(int));  // initialize to zero
    if (*keys == NULL) {
        free(*values);
        printf("Memory allocation failed for 'keys' array.\n");
        return;
    }

    Node* startNode = (Node*)malloc(sizeof(Node) * size);
    if (startNode == NULL) {
        free(*values);
        free(*keys);
        printf("Memory allocation failed for 'nodes' array.\n");
        return;
    }

    // initialize values and keys arrays
    for (int i = 0; i < size; ++i) {
        (*values)[i] = (double)(rand() % 100);  // random double value between 0 and 99.99
        (*keys)[i] = rand() % 100;  // random integer key between 0 and 99
    }

    Node* currentNode = startNode;
    for (int i = 0; i < size - 1; ++i) {
        currentNode->value = 'a' + rand() % ('z' - 'a'); // random character between 'a' and 'z'
        currentNode->next = currentNode + 1;
        ++currentNode;
    }

    currentNode->value = 'a' + rand() % ('z' - 'a');  // for the last node, set value
    currentNode->next = NULL;
    *nodes = startNode;  // assign to output parameter
}
