int load_bundle(const char *path, Item **items) {
    log4c_category_t *logcat = NULL;
    config_t cfg;
    config_setting_t *root, *item_setting;
    const char* value = NULL;

    // initialize logger
    if (log4c_init() != 1) {
        printf("Failed to init log4c library\n");
        return -1;
    }

    logcat = log4c_category_get("load_bundle");

    config_init(&cfg);

    if (!config_read_file(&cfg, path)) {
      log4c_error(logcat, "Failed to read file: %s\n", path);
      return -1;
    }

    root = config_root_setting(&cfg);
    int item_count = config_setting_length(root);
    *items = (Item*)malloc(sizeof(Item) * item_count);

    srand((unsigned int) time(NULL));

    for (int i = 0; i < item_count; ++i) {
        item_setting = config_setting_get_elem(root, i);

        if (!config_setting_lookup_string(item_setting, "offsets", &value)) {
            log4c_error(logcat, "Missing offset field\n");
            return -1;
        }

        (*items)[i].offsets = malloc(sizeof(long) * strlen(value)); // assuming each long is separated by comma
        for (int j = 0; value[j] != '\0'; ++j, ++j) { // parsing and converting the offsets 
            (*items)[i].offsets[j / 2] = strtol(&value[j], NULL, 10);
        }

        if (!config_setting_lookup_string(item_setting, "keys", &value)) {
            log4c_error(logcat, "Missing keys field\n");
            return -1;
        }

        (*items)[i].keys = malloc(sizeof(int) * strlen(value)); // assuming each int is separated by comma
        for (int j = 0; value[j] != '\0'; ++j, ++j) { // parsing and converting the keys 
            (*items)[i].keys[j / 2] = strtol(&value[j], NULL, 10);
        }
    }

    config_destroy(&cfg);
    log4c_category_delete(logcat);
    return item_count;
}

int main() {
    Item* items;
    int count = load_bundle("path/to/file.txt", &items);
    // do something with the loaded items here...
    for (int i = 0; i < count; ++i) {
        free(items[i].offsets);
        free(items[i].keys);
    }
    free(items);
    return 0;
}
```
