        Record {
            int_value,
            double_value,
        }
    }
}

pub struct HttpClient {
    http_client: http::Client,
    records: Arc<Mutex<Vec<Record>>>,
}

impl HttpClient {
    pub fn new(url: &str, disable_certificate_validation: bool) -> Result<Self, Box<dyn std::error::Error>> {
        let client = http::Client::new(url)?;
        if disable_certificate_validation {
            client.disable_certificate_verification();
        }

        Ok(HttpClient {
            http_client: client,
            records: Arc::new(Mutex::new(Vec::new())),
        })
    }

    pub fn create_request(&self) -> Result<http::RequestBuilder, Box<dyn std::error::Error>> {
        Ok(http::RequestBuilder::new()?)
    }

    pub fn add_record(&self, record: Record) {
        let mut records = self.records.lock().unwrap();
        records.push(record);
    }
}
```
