#include <stdio.h>
#include <stdlib.h>
#include <syslog.h>
#include <limits.h>

/* Function to sort an array using bubble sort */
void bubbleSort(int arr[], int n) {
    for (int i = 0; i < n-1; i++)       
        for (int j = 0; j < n-i-1; j++)  
            if (arr[j] > arr[j+1])  // Swap elements if the next one is smaller
                { int temp = arr[j]; arr[j] = arr[j+1]; arr[j+1] = temp; }
}

/* Function to handle logging */
void logMessage(int priority, char* message) { 
    openlog("Process Integers", LOG_PID | LOG_CONS , LOG_USER); // Open the connection to system logger
    syslog(priority, "%s",message);   // Log the message
    closelog(); // Close the connection to system logger
}

void processIntegers(int *count) {
    int *arr = (int*)malloc(*count * sizeof(int));  // Dynamically allocate memory for array based on user input.

    if (arr == NULL || *count < 0) {   // Check for invalid inputs and handle them gracefully
        logMessage(LOG_ERR, "Error: Invalid input detected");
        return;
    }

    logMessage(LOG_INFO, "Reading integers...");

    int i = 0;
    while (i < *count) {
        if(scanf("%d", &arr[i]) != 1){  // Check for non-integer inputs
            logMessage(LOG_ERR, "Error: Non-Integer input detected");
            return;
        }
        i++;
    }

    int sum = 0;   // Initialize a variable to hold the total sum of integers.
    for (i = 0; i < *count; ++i) {
        sum += arr[i];  // Calculate and update the sum of all inputs.
    }

    double avg = (double)sum / *count;   // Compute average value of integers.

    bubbleSort(arr, *count);  // Sort array before finding smallest and largest values.

    logMessage(LOG_INFO, "Processing results...");

    printf("Largest: %d\n", arr[*count-1]);   // Print the largest integer in array.
    printf("Smallest: %d\n", arr[0]);  // Print smallest integer in array.
    printf("Average: %.2f\n", avg);   // Print average value of integers.

    free(arr);   // Free memory after use.
}
```
