pthread_mutex_t lock;

int allocated_size = 0;  // Track total memory usage

void* allocate_record(size_t limit) {
    void *ptr = NULL;

    pthread_mutex_lock(&lock);
    if (allocated_size + sizeof(Record) > limit) {
        fprintf(stderr, "Memory allocation failed: exceeded memory limit.\n");
        return NULL;
    }

    ptr = malloc(sizeof(Record));
    allocated_size += sizeof(Record);
    pthread_mutex_unlock(&lock);

    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
