int safe_function(long **offsets, int **keys, record ***records, int num_records) {
    if (num_records > INT_MAX || num_records < 0) {
        fprintf(logFile, "Error: Invalid input range.\n");
        return -1;  // Return error code on invalid input
    }

    pthread_mutex_lock(&lock);   // Lock mutex for thread safety

    *offsets = (long*) malloc(num_records * sizeof(long));
    if (*offsets == NULL) {
        fprintf(logFile, "Error: Failed to allocate memory for offsets.\n");
        pthread_mutex_unlock(&lock);  // Unlock mutex before returning error code
        return -1;
    }

    *keys = (int*) malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        fprintf(logFile, "Error: Failed to allocate memory for keys.\n");
        free(*offsets);  // Free previously allocated memory on error
        pthread_mutex_unlock(&lock);  // Unlock mutex before returning error code
        return -1;
    }

    *records = (record**) malloc(num_records * sizeof(record*));
    if (*records == NULL) {
        fprintf(logFile, "Error: Failed to allocate memory for records.\n");
        free(*keys);  // Free previously allocated memory on error
        free(*offsets);  // Also free offsets in case of error
        pthread_mutex_unlock(&lock);  // Unlock mutex before returning error code
        return -1;
    }

    srand(time(NULL));   // Seed random number generator with current time

