    }
}

void serialize(long *offsets, int keysSize, int *keys, int recordsSize, record_t **records, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Failed to open the file for writing\n");
        return;
    }

    fwrite(offsets, sizeof(long), keysSize, file);
    fwrite(keys, sizeof(int), keysSize, file);

    for (int i = 0; i < recordsSize; i++) {
        fwrite(&records[i]->value, sizeof(int), 1, file);
    }

    fclose(file);
}

void deserialize(long **offsets, int *keysSize, int **keys, int *recordsSize, record_t ***records, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Failed to open the file for reading\n");
        return;
    }

    // Read offsets and keys size first
    int itemsRead = fread(keysSize, sizeof(int), 1, file);
    *offsets = malloc(sizeof(long)**keysSize);
    *keys = malloc(sizeof(int)**keysSize);

    if (itemsRead != 1 || *offsets == NULL || *keys == NULL) {
        printf("Failed to read offsets and keys size\n");
        fclose(file);
        return;
    }

    itemsRead = fread(*offsets, sizeof(long), *keysSize, file);
    itemsRead += fread(*keys, sizeof(int), *keysSize, file);

    if (itemsRead != *keysSize*2) {
        printf("Failed to read offsets and keys\n");
        free(*offsets);
        free(*keys);
        fclose(file);
        return;
    }

    // Read records size
    itemsRead = fread(recordsSize, sizeof(int), 1, file);
    *records = malloc(sizeof(record_t*)**recordsSize);

    if (itemsRead != 1 || *records == NULL) {
        printf("Failed to read records size\n");
        free(*offsets);
        free(*keys);
        fclose(file);
        return;
    }

    for (int i = 0; i < *recordsSize; i++) {
        (*records)[i] = malloc(sizeof(record_t));

        if ((*records)[i] == NULL) {
            printf("Failed to allocate memory for record\n");
            // Clean up previously allocated records
            for (int j = 0; j < i; j++) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            fclose(file);
            return;
        }

        itemsRead = fread(&(*records)[i]->value, sizeof(int), 1, file);
        if (itemsRead != 1) {
            printf("Failed to read record value\n");
            // Clean up allocated records and values
            for (int j = 0; j <= i; j++) {
                free((*records)[j]);
            }
            free(*offsets);
            free(*keys);
            fclose(file);
            return;
        }
    }

    fclose(file);
}
```
Please note that the code is simplified and does not cover potential external dependencies or error handling in detail. Also, dynamic memory allocation/deallocation can be more efficient if implemented properly based on your specific requirements.
