['Here is a possible implementation of the task in C. This code includes memory allocation, initialization, and deallocation for various data structures. Please note that you would need to link `-lm` flag when compiling the program if you want to use `math.h` functions such as `log()` and `pow()`:

```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <assert.h>
#include <math.h>

typedef struct vector {
    float x;
    float y;
} Vector;

typedef struct record {
    int id;
} Record;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);

    if (ptr == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    return ptr;
}

void safe_free(void** ptr) {
    assert(*ptr != NULL);
    free(*ptr);
    *ptr = NULL;
}

int* allocate_integer_array(size_t size) {
    int* arr = safe_malloc(sizeof(int) * size);

    for (size_t i = 0; i < size; ++i) {
        arr[i] = 0; // or initialize with some other value
    }

    return arr;
}

char* allocate_string(size_t length) {
    char* str = safe_malloc(sizeof(char) * (length + 1)); // +1 for null-terminator

    memset(str, '\0', sizeof(char) * (length + 1)); // initialize with null characters

    return str;
}

Vector* allocate_vector_array(size_t size) {
    Vector* vec = safe_malloc(sizeof(Vector) * size);

    for (size_t i = 0; i < size; ++i) {
        vec[i].x = 0.0f; // or initialize with some other value
        vec[i].y = 0.0f; // or initialize with some other value
    }

    return vec;
}

Record* allocate_record_array(size_t size, int min, int max) {
    srand((unsigned int) time(NULL));

    Record* rec = safe_malloc(sizeof(Record) * size);

    for (size_t i = 0; i < size; ++i) {
        rec[i].id = min + rand() % (max - min + 1); // generate random id in range [min, max]
    }

    return rec;
}

void manage_memory(size_t mem_limit) {
    size_t total = 0;

    while (total < mem_limit) {
        size_t array_size = pow(2, log((double)mem_limit - total) / log(2.0)); // get largest power of 2 that fits in remaining memory

        int* arr1 = allocate_integer_array(array_size);
        char* str1 = allocate_string(array_size);
        Vector* vec1 = allocate_vector_array(array_size);
        Record* rec1 = allocate_record_array(array_size, 0, RAND_MAX); // assuming ids are in range [0, RAND_MAX]

        total += array_size * (sizeof(int) + sizeof(char) + sizeof(Vector) + sizeof(Record));

        safe_free((void**)&arr1);
        safe_free((void**)&str1);
        safe_free((void**)&vec1);
        safe_free((void**)&rec1);
    }
}
```

This code is a basic demonstration and does not consider factors such as memory alignment, padding, thread safety or optimizations. In real-world applications, you might want to use more advanced techniques for better performance and control over resources. Also, make sure to check `malloc` return values in your production code to handle allocation failures gracefully.
']

