["```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    double value;
    int* key_ptr;
    char* str_buffer;
} data_point;

int allocate_data(data_point** data, size_t count, const int* keys, 
                  const char* external_buffer, size_t buffer_size) {

    srand(time(NULL)); // seed the random number generator

    *data = calloc(count, sizeof(data_point));
    if (*data == NULL) return -1; // allocation failure

    for (size_t i = 0; i < count; i++) {
        (*data)[i].value = ((double)rand() / RAND_MAX) * 10.0;

        (*data)[i].key_ptr = malloc(sizeof(int));
        if ((*data)[i].key_ptr == NULL) return -1; // allocation failure

        *((*data)[i].key_ptr) = keys[i];

        size_t str_len = strnlen(&external_buffer[i], buffer_size);
        if (str_len >= buffer_size) return -2; // string length error

        (*data)[i].str_buffer = malloc(str_len + 1);
        if ((*data)[i].str_buffer == NULL) return -1; // allocation failure

        strncpy((*data)[i].str_buffer, &external_buffer[i], str_len);
        (*data)[i].str_buffer[str_len] = '\0';
    }

    return 0; // success
}

void deallocate_data(data_point* data, size_t count) {
    for (size_t i = 0; i < count; i++) {
        free(data[i].key_ptr);
        free(data[i].str_buffer);
    }

    free(data);
}
```
In the above code, `allocate_data` function allocates memory for `count` number of `data_point` structures. Each structure's double field is set to a random value between 0 and 10 (inclusive), its integer pointer gets allocated space and assigned with corresponding key from `keys` array, and the string buffer from `external_buffer` is copied into it with proper null termination. If there are any allocation failures or the length of string exceeds provided buffer size, it returns appropriate error codes.

The function `deallocate_data` frees up all allocated memory when the function is finished with it. It goes through each data point in the array and frees its key pointer and string buffer before freeing the entire data array. This ensures that no leaks occur due to unfreed pointers.
