char* encryptDecrypt(const EVP_CIPHER *cipher, const char *key, const char *iv, const char *input, int enc) {
    // Initialize OpenSSL encryption context
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_CipherInit(ctx, cipher, (unsigned char *)key, (unsigned char *)iv, enc)) {
        fprintf(stderr, "Failed to initialize OpenSSL encryption context\n");
        return NULL;
    }

    // Allocate memory for output buffer and perform the encryption/decryption
    size_t len = strlen(input);
    char *output = malloc(len + 1);
    int outl, tmpl;
    if (!EVP_CipherUpdate(ctx, (unsigned char *)output, &outl, (const unsigned char *)input, len)) {
        fprintf(stderr, "Failed to perform OpenSSL encryption update\n");
        free(output);
        return NULL;
    }
    if (!EVP_CipherFinal(ctx, (unsigned char *)(output + outl), &tmpl)) {
        fprintf(stderr, "Failed to perform OpenSSL encryption finalization\n");
        free(output);
        return NULL;
    }

    // Clean up and return the output buffer
    EVP_CIPHER_CTX_free(ctx);
    output[outl + tmpl] = '\0';  // Null-terminate the string
    return output;
}

int main(int argc, char *argv[]) {
    int c;
    const EVP_CIPHER *cipher = NULL;
    const char *key = NULL;
    const char *iv = NULL;
    int enc = 1;  // By default, encrypt the input string
    FILE *inputFile = stdin;
    FILE *outputFile = stdout;

    while ((c = getopt(argc, argv, "e:d:k:i:o:a:")) != -1) {
        switch (c) {
            case 'e':
                enc = 1;  // Encrypt the input string
                break;
            case 'd':
                enc = 0;  // Decrypt the input string
                break;
            case 'k':
                key = optarg;  // Set the encryption/decryption key
                break;
            case 'i':
                if ((inputFile = fopen(optarg, "r")) == NULL) {
                    fprintf(stderr, "Failed to open input file\n");
                    return EXIT_FAILURE;
                }
                break;
            case 'o':
                if ((outputFile = fopen(optarg, "w")) == NULL) {
                    fprintf(stderr, "Failed to open output file\n");
                    return EXIT_FAILURE;
                }
                break;
            case 'a':
                // Set the cipher based on the command line option (this is just an example and not a real code)
                if (!strcmp(optarg, "AES")) {
                    cipher = EVP_aes_256_cbc();
                } else if (!strcmp(optarg, "DES")) {
                    cipher = EVP_des_ede3_cfb();
                }
                break;
            default:
                fprintf(stderr, "Unknown option character '\\x%x'.\n", optopt);
                return EXIT_FAILURE;
        }
    }

    if (!cipher || !key) {
        fprintf(stderr, "Cipher and key must be specified\n");
        return EXIT_FAILURE;
    }

    // Read the input string from file or stdin
    char buffer[4096];
    size_t len = fread(buffer, 1, sizeof(buffer) - 1, inputFile);
    if (ferror(inputFile)) {
        fprintf(stderr, "Failed to read from input file\n");
        return EXIT_FAILURE;
    }
    buffer[len] = '\0';

    // Perform the encryption/decryption
    char *output = encryptDecrypt(cipher, key, iv, buffer, enc);
    if (!output) {
        return EXIT_FAILURE;  // Error during OpenSSL operations
    }

    // Write the output to file or stdout
    fwrite(output, 1, strlen(output), outputFile);
    if (ferror(outputFile)) {
        fprintf(stderr, "Failed to write to output file\n");
        return EXIT_FAILURE;
    }

    free(output);
    fclose(inputFile);
    fclose(outputFile);

    return EXIT_SUCCESS;
}
