use std::sync::{Arc, Mutex};
use http::uri::Uri;
use log::info;
use serde_json::Value;

struct Record {
    int_value: i32,
    double_value: f64,
}

struct Data<'a> {
    long_offsets: Arc<Mutex<Vec<i64>>>,
    int_keys: Arc<Mutex<Vec<i32>>>,
    double_values: Arc<Mutex<Vec<f64>>>,
    records: Arc<Mutex<Vec<Record>>>,
}

pub struct HttpClient {
    data: Data,
    disable_certificate_validation: bool,
    enable_logging: bool,
}

impl HttpClient {
    pub fn new(disable_certificate_validation: bool, enable_logging: bool) -> Self {
        Self {
            data: Data {
                long_offsets: Arc::new(Mutex::new(Vec::new())),
                int_keys: Arc::new(Mutex::new(Vec::new())),
                double_values: Arc::new(Mutex::new(Vec::new())),
                records: Arc::new(Mutex::new(Vec::new())),
            },
            disable_certificate_validation,
            enable_logging,
        }
    }

    pub fn create_request(&self, url: &str) -> Result<Uri, Box<dyn std::error::Error>> {
        let uri = Uri::from_static(url)?;

        if self.enable_logging {
            info![uri]
        }

        Ok(uri)
    }

    pub fn add_record(&self, record: Value) -> Result<(), Box<dyn std::error::Error>> {
        let record = serde_json::from_value(record)?;

        self.data.records.lock().unwrap().push(record);

        if self.enable_logging {
            info![&format![self.data]]
        }

        Ok(())
    }
}
```
