typedef struct {
    double value;
    char *name;
    int index;
} data_point;

int create_data(size_t num, data_point **array) {
    size_t i, total_memory = 0;
    *array = calloc(num, sizeof(data_point)); // Allocate memory for array of structures

    if (*array == NULL) return -1; // Handle allocation failure

    for (i=0; i<num; i++) { 
        total_memory += sizeof(data_point); // Add the size of each data point to our total

        // Allocate memory for name and initialize it
        (*array)[i].name = malloc(20);
        if ((*array)[i].name == NULL) {
            free_all(*array, i); 
            return -1; // Handle allocation failure
        }
        strcpy((*array)[i].name, "example");

        (*array)[i].value = rand() % 100; // Initialize value with random number
        (*array)[i].index = i; // Initialize index with loop counter
    }

    if (total_memory > MAX_MEMORY) { // If total memory exceeds limit, free and return error code
        free_all(*array, num); 
        return -1; 
    }

    return 0; // Return success code
}

void free_all(data_point *array, size_t num) {
    for (size_t i=0; i<num; i++) free(array[i].name); // Free the memory of each name in the array

    free(array); // Free the entire array
}
