["Here is a basic example in C that demonstrates some aspects of the task. This code will need to be expanded significantly for full functionality, including error handling, logging, dynamic resizing of the hash table, and network packet management. 

```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <assert.h>

#define MAX_TSI 500
#define MAX_PACKETS 100

typedef struct {
    char ip[INET6_ADDRSTRLEN];
    int port;
    void *packets[MAX_PACKETS];
    size_t packet_count;
} TSI;

typedef struct HashNode {
    TSI *tsi;
    struct HashNode *next;
} HashNode;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static TSI* tsiList[MAX_TSI] = {NULL};
static size_t listCount = 0;
static HashNode *hashTable[MAX_TSI];

void addTsi(const char *ip, int port) {
    assert(listCount < MAX_TSI);

    pthread_mutex_lock(&lock);

    // Check if TSI with this ip already exists.
    HashNode *node = hashTable[port % MAX_TSI];
    while (node) {
        assert(strcmp(ip, node->tsi->ip));  // Assuming IPs are unique within list
        node = node->next;
    }

    TSI *newTsi = malloc(sizeof(TSI));
    strncpy(newTsi->ip, ip, INET6_ADDRSTRLEN);
    newTsi->port = port;
    newTsi->packet_count = 0;

    HashNode *hashNode = malloc(sizeof(HashNode));
    hashNode->tsi = newTsi;
    hashNode->next = hashTable[port % MAX_TSI];
    hashTable[port % MAX_TSI] = hashNode;

    tsiList[listCount++] = newTsi;

    pthread_mutex_unlock(&lock);
}
```
