["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct UEContext {
    char ueID[256];
    int rrcConnectionInformationTag;
    int securityKey;
} UEContext;

typedef struct LTEUEContextList {
    UEContext* list;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} LTEUEContextList;

// Initialize a new UE Context List with an initial capacity
LTEUEContextList* initUEContextList(size_t capacity) {
    LTEUEContextList* list = malloc(sizeof(LTEUEContextList));
    if (list == NULL) return NULL;

    list->capacity = capacity;
    list->size = 0;

    pthread_mutex_init(&list->lock, NULL);

    // Allocate memory for the list items
    list->list = malloc(sizeof(UEContext) * list->capacity);
    if (list->list == NULL) {
        free(list);
        return NULL;
    }

    return list;
}

// Add an item to the UE Context List, growing the list if necessary
int addUEContextToList(LTEUEContextList* list, const char* ueID, int rrcConnectionInformationTag, int securityKey) {
    // Validate input parameters
    if (list == NULL || ueID == NULL) return -1;

    pthread_mutex_lock(&list->lock);

    // Grow the list if necessary
    if (list->size >= list->capacity) {
        size_t newCapacity = list->capacity * 2;
        UEContext* newList = realloc(list->list, sizeof(UEContext) * newCapacity);

        // Handle allocation failure
        if (newList == NULL) return -1;

        list->list = newList;
        list->capacity = newCapacity;
    }

    // Add the item to the list
    strncpy(list->list[list->size].ueID, ueID, sizeof(list->list[list->size].ueID) - 1);
    list->list[list->size].rrcConnectionInformationTag = rrcConnectionInformationTag;
    list->list[list->size].securityKey = securityKey;

    list->size++;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

// Free all memory associated with a UE Context List
void freeUEContextList(LTEUEContextList* list) {
    if (list == NULL) return;

    pthread_mutex_destroy(&list->lock);

    // Free the list items
    if (list->list != NULL) {
        free(list->list);
    }

    free(list);
}
