```c
#include <stdio.h>
#include <openssl/evp.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>

#define MAX_BUFFER 4096

typedef struct {
    const EVP_CIPHER *cipher;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} cipher_config_t;

int perform_crypt(FILE* in, FILE* out, int do_encrypt, const EVP_CIPHER *cipher, const unsigned char *key, const unsigned char *iv) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!EVP_CipherInit(ctx, cipher, key, iv, do_encrypt)) {
        /* Error handling */
        return 0;
    }

    unsigned char inbuf[MAX_BUFFER], outbuf[MAX_BUFFER + EVP_MAX_BLOCK_LENGTH];
    int inlen, outlen;
    for (;;) {
        inlen = fread(inbuf, 1, MAX_BUFFER, in);
        if (inlen <= 0) break; // End of file or error.
        if (!EVP_CipherUpdate(ctx, outbuf, &outlen, inbuf, inlen)) {
            /* Error handling */
            return 0;
        }
        fwrite(outbuf, 1, outlen, out); // Write output to file/socket.
    }

    if (!EVP_CipherFinal(ctx, outbuf, &outlen)) {
        /* Error handling */
        return 0;
    }
    fwrite(outbuf, 1, outlen, out); // Write final output to file/socket.

    EVP_CIPHER_CTX_free(ctx);

    return 1;
}

int main(int argc, char* argv[]) {
    cipher_config_t config = {{0}};
    const char *infile = NULL, *outfile = NULL;
    int do_encrypt = 0; // Default to decrypt.

    int opt;
    while ((opt = getopt(argc, argv, "e:d:k:i:o:a:")) != -1) {
        switch (opt) {
            case 'e': 
                do_encrypt = 1;
                break;
            case 'd':
                do_encrypt = 0;
                break;
            case 'k': 
                strncpy(config.key, optarg, EVP_MAX_KEY_LENGTH);
                break;
            case 'i': 
                infile = optarg;
                break;
            case 'o': 
                outfile = optarg;
                break;
            case 'a':
                if (!strcmp(optarg, "AES")) {
