typedef struct Session {
    long* offsets;
    int* keys;
    Record** records;
    uLongf compressedSize;
    Bytef* compressedData;
    size_t recordCount;
} Session;

Session* createSession(size_t size) {
    Session* session = malloc(sizeof(Session));
    if (session == NULL) {
        // Handle allocation failure
        return NULL;
    }

    session->offsets = calloc(size, sizeof(long));
    session->keys = calloc(size, sizeof(int));
    session->records = malloc(size * sizeof(Record*));
    if (session->offsets == NULL || session->keys == NULL || session->records == NULL) {
        // Handle allocation failure
        freeSession(session);
        return NULL;
    }

    session->recordCount = size;
    for (size_t i = 0; i < size; ++i) {
        session->records[i] = malloc(sizeof(Record));
        if (session->records[i] == NULL) {
            // Handle allocation failure
            freeSession(session);
            return NULL;
        }
    }

    return session;
}

void compressSessionData(Session* session, const Bytef* source, uLong sourceLen) {
    if (compress(source, &sourceLen)) {
        // Handle compression failure
        return;
    }

    session->compressedSize = sourceLen;
    session->compressedData = malloc(sourceLen);
    memcpy(session->compressedData, source, sourceLen);
}

void freeSession(Session* session) {
    if (session == NULL) {
        return;
    }

    for (size_t i = 0; i < session->recordCount; ++i) {
        free(session->records[i]);
    }
    free(session->offsets);
    free(session->keys);
    free(session->compressedData);

    free(session);
}
```
