    pthread_mutex_t lock;
} ArrayManager;

void initArrayManager(ArrayManager* manager) {
    pthread_mutex_init(&manager->lock, NULL);

    manager->doubles = malloc(sizeof(double));  // initial capacity
    manager->strings = malloc(sizeof(char*));
    manager->datas   = malloc(sizeof(data*));
    manager->doublesSize = 0;
    manager->stringsSize = 0;
    manager->datasSize = 0;
}

void addDouble(ArrayManager* manager, double value) {
    pthread_mutex_lock(&manager->lock);

    if (++manager->doublesSize > sizeof(manager->doubles) / sizeof(double)) {  // realloc when full
        manager->doubles = realloc(manager->doubles, manager->doublesSize * 2 * sizeof(double));   // exponential growth
    }

    manager->doubles[manager->doublesSize - 1] = value;

    pthread_mutex_unlock(&manager->lock);
}

