['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_MEMORY 10 * 1024 * 1024 // 10MB
#define MAX_RECORDS 1000000 // up to 1 million records

typedef struct {
    int key;
    double value;
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t memory_used = 0;
int isFailed = 0; // flag to track if any allocation failed

void* allocate(size_t size) {
    pthread_mutex_lock(&lock);
    void *ptr = malloc(size);

    if (ptr != NULL) {
        memory_used += size;
        printf("Allocated %zu bytes. Total: %zu\n", size, memory_used);

        // check if we've exceeded the limit and free the allocated memory if so
        if (memory_used > MAX_MEMORY) {
            isFailed = 1;
            printf("Error: Memory allocation failed. Total memory used exceeds 10MB\n");
            free(ptr);
            ptr = NULL;
        }
    } else {
        isFailed = 1;
        printf("Error: Memory allocation failed.\n");
    }

    pthread_mutex_unlock(&lock);
    return ptr;
}

int allocateMemory(long **offsets, int **keys, double **values, Record **records) {
    *offsets = allocate(100 * sizeof(**offsets));
    *keys = allocate(100 * sizeof(**keys));
    *values = allocate(100 * sizeof(**values));

    if (isFailed) return -1; // memory allocation failed

    srand((unsigned int) time(NULL));
    for (int i = 0; i < 100 && !isFailed; ++i) {
        (*records)[i].key = rand() % 200; // random value within a range
        (*records)[i].value = ((double)rand() / (double)(RAND_MAX)) * 360.0; // random double value within another range
    }

    return !isFailed ? 0 : -1; // indicate success or failure
}

void deallocateMemory(long **offsets, int **keys, double **values, Record **records) {
    if (*offsets) free(*offsets);
    if (*keys) free(*keys);
    if (*values) free(*values);
    if (*records && !isFailed) free(*records); // only free if allocation succeeded
}

void saveRecords(Record *records, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: Failed to open file for writing.\n");
        return;
    }

    int records_written = fwrite(records, sizeof(*records), MAX_RECORDS, file);
    fclose(file);

    if (records_written != MAX_RECORDS) {
        printf("Error: Failed to write all records to the file.\n");
    } else {
        printf("Successfully saved %d records to the file.\n", records_written);
    }
}
