static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int calculateDistances(size_t numPoints, double minRange, double maxRange) {
    int result = 0;

    // Allocate memory for all arrays.
    double *distances = malloc(numPoints * numPoints * sizeof(*distances));
    Point *sources = malloc(numPoints * sizeof(*sources));
    Point *dests = malloc(numPoints * sizeof(*dests));
    int *keys = malloc(numPoints * sizeof(*keys));

    if (!distances || !sources || !dests || !keys) {
        result = 1; // Memory allocation failure.
        goto cleanup;
    }

    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < numPoints && !result; ++i) {
        sources[i].x = minRange + ((double) rand() / RAND_MAX) * (maxRange - minRange);
        sources[i].y = minRange + ((double) rand() / RAND_MAX) * (maxRange - minRange);
        dests[i].x = minRange + ((double) rand() / RAND_MAX) * (maxRange - minRange);
        dests[i].y = minRange + ((double) rand() / RAND_MAX) * (maxRange - minRange);
        keys[i] = i; // Use the index as a key. Adjust as per requirement.
    }
    pthread_mutex_unlock(&mutex);

    for (size_t i = 0; i < numPoints && !result; ++i) {
        for (size_t j = 0; j < numPoints && !result; ++j) {
            double dx = sources[i].x - dests[j].x;
            double dy = sources[i].y - dests[j].y;
            distances[i * numPoints + j] = sqrt(dx*dx + dy*dy);
        }
    }

cleanup:
    pthread_mutex_destroy(&mutex); // It's okay to destroy a mutex that was never locked.
    free(distances);
    free(sources);
    free(dests);
    free(keys);

    return result;
}
```
