    int end;
    pthread_mutex_t *lock;
} ThreadData;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void* calculateDistances(void* arg) {
    ThreadData *data = (ThreadData*)arg;
    for (int i = data->start; i < data->end; ++i) {
        double dx = points[i].x - points[i + 1].x;
        double dy = points[i].y - points[i + 1].y;
        pthread_mutex_lock(data->lock);
        distances[i] = sqrt(dx * dx + dy * dy);
        pthread_mutex_unlock(data->lock);
    }
    return NULL;
}

void allocateMemoryAndInit() {
    srand((unsigned int)time(NULL));  // seeding the random number generator

    keys = (int*)malloc(sizeof(int) * 10000);
    if (keys == NULL) exit(-1);  // memory allocation check

    points = (Point*)malloc(sizeof(Point) * 10000);
    if (points == NULL) exit(-1);  // memory allocation check

    colors = (Color*)malloc(sizeof(Color) * 10000);
    if (colors == NULL) exit(-1);  // memory allocation check

    distances = (double*)calloc(10000, sizeof(double));
    if (distances == NULL) exit(-1);  // memory allocation check

    for (int i = 0; i < 10000; ++i) {
        keys[i] = i;
        points[i].x = ((double)rand() / RAND_MAX) * (upperLimit - lowerLimit) + lowerLimit;  // generate a random coordinate within the specified range
        points[i].y = ((double)rand() / RAND_MAX) * (upperLimit - lowerLimit) + lowerLimit;
    }
}

void parallelProcessing(int threadCount, int pointCount) {
    pthread_t threads[threadCount];
    ThreadData data[threadCount];

    for (int i = 0; i < threadCount; ++i) {
        data[i].start = i * (pointCount / threadCount);
        data[i].end = (i + 1) * (pointCount / threadCount);
        if(i == threadCount - 1) // For the last thread to account for possible extra points
            data[i].end += pointCount % threadCount;
        data[i].lock = &mutex;

        int rc = pthread_create(&threads[i], NULL, calculateDistances, (void*)&data[i]);
        if(rc) {
            printf("ERROR: return code from pthread_create() is %d\n", rc);
            exit(-1);
        }
    }

    for(int i = 0; i < threadCount; ++i) {
        int rc = pthread_join(threads[i], NULL);
        if (rc) {
            printf("ERROR: return code from pthread_join() is %d\n", rc);
            exit(-1);
        }
    }
}
```
