static COUNT: Mutex<u32> = Mutex::new(0);

fn create_directory(name: &str) -> Result<DirEntry, String> {
    let mut count = COUNT.lock().unwrap();

    // Checking system load before creating a directory
    if *count > 100 { 
        return Err("Reached max concurrent operations.".to_string());
    }
    *count += 1;

    let env_path = env::var("DIRPATH").unwrap_or(String::new());
    let dir_entry: DirEntry;

    // Checking if environment variable is set
    if !env_path.is_empty() {
        match fs::DirBuilder::new().current_dir().join(name) {
            Ok(val) => {
                dir_entry = val;
            },
            Err(_) => return Err("Error creating directory.".to_string())
        };
    } else {
       // Create a new directory and set environment variable 
       match fs::create_dir(&name) {
           Ok(val) => {
               env::set_var("DIRPATH", &format_path_str(name));
               dir_entry = val;
            },
            Err(_) => return Err("Error creating directory.".to_string())
       }; 
    }

    // A mechanism to limit the maximum number of concurrent directory creations based on system load metrics (e.g., CPU usage, available memory).
    thread::spawn(move || {
