#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int value;
} Record;

typedef struct hashNode {
    Record* record;
    struct hashNode* next;
} HashNode;

void insertRecord(HashNode** table, long* offsets, int* keys, int size) {
    srand(time(NULL));

    for (int i = 0; i < size; ++i) {
        Record* record = malloc(sizeof(Record));

        if (record == NULL) {
            printf("Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        int value = rand() % 100; // Random value in range [0, 99]
        record->value = value;

        long offset = abs(rand()) % size;
        offsets[i] = offset;

        int key = keys[offset];
        HashNode* node = malloc(sizeof(HashNode));

        if (node == NULL) {
            printf("Memory allocation failed.\n");
            free(record);
            exit(EXIT_FAILURE);
        }

        node->record = record;
        node->next = table[key];
        table[key] = node;
    }
}

int main() {
    int size = 10;

    HashNode** hashTable = malloc(size * sizeof(HashNode*));
    long* offsets = malloc(size * sizeof(long));
    int* keys = malloc(size * sizeof(int));

    if (hashTable == NULL || offsets == NULL || keys == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        hashTable[i] = NULL;
        offsets[i] = -1;
        keys[i] = i * 23 % size; // Simple hash function
    }

    insertRecord(hashTable, offsets, keys, size);

    for (int i = 0; i < size; ++i) {
        printf("Key: %d, Value: %d\n", keys[offsets[i]], hashTable[keys[offsets[i]]]->record->value);

        HashNode* node = hashTable[keys[offsets[i]]];
        free(node->record);
        free(node);
    }

    free(hashTable);
    free(offsets);
    free(keys);

    return 0;
}
```
