        while (node != NULL) {
            if (node->sg.ueid == ueid) {
                fprintf(stderr, "Error: UEID already exists\n");
                return NULL;
            }

            node = node->next;
        }
    }

    SG* sg = (SG*)malloc(sizeof(SG));
    sg->ueid = ueid;
    memcpy(sg->re, re, sizeof(RE) * 50);
    sg->qos = qos;

    return sg;
}

// Function to handle memory deallocation and thread safety
void deleteSg(int ueid) {
    unsigned int index = hash(ueid);
    Node** prev = &hashTable[index];
    pthread_mutex_lock(&lock);

    while (*prev != NULL && (*prev)->sg.ueid != ueid) {
        prev = &((*prev)->next);
    }

    if (*prev != NULL) {
        Node* nodeToDelete = *prev;
        *prev = nodeToDelete->next;
        free(nodeToDelete->sg);
        free(nodeToDelete);
        size--;
    }

    pthread_mutex_unlock(&lock);
}
