#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
} Record;

int read_data(long *offsets, int *keys, size_t count) {
    FILE* fp = fopen("inputfile", "r");
    if (fp == NULL) return -1; // Error opening file.

    for (size_t i = 0; i < count; ++i) {
        if (fscanf(fp, "%ld %d", &offsets[i], &keys[i]) != 2) {
            fclose(fp); 
            return -1; // Error reading file.
        }
    }

    fclose(fp);
    return 0;
}

int process_data(size_t initial_size, size_t limit) {
    long *offsets = malloc(initial_size * sizeof(long));
    int *keys = malloc(initial_size * sizeof(int));
    Record *records = calloc(initial_size, sizeof(Record)); // Initialized to 0.

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return -1; // Error allocating memory.
    }

    size_t total = initial_size;

    if (read_data(offsets, keys, initial_size) != 0) {
        free(offsets);
        free(keys);
        free(records);
        return -1; // Error reading data.
    }

    while (total < limit) {
        size_t new_size = total * 2;

        if (new_size > limit) new_size = limit;

        long* new_offsets = realloc(offsets, new_size * sizeof(long));
        int* new_keys = realloc(keys, new_size * sizeof(int));
        Record* new_records = realloc(records, new_size * sizeof(Record));

        if (new_offsets == NULL || new_keys == NULL || new_records == NULL) {
            free(offsets);
            free(keys);
            free(records);
            return -1; // Error reallocating memory.
        }

        offsets = new_offsets;
        keys = new_keys;
        records = new_records;

        if (read_data(&offsets[total], &keys[total], new_size - total) != 0) {
            free(offsets);
            free(keys);
            free(records);
            return -1; // Error reading data.
        }

        total = new_size;
    }

    // Processing of the arrays and records goes here...

    free(offsets);
    free(keys);
    free(records);

    return 0; // Success.
}
```
In this code, `read_data` reads data from a file named "inputfile" in the format of 'long int' and 'int'. `process_data` is the main function that allocates memory for the arrays and handles dynamic resizing when necessary. It also checks for errors during memory allocation and reallocation and returns appropriate error codes if any occurs. After processing, it frees all allocated memory before exiting.
