using UnityEngine;
using Newtonsoft.Json;
using System.IO;
using System;
using Serilog;
using Serilog.Core;
using System.Collections.Generic;

public class PhysicsSimulation : MonoBehaviour {
    private Logger _logger = new LoggerConfiguration()
        .WriteTo.File("log.txt")
        .CreateLogger();

    public string ConfigPath = "config.json";

    private List<GameObject> objects = new List<GameObject>();
    private Dictionary<string, CollisionHandler> collisionHandlers;

    void Start() {
        LoadConfiguration(ConfigPath);
        InvokeRepeating("LogState", 0f, 5f); // Log state every 5 seconds.
    }

    public void LoadConfiguration(string path) {
        var json = File.ReadAllText(path);
        var config = JsonConvert.DeserializeObject<SimulationConfig>(json);

        foreach (var obj in config.objects) {
            AddObject(obj.type, obj.position, obj.velocity);
        }
    }

    public void AddObject(string type, Vector3 position, Vector3 velocity) {
        var prefab = Resources.Load<GameObject>($"Prefabs/{type}");
        if (prefab == null) throw new Exception("Invalid object type: " + type);

        var obj = Instantiate(prefab, position, Quaternion.identity);
        var rb = obj.GetComponent<Rigidbody>();
        rb.velocity = velocity;
        objects.Add(obj);
    }

    void LogState() {
        foreach (var obj in objects) {
            _logger.Information("Object {@state}", new {
                type = obj.tag,
                position = obj.transform.position,
                velocity = obj.GetComponent<Rigidbody>().velocity
            });
        }
    }

    void OnCollisionEnter(Collision collision) {
        var handler = collisionHandlers[collision.gameObject.tag];
        if (handler != null) {
            handler.HandleCollision(collision);
        } else {
            Debug.LogWarning("No collision handler for object type: " + collision.gameObject.tag);
        }
    }
}

public class CollisionHandler {
    public virtual void HandleCollision(Collision collision) {}
}

[Serializable]
public class SimulationConfig {
    public List<SimulationObject> objects;
}

[Serializable]
public class SimulationObject {
    public string type;
    public Vector3 position;
    public Vector3 velocity;
}
