int find_largest(const int* arr, size_t n) {
    if (n == 0) return -1; // Returning a sentinel value for empty array
    int max = *arr;
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > max) max = arr[i];
    }
    return max;
}

