        exit(EXIT_FAILURE);
    }

    printf("Enter %d integers: ", n);
    for (int i = 0; i < n; ++i) {
        scanf("%d", &arr[i]);
    }

    int max = find_largest(arr, n);
    printf("The largest integer is: %d\n", max);

    // Free memory allocated for array
    free(arr);
}

// Function to initialize EVP_CIPHER structure based on input key size
EVP_CIPHER* init_cipher(int keysize) {
