typedef struct {
    long* timestamps;
    int* keys;
} sensor_record;

int loadSensorData(const char* filePath, sensor_record** bundle) {
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        return -1; // Error code for file open failure
    }

    *bundle = malloc(1000 * sizeof(sensor_record));
    if (*bundle == NULL) {
        fclose(file);
        return -2; // Error code for memory allocation failure
    }

    int count = 0;
    while (!feof(file)) {
        if (count >= 1000) {
            break;
        }

        (*bundle)[count].timestamps = malloc(sizeof(long));
        (*bundle)[count].keys = calloc(4, sizeof(int)); // Assuming each record contains 4 keys

        if ((*bundle)[count].timestamps == NULL || (*bundle)[count].keys == NULL) {
            fclose(file);

            for (int i = 0; i < count; i++) {
                free((*bundle)[i].timestamps);
                free((*bundle)[i].keys);
            }
            free(*bundle);

            return -2; // Error code for memory allocation failure
        }

        fscanf(file, "%ld", (*bundle)[count].timestamps); // Assuming timestamp is the first value in each line
        for (int i = 0; i < 4; i++) { // Assume 4 keys in each line after the timestamp
