void initializeData(dataRecord **records, long *offsets, int *keys, double *values, char ***strings, configStruct *config) {
    pthread_mutex_lock(&mutex); // Lock the mutex to ensure thread-safe execution

    if (config->recordCount == 0) {
        fprintf(stderr, "Array size cannot be zero.\n");
        pthread_mutex_unlock(&mutex); // Unlock before returning
        return;
    }

    *records = malloc(config->recordCount * sizeof(dataRecord));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation failed for records.\n");
        pthread_mutex_unlock(&mutex); // Unlock before returning
        return;
    }

    *offsets = malloc(config->recordCount * sizeof(long));
    if (*offsets == NULL) {
        free(*records);
        *records = NULL;
        fprintf(stderr, "Memory allocation failed for offsets.\n");
        pthread_mutex_unlock(&mutex); // Unlock before returning
        return;
    }

    *keys = malloc(config->recordCount * sizeof(int));
    if (*keys == NULL) {
        free(*records);
        *records = NULL;
        free(*offsets);
        *offsets = NULL;
        fprintf(stderr, "Memory allocation failed for keys.\n");
        pthread_mutex_unlock(&mutex); // Unlock before returning
        return;
    }

    *values = malloc(config->recordCount * sizeof(double));
    if (*values == NULL) {
        free(*records);
        *records = NULL;
        free(*offsets);
        *offsets = NULL;
        free(*keys);
        *keys = NULL;
        fprintf(stderr, "Memory allocation failed for values.\n");
        pthread_mutex_unlock(&mutex); // Unlock before returning
        return;
    }

    srand(time(NULL));
    for (size_t i = 0; i < config->recordCount; ++i) {
        (*records)[i].intValue = rand(); // Assuming a random integer is desired
        (*records)[i].doubleValue = ((double)rand() / RAND_MAX); // Assuming a random double is desired

        int stringLength = 10; // Can be any length
        (*records)[i].stringValue = malloc(stringLength + 1);
        if ((*records)[i].stringValue == NULL) {
            fprintf(stderr, "Memory allocation failed for string value.\n");
            pthread_mutex_unlock(&mutex); // Unlock before returning
            return;
