```c
#include <stdio.h>
#include <stdlib.h>

typedef struct record {
    int value;
} record;

void init_records(int size, int seed) {
    if(size <= 0){
        fprintf(stderr, "Invalid size: %d\n", size);
        return;
    }

    long *offsets = malloc(size * sizeof(long));
    if (offsets == NULL) {
        fprintf(stderr, "Allocation failed for offsets.\n");
        return;
    }

    int *keys = malloc(size * sizeof(int));
    if (keys == NULL) {
        free(offsets);
        fprintf(stderr, "Allocation failed for keys.\n");
        return;
    }

    record *records = malloc(size * sizeof(record));
    if (records == NULL) {
        free(offsets);
        free(keys);
        fprintf(stderr, "Allocation failed for records.\n");
        return;
    }

    srand(seed);  // Seed the random number generator for reproducibility

    // Random number generation with error checking
    for (int i = 0; i < size; i++) {
        offsets[i] = rand();
        keys[i] = rand() % 100;
        records[i].value = rand() % 100;
    }

    // Log the initialization process
    printf("Initialization completed. Size: %d\n", size);

    /* Add functionality to free allocated memory when it is no longer needed */
    free(offsets);
    free(keys);
    free(records);
}
```

This function uses `srand()` to seed the random number generator for reproducibility. If you want a different sequence of pseudo-random numbers each time, do not call this function or provide it with a different value each time. 

