["Here's a basic implementation of your task using C and OpenSSL library:

```c
#include <stdlib.h>
#include <time.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/err.h>

typedef struct record {
    int value;
} Record;

int create_arrays(long *offsets, int *keys, Record **records, 
                  size_t n_elements, int min, int max) {
    // initialize crypto primitives
    AES_KEY aes_key;
    CAMELLIA_KEY camellia_key;
    MD5_CTX md5_ctx;
    SHA_CTX sha1_ctx;
    RSA *rsa = NULL;
    BIGNUM *bn = BN_new();

    // check allocation failures
    if (!offsets || !keys || !records || !BN_pseudo_rand(bn, 128, 0, 0)) {
        return -1; // error code for memory allocation failure
    }

    *records = (Record *) malloc(n_elements * sizeof(Record));

    if (!*records) {
        return -1; // error code for memory allocation failure
    }

    srand((unsigned int) time(NULL));

    for(size_t i = 0; i < n_elements; ++i) {
        offsets[i] = rand();
        keys[i] = (rand() % (max - min + 1)) + min;

        (*records)[i].value = keys[i]; // set record value to a key's random integer
    }

    AES_set_encrypt_key(keys, 128, &aes_key);
    CAMELLIA_set_key(keys, 128, &camellia_key);
    MD5_Init(&md5_ctx);
    SHA_Init(&sha1_ctx);

    rsa = RSA_generate_key(1024, 65537, NULL, NULL);

    // clean up crypto primitives
    AES_set_encrypt_key(NULL, 128, &aes_key);
    CAMELLIA_set_key(NULL, 128, &camellia_key);
    MD5_Init(&md5_ctx);
    SHA_Init(&sha1_ctx);

    RSA_free(rsa);
    BN_clear_free(bn);

    return n_elements; // success code for number of records created
}
```

Please note that this is a simplified example and may not cover all the aspects you mentioned such as efficiently handling cryptographic resources or ensuring the function is compatible with OpenSSL. This implementation also doesn't handle errors related to AES, Camellia, MD5, SHA, RSA ciphering or generating keys for them. For production code, consider adding error checks and exception handling mechanisms.
"]

