        var config = new ConfigurationBuilder()
            .AddJsonFile("appsettings.json", true, true)
            .Build();

        // Load user account validation settings from external JSON file
        UserAccountSettings settings = JsonConvert.DeserializeObject<UserAccountSettings>(config["user_account"]);

        // Configure ASP.NET Identity framework for user accounts and passwords
        var identityBuilder = services.AddIdentityCore<ApplicationUser>();
        var options = identityBuilder.Options;

        // Customize username and password requirements
        options.Password.RequiredLength = settings.PasswordRequiredLength;
        options.Password.RequireNonAlphanumeric = settings.PasswordRequireNonAlphanumeric;
        options.Password.RequireDigit = settings.PasswordRequireDigit;

        // Configure user lockout defaults
        options.Lockout.DefaultLockoutTimeSpan = TimeSpan.FromMinutes(settings.DefaultLockoutTime);
        options.Lockout.MaxFailedAccessAttempts = settings.MaxFailedAccessAttempts;

        long[] offsetValues = new long[10]; // Allocate memory for 'long' offset values array
        int[] keys = new int[10]; // Allocate memory for 'int' keys array

