Please note that the following code doesn't cover all your requirements, but should give you a starting point:

**C Code:**
```c
#include <pthread.h>
#include <stdlib.h>

typedef struct record {
    int value;
} Record;

// Global variable to hold thread safety
pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;

void *random_number(void *ptr) {
    // Get the parameter passed to this thread 
    Record *record = (Record *) ptr;

    // Lock for writing
    pthread_rwlock_wrlock(&lock);
    record->value = rand();
    pthread_rwlock_unlock(&lock);
}

int main() {
    srand(time(0)); 

    Record *records = malloc(sizeof(Record) * 10); // Allocate memory for records

    if (records == NULL) return EXIT_FAILURE; // Handle allocation failure gracefully

    pthread_t threads[10];

    for(int i = 0; i < 10; ++i) {
        if(pthread_create(&threads[i], NULL, random_number, &records[i]) != 0){
            perror("Failed to create thread");
            return EXIT_FAILURE;
        } 
    }

    for(int i = 0; i < 10; ++i) {
        if (pthread_join(threads[i], NULL) != 0){
            perror("Failed to join thread");
            return EXIT_FAILURE;
        } 
    }

    free(records); // Clean up resources

    return EXIT_SUCCESS;
}
```
**Java Code:**
```java
import java.util.Random;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

class RandomSleepTask implements Runnable {
    private final String serviceName;
    public RandomSleepTask(String serviceName) {
        this.serviceName = serviceName;
    }

    @Override
    public void run() {
        Random random = new Random();

        try {
            System.out.println("Starting " + serviceName);

            // Simulate delay between starts
            Thread.sleep(random.nextInt(5000)); 

            // Send message to messaging system when the service is stopped
            System.out.println("Stopping " + serviceName);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Service was interrupted: " + e.getMessage());
        }
    }
}

public class ServiceManager {
    private static final int POOL_SIZE = 10;

    public static void main(String[] args) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(POOL_SIZE);

        for (int i = 0; i < POOL_SIZE; i++) {
            Runnable task = new RandomSleepTask("Service " + i);
            executor.execute(task);
        }

        // Wait for termination of all tasks 
        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.MILLISECONDS);
    }
}
```
Please note that this code doesn't cover the functional requirements you've provided like cryptographic primitives management or performance monitoring in C and Java. For these, you would need to use appropriate libraries/tools from their respective languages (e.g., OpenSSL for C and Bouncy Castle for Java). 

