```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

struct Activity {
    char* timestamp;
    char* actionType;
    char* metadata;
};

struct Session  {
    int sessionId;
    char* username;
    char* email;
    struct Activity* activities;
};

// Assume we have a linked list implementation for simplicity
typedef struct SessionNode {
    struct Session* session;
    struct SessionNode* next;
} SessionNode;

SessionNode* head = NULL;  // Head of the session list
pthread_mutex_t lock;  // Mutex for thread safety
int MAX_SESSIONS = 10000;  // Maximum number of sessions

void addSession(struct Session* s) {
    pthread_mutex_lock(&lock);

    if (head == NULL) {
        head = malloc(sizeof(SessionNode));
        head->session = s;
        head->next = NULL;
    } else {
        SessionNode* current = head;
        while (current->next != NULL && strcmp(current->session->email, s->email) != 0) {
            if (current->next == NULL) break;
            current = current->next;
        }

        if (strcmp(current->session->email, s->email) == 0) {
            printf("Email already exists.\n");
            return;
        } else {
            SessionNode* newNode = malloc(sizeof(SessionNode));
            newNode->session = s;
            newNode->next = NULL;
            current->next = newNode;
        }
    }

    if (head != NULL) {
        SessionNode* curr = head;
        int count = 0;

        while(curr) {
            count++;
            curr = curr->next;
        }

        if (count >= MAX_SESSIONS) {
            printf("Maximum number of sessions reached. Deleting oldest session.\n");
            SessionNode* toDelete = head;
            head = head->next;
            free(toDelete);
        }
    }

    pthread_mutex_unlock(&lock);
}

void loadSessions(const char* filename, const char* formatType) {
    // Load and deserialize data from different file formats here. For simplicity, I'll assume CSV for now.

    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        printf("Could not open file\n");
        return;
    }

    char line[256];

    while (fgets(line, sizeof(line), file)) {
        struct Session* s = malloc(sizeof(struct Session));

        // Assume CSV format. Replace with appropriate parsing for other formats.
        s->sessionId = atoi(strtok(line, ","));  // Assuming session ID is the first field
        s->username = strdup(strtok(NULL, ","));  // Username
        s->email = strdup(strtok(NULL, ","));  // Email

        addSession(s);  // Add deserialized session to the list.
    }

    fclose(file);
}
```

This code provides a basic structure for loading and deserializing log files into `Session` structures, adding them to a thread-safe linked list, and handling excessive memory usage by deleting oldest sessions when maximum limit is reached. However, the specifics of file format parsing, error checking, logging mechanism, unit tests, etc., are not implemented in this code skeleton due to the complexity of the task at hand.
