['Here's a C function that fulfills the requirements outlined in the prompt. The function uses `calloc` for allocation and error checking, `free` to release memory when necessary, and an external library for random number generation (here assumed to be `librandom`).

```c
#include <stdio.h>
#include <stdlib.h>
#include "external_library.h" // Replace with the appropriate header file of librandom

typedef struct measurement {
    double value;
} measurement;

void init_measurements(int size) {
    if (size <= 0) {
        printf("Error: Invalid array size.\n");
        return;
    }

    // Allocate memory for arrays, check for allocation failure.
    double *values = calloc(size, sizeof(double));
    char *keys = calloc(size, sizeof(char));
    measurement *measurements = calloc(size, sizeof(measurement));

    if (values == NULL || keys == NULL || measurements == NULL) {
        printf("Error: Memory allocation failed.\n");
        // Free any allocated memory and return.
        free(values);
        free(keys);
        free(measurements);
        return;
    }

    srand(time(NULL));  // Seed the random number generator

    // Populate measurements with random values, handle potential NULL pointers.
    for (int i = 0; i < size; i++) {
        if (!values || !keys || !measurements) {
            printf("Error: Null pointer encountered.\n");
            break;  // Exit loop and free memory when a null pointer is detected.
        }

        values[i] = generate_random();  // Assume `generate_random` is a function provided by librandom.
        measurements[i].value = values[i];
    }

    // Logging: print the generated random numbers.
    for (int i = 0; i < size; i++) {
        printf("Generated value at index %d: %f\n", i, values[i]);
    }

    // Free memory when it's no longer needed.
    free(values);
    free(keys);
    free(measurements);
}
```
