```java
import org.apache.http.HttpEntity;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

import com.fasterxml.jackson.databind.ObjectMapper;

public class RestClient {
    private CloseableHttpClient httpClient = HttpClients.createDefault();
    private ObjectMapper objectMapper = new ObjectMapper();

    public void sendPostRequest(String url, User user) throws Exception {
        HttpPost post = new HttpPost(url);

        String jsonInString = objectMapper.writeValueAsString(user);
        StringEntity entity = new StringEntity(jsonInString);
        post.setEntity(entity);
        post.setHeader("Accept", "application/json");
        post.setHeader("Content-type", "application/json");

        CloseableHttpResponse response =  httpClient.execute(post);
        try {
            System.out.println(response.getStatusLine());
            HttpEntity resEntity = response.getEntity();

            if (resEntity != null) {
                String responseString = EntityUtils.toString(resEntity, "UTF-8");
                System.out.println(responseString);
            }
        } finally {
            response.close();
        }
    }
}
```

This is a basic example of how to send POST requests with JSON payloads using the Apache HttpClient library in Java. 

