#define MAX_STRING_LENGTH 20
#define MIN(a,b) (((a)<(b))?(a):(b))

typedef struct {
    float temperature;
    char buffer[MAX_STRING_LENGTH];
} sensor_data;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

float random_range(float min, float max) {
    return (max - min) * ((float)rand() / RAND_MAX) + min;
}

int init_sensor_array(const char* strings[], int numStrings, 
                      sensor_data** sensors, int numSensors, float rangeMin, float rangeMax) {
    if (numStrings < numSensors || numSensors < 1) {
        return -1; // error: insufficient data or invalid number of sensors
    }

    *sensors = malloc(numSensors * sizeof(sensor_data));
    if (*sensors == NULL) {
        return -2; // error: memory allocation failure
    }

    pthread_mutex_lock(&mutex);
    for (int i = 0; i < numSensors; ++i) {
        (*sensors)[i].temperature = random_range(rangeMin, rangeMax);
        strncpy((*sensors)[i].buffer, strings[i], MIN(strlen(strings[i]), MAX_STRING_LENGTH - 1));
        (*sensors)[i].buffer[MAX_STRING_LENGTH - 1] = '\0'; // ensure null termination
    }
    pthread_mutex_unlock(&mutex);

    return numSensors; // success: initialized sensors
}
```
This function uses dynamic memory allocation and mutexes for thread safety. The `random_range` helper function generates a random float within the provided range, which is used to initialize each sensor's temperature value. Strings are copied into buffers using `strncpy`, ensuring that no buffer overflow occurs even if an external module provides strings of varying lengths.

Note: This implementation assumes that you have access to all necessary libraries (stdlib, string, pthread). It also requires the use of compiler with C99 or later support for variable-length arrays and initializer lists for `pthread_mutex`.
