    if (total_memory + size > max_limit) {
        pthread_mutex_unlock(&mutex);
        return -1; // error code for exceeding limit
    }

    *ptr = malloc(size);
    if (*ptr == NULL) {
        pthread_mutex_unlock(&mutex);
        return -2; // error code for allocation failure
    }

    total_memory += size;
    pthread_mutex_unlock(&mutex);
    return 0; // success
}

