        array[i].string = (char*)malloc(sizeof(char) * 100); // Assuming string size is 100 bytes.
        if (!array[i].string) {
            for (int j = 0; j < i; ++j) free(array[j].string);   // Free previously allocated strings.

            free(array);    // Free the entire array before returning error code.

            return -1;  // Memory allocation failed.
        }

        strcpy(array[i].string, "Static string");    // Fill static string data here.
        array[i].key = i + 1;
