u_char* dns_lookup(const char *hostname) {
    struct hostent *hp = gethostbyname(hostname);

    if (hp == NULL) {
        herror("gethostbyname");
        return NULL;
    }

    u_char* addr = malloc(sizeof(u_char)*4);
    addr[0] = ((struct in_addr *) hp->h_addr)->s_addr >> 24;
    addr[1] = ((struct in_addr *) hp->h_addr)->s_addr >> 16;
    addr[2] = ((struct in_addr *) hp->h_addr)->s_addr >> 8;
    addr[3] = (u_char) ((struct in_addr *) hp->h_addr)->s_addr;

    return addr;
}

TSI* create_tsi(const u_char *ip, int port) {
    TSI* tsi = malloc(sizeof(TSI));

    if (tsi == NULL) {
        perror("malloc");
        return NULL;
    }

    memcpy(tsi->ip, ip, 4);
    tsi->port = port;

    return tsi;
}
