}

type StateBox = Arc<Mutex<State>>;

fn create_client(url: &str, disable_cert_validation: bool) -> Result<reqwest::RequestBuilder, reqwest::Error> {
    let client = Client::builder()
        .danger_accept_invalid_certs(disable_cert_validation)
        .build()?;

    Ok(client.get(url))
}

fn create_record_box(int_val: i32, double_val: f64) -> Result<Arc<Record>, &'static str> {
    let record = Record { int_val, double_val };
    Ok(Arc::new(record))
}

fn create_state_box() -> StateBox {
    Arc::new(Mutex::new(State{ records: HashMap::new() }))
}

fn add_record_to_state_box(state_box: &StateBox, int_val: i32, double_val: f64) -> Result<usize, Box<dyn std::error::Error>> {
    let mut state = state_box.lock().unwrap();

    let record = create_record_box(int_val, double_val)?;
    let id = rand::random::<usize>();

    debug_log(&format_string("Adding record with ID: {}", id));

    state.records.insert(id, (record, Instant::now()));

    Ok(id)
}

fn get_record_from_state_box(state_box: &StateBox, id: usize) -> Option<Arc<Record>> {
    let state = state_box.lock().unwrap();
    if let Some((record, _)) = state.records.get(&id).cloned() {
        info_log(&format_string("Getting record with ID: {}", id));
        return Some(record);
    }

    error_log(&format_string("Could not find record with ID: {}", id));
    None
}
```
This code snippet demonstrates the use of unsafe code (`reqwest::Client::builder()`) to create an HTTP client, and uses safe code where possible. The `create_record_box` function allocates a new record structure in a thread-safe manner using `Arc<Record>`. A mutex is used to ensure that only one thread can modify the state at a time.
']

