['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct User {
    char* name;
    int age;
    struct User** friends;
} User;

int memory_usage = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* logFile;
bool loggingEnabled = false;

void* allocate(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        return NULL;
    }

    pthread_mutex_lock(&lock);
    memory_usage += size;
    pthread_mutex_unlock(&lock);

    return ptr;
}

void freeMem(void* ptr, size_t size) {
    if (ptr) {
        free(ptr);

        pthread_mutex_lock(&lock);
        memory_usage -= size;
        pthread_mutex_unlock(&lock);
    }
}

void logDetails() {
    if (!loggingEnabled || !logFile) return;

    fprintf(logFile, "Total allocated memory: %d\n", memory_usage);
}

int initialize_social_network(int num_users, int max_age, const char* log_path, bool enable_logging) {
    srand(time(0));

    loggingEnabled = enable_logging;

    if (loggingEnabled) {
        logFile = fopen(log_path, "w");
        if (!logFile) return -1;  // error while opening file
    }

    User* users = allocate(num_users * sizeof(User));
    if (!users) {
        fprintf(stderr, "Memory allocation failed.\n");
        return -2;  // memory allocation failed
    }

    for (int i = 0; i < num_users; ++i) {
        users[i].name = allocate((rand() % 10 + 5) * sizeof(char));  // random name length between 5 and 15 characters
        if (!users[i].name) {
            fprintf(stderr, "Memory allocation failed.\n");

            // Free previously allocated memory before returning
            for (int j = 0; j < i; ++j) {
                freeMem(users[j].name, strlen(users[j].name));
            }
            freeMem(users, num_users * sizeof(User));

            return -2;  // memory allocation failed
        }

        users[i].age = rand() % max_age + 1;  // random age between 1 and max_age
    }

    logDetails();

    // Free allocated memory when finished with it
    for (int i = 0; i < num_users; ++i) {
        freeMem(users[i].name, strlen(users[i].name));
    }
    freeMem(users, num_users * sizeof(User));

    if (loggingEnabled && logFile) fclose(logFile);

    return 0;  // success
}
```
This code implements a function `initialize_social_network` that allocates memory for an array of users, each with a dynamically generated name and a random age within the given range. It also logs memory usage details to a file if logging is enabled. Memory allocation failures are gracefully handled by returning appropriate error codes and freeing any partially allocated resources. When finished with all allocated memory, it frees this memory using `freeMem` function. This function ensures that all allocated memory is properly freed before the function exits.
