    if (!isset($request['password']) || !preg_match($pattern, $request['password'])) {
        return ['message' => 'error', 'errors' => ['field' => 'Password must be at least 8 characters long and contain at least one uppercase letter, one lowercase letter, one digit, and one special character']];
    }

    return true;
}

function handleRequest($request) {
