        $stmt->execute([$request['name'], $request['email'], $request['password']]);

        if (!sendConfirmationEmail($request['email'])) {
            return json_encode(['message' => 'error', 'errors' => ['email' => 'Failed to send confirmation email']]);
        }
    }

    // Validate inputs
    $errors = validateInputs($request);
    if (!empty($errors)) {
        return json_encode(['message' => 'error', 'errors' => $errors]);
    }

    try {
        $stmt->execute([$request['name'], $request['email'], $request['password']]);
    } catch (PDOException $e) {
        error_log($e->getMessage());

        return json_encode(['message' => 'error', 'errors' => ['database' => 'Failed to save data']]);
    }

    return json_encode(['message' => 'success']);
}

function validateInputs($request) {
    $errors = [];

    if (strlen($request['name']) < 3) {
        $errors['name'] = 'Name must be at least 3 characters long.';
    }

    if (!filter_var($request['email'], FILTER_VALIDATE_EMAIL)) {
        $errors['email'] = 'Email is not valid.';
    }

    $pattern = "/^.*(?=.{8,})(?=.*\d)(?=.*[a-z])(?=.*[A-Z]).*$/";
    if (!preg_match($pattern, $request['password'])) {
        $errors['password'] = 'Password must be at least 8 characters long and contain at least one uppercase letter, one lowercase letter, one digit, and one special character.';
    }

    return $errors;
}

function sendConfirmationEmail($email) {
    $apiUrl = 'https://example-api.com/send_confirmation_email?email=' . $email;
    $retries = 0;

    while ($retries < 3) {
        try {
            $response = file_get_contents($apiUrl);

            if ($response !== false) {
                return true;
            }
        } catch (Exception $e) {
            error_log($e->getMessage());
        }

        $retries++;
        sleep(pow(2, $retries)); // Exponential backoff
    }

    return false;
}
