['```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    double d;
    char* s;
} data;

data* array = NULL;
int error_flag = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *logfile = NULL;

void log_error(char *msg) {
    pthread_mutex_lock(&lock);
    if (logfile == NULL) {
        logfile = fopen("error.log", "w");
    }
    if (logfile != NULL) {
        fprintf(logfile, "%s\n", msg);
    }
    pthread_mutex_unlock(&lock);
}

void free_memory() {
    int i;
    for (i = 0; array[i].d != 101.0 && array[i].s != NULL; ++i) {
        free(array[i].s);
    }
    free(array);
}

void* create_data() {
    int i, j;
    double d;
    char *s = malloc(20);

    srand((unsigned int)time(NULL));

    array = (data*)malloc(100 * sizeof(data));
    if (!array) {
        log_error("Memory allocation failed for data array");
        error_flag = 1;
        return NULL;
    }

    for (i = 0; i < 100; ++i) {
        do {
            d = ((double)rand() / (double)RAND_MAX) * 100.0;
            sprintf(s, "String %d", i);

            for (j = 0; j < i && array[j].d != 101.0; ++j) {
                if (array[j].d == d || strcmp(array[j].s, s) == 0) {
                    break;
                }
            }

            if (j < i) {
                log_error("Duplicate value detected");
                error_flag = 1;
                free_memory();
                return NULL;
            }
        } while (error_flag == 0);

        array[i].d = d;
        array[i].s = s;

        if ((i + 1) % 100 == 0 && pthread_mutex_trylock(&lock) != 0) {
            log_error("Resource check failed");
            error_flag = 1;
            free_memory();
            return NULL;
        }
