void LogMemoryUsage() {
    if (!loggingEnabled || logfile == NULL) return;

    fprintf(logfile, "Total allocated size: %zu bytes\n", total_allocated);
}

// Function to manage allocation and deallocation of memory for project structures
int ManageProjects(size_t num_projects, int limit) {
    // Check if the number of projects is valid
    if (num_projects <= 0 || limit < 0) {
        return -1;  // Invalid parameters
    }

    pthread_mutex_lock(&lock);

    if ((size_t)(total_allocated + num_projects * sizeof(Project)) > limit) {
        pthread_mutex_unlock(&lock);

        return -2;  // Limit exceeded
    }

    Project* projects = (Project*)calloc(num_projects, sizeof(Project));

    if (!projects) {
        pthread_mutex_unlock(&lock);

        return -3;  // Allocation failure
    }

    total_allocated += num_projects * sizeof(Project);
    LogMemoryUsage();

    for (size_t i = 0; i < num_projects; ++i) {
