    // Deallocate the memory
    for (size_t i = 0; i < num_projects; ++i) {
        free(projects[i].name);
        free(projects[i].developer);
        free(projects[i].version_number);
    }

    total_allocated -= num_projects * sizeof(Project);
    LogMemoryUsage();

    pthread_mutex_unlock(&lock);

