typedef struct sensorData {
    int key;
    float value;
    char data[10];
} sensorData;

void generate_data(long *offsets, int *keys, float *values, sensorData **records, size_t numRecords) {
    srand((unsigned int)time(NULL));

    for (size_t i = 0; i < numRecords; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % 1000 + 1; // Random values within the range [1, 1000].
        values[i] = (float)(rand() % 1000) / 10.0f + 1.0f; // Random float values within the range [1.0, 100.0].

        sensorData *record = malloc(sizeof(sensorData));
        assert(record != NULL);
        record->key = keys[i];
        record->value = values[i];
        sprintf(record->data, "%d", rand() % 1000 + 1); // Random string.

        records[i] = record;
    }
}

void stable_sort(sensorData **records, size_t numRecords) {
    int i, j;
    for (i = 0; i < numRecords - 1; ++i) {
        for (j = 0; j < numRecords - i - 1; ++j) {
            if (records[j]->key > records[j + 1]->key) {
                sensorData *temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

void manage_memory(long *offsets, int *keys, float *values, sensorData **records, size_t numRecords) {
    free(offsets);
    free(keys);
    free(values);

    for (size_t i = 0; i < numRecords; ++i) {
        free(records[i]);
    }
    free(records);
}
