void parseCSV(char* line, long** offsets, int* count) {
    char* token = strtok(line, ",");
    while (token != NULL) {
        errno = 0;
        char *endptr;
        long val = strtol(token, &endptr, 10);

        if (errno == ERANGE || endptr == token || *endptr != '\0') {
            fprintf(stderr, "Invalid input format: %s\n", line);
            return;
        }

        (*offsets)[*count] = val;
        (*count)++;

        if ((*count)*sizeof(long) >= offset_count*sizeof(long)) {
            *offsets = realloc(*offsets, offset_count*2);
        }

        token = strtok(NULL, ",");
    }
}

