JavaScript part:
```javascript
function asyncReduction(arr, initValue, callback) {
    return new Promise((resolve, reject) => {
        let accumulatedValue = initValue;

        function reduce() {
            if (arr.length === 0) {
                resolve(accumulatedValue);
                return;
            }

            const currentNumber = arr.shift();
            callback(accumulatedValue, currentNumber, (err, result) => {
                if (err) {
                    reject(err);
                } else {
                    accumulatedValue = result;
                    reduce();
                }
            });
        }

        reduce();
    });
}
```
