// Function to handle memory allocation and initialization of arrays
void manage_memory(size_t size, int maxLimit) {
    long *offsets = init_array(2, sizeof(long));
    offsets[0] = 0;
    offsets[1] = size;

    if (maxLimit < size * sizeof(int)) {
        exit(EXIT_FAILURE);  // Handle memory allocation failure.
    }

    int* keys = init_array(size, sizeof(int));
    record* records = init_array(size, sizeof(record));

