    float *values;
    Record **records;
};

#define MAX_ARRAY_SIZE (1 << 30) // 1GB limit for now, can be modified based on system resources.

struct MemoryManager* initializeMemory(size_t num_records, size_t record_count){
    struct MemoryManager *mgr = malloc(sizeof(struct MemoryManager));

    if(!mgr || num_records > MAX_ARRAY_SIZE || record_count > MAX_ARRAY_SIZE) {
        free(mgr);
        return NULL; // Out of memory or invalid configuration parameters.
    }

    pthread_mutex_init(&mgr->mutex, NULL);

    mgr->offsets = calloc(num_records, sizeof(long));
    mgr->keys = calloc(num_records, sizeof(int));
    mgr->values = calloc(num_records, sizeof(float));

    if(!mgr->offsets || !mgr->keys || !mgr->values) {
        free(mgr->offsets);
        free(mgr->keys);
        free(mgr->values);
        pthread_mutex_destroy(&mgr->mutex);
        free(mgr);
        return NULL; // Out of memory.
    }

    mgr->records = calloc(record_count, sizeof(Record*));
