            free(mgr->records);
            free(mgr->offsets);
            free(mgr->keys);
            free(mgr->values);
            pthread_mutex_destroy(&mgr->mutex);
            free(mgr);
            return NULL; // Out of memory.
        }
    }

    return mgr;
}

void destroyMemoryManager(struct MemoryManager *mgr, size_t record_count){
    if(!mgr) {
        return;
    }

    pthread_mutex_lock(&mgr->mutex); // Acquire lock before modifying memory.
    free(mgr->offsets);
    free(mgr->keys);
    free(mgr->values);

    for(size_t i = 0; i < record_count; i++){
        free(mgr->records[i]);
    }

    free(mgr->records);
    pthread_mutex_unlock(&mgr->mutex); // Release lock after memory modification.
    pthread_mutex_destroy(&mgr->mutex);
    free(mgr);
}
```
']

