typedef struct {
    int value;
} record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void manage_records(int num_records, int min, int max) {
    long *offsets = malloc(num_records * sizeof(*offsets));
    if (!offsets) return; // handle memory allocation failure

    int *keys = malloc(num_records * sizeof(*keys));
    if (!keys) {
        free(offsets);
        return;
    }

    record *records = malloc(num_records * sizeof(*records));
    if (!records) {
        free(offsets);
        free(keys);
        return;
    }

    pthread_mutex_lock(&mutex);

    unsigned int seed = (unsigned int) time(NULL); // for rand_r

    // Initialize offsets and keys
