#include <time.h>

typedef struct {
    int value;
} Record;

int validateRanges(int** min_values, int** max_values, int num_ranges) {
    for (int i = 0; i < num_ranges - 1; i++) {
        if (*min_values[i] >= *max_values[i]) {
            return 0; // Invalid range: min is greater than max
        }
        for (int j = i + 1; j < num_ranges; j++) {
            if ((*min_values[j] <= *max_values[i] && *min_values[j] >= *min_values[i]) || (*max_values[j] >= *min_values[i] && *max_values[j] <= *max_values[i])) {
                return 0; // Overlapping ranges
            }
        }
    }
    return 1;
}

Record* initialize_records(long* offsets, int* keys, Record* records, int num_records, int** min_values, int** max_values, int num_ranges) {

    if (!validateRanges(min_values, max_values, num_ranges)) {
        printf("Invalid or overlapping ranges\n");
        return NULL;
    }

    // Dynamic allocation of records
    Record* temp = (Record*) malloc(num_records * sizeof(Record));

    if (temp == NULL) {
        printf("Memory Allocation Failed!\n");
        return NULL; 
    } else {
        for (int i = 0; i < num_records; i++) {
            // Initializing each record with a random value within the range
            srand(time(NULL));
            temp[i].value = (*min_values + rand() % (*max_values - *min_values + 1))*offsets[i]+keys[i];
        }
    }

    return temp; 
}
```
This code first validates the ranges using validateRanges function. If they are invalid or overlap, it returns NULL and ends execution without allocating memory. It then dynamically allocates memory for the records. If allocation fails, it again returns NULL. Otherwise, it initializes each record with a random value within its range.
