```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

Record** initialize(long offsetSize, int keySize, int recordSize, int minVal, int maxVal) {
    if (offsetSize <= 0 || keySize <= 0 || recordSize <= 0 || minVal > maxVal) return NULL;

    srand(time(NULL));  // For randomness in values of records

    long* offsets = malloc(sizeof(*offsets) * offsetSize);
    if (offsets == NULL) return NULL;

    int* keys = malloc(sizeof(*keys) * keySize);
    if (keys == NULL) { 
        free(offsets); 
        return NULL; 
    }

    Record** records = malloc(sizeof(*records) * recordSize);
    if (records == NULL) { 
        free(offsets); 
        free(keys); 
        return NULL; 
    }

    for (int i = 0; i < recordSize; ++i) {
        records[i] = malloc(sizeof(**records));
        if (records[i] == NULL) {  
            // In case of allocation error, free all previously allocated memory and return NULL
            for (int j = 0; j < i; ++j) 
                free(records[j]);
            free(offsets);
            free(keys);
            return NULL;
        }

        // Set a random value within the given range for each record's int field
