#include <stdlib.h>
#include <time.h>
#include <pthread.h> // for mutex operations

typedef struct record {
    int value;
} record;

// Assume your PHY layer structure is something like this:
typedef struct lte_phy {
    long ueid;
    int cce[5]; // Just assuming a random number of CCEs
    bool crc_ind;
    bool crc_flag;
} lte_phy;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void populate(long **offsets, int **keys, record ***records, lte_phy ***phies, int num) {
    srand((unsigned int) time(NULL)); // Seed the random number generator.

    *offsets = malloc(num * sizeof(long));
    *keys = malloc(num * sizeof(int));
    *records = malloc(num * sizeof(record*));
    *phies = malloc(num * sizeof(lte_phy*));

    if(*offsets == NULL || *keys == NULL || *records == NULL || *phies == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_lock(&mutex); // Lock to ensure thread safety.

    for (int i = 0; i < num; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand();

        (*records)[i] = malloc(sizeof(record)); // Allocate memory for each record.
        if((*records)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        (*records)[i]->value = rand();

        (*phies)[i] = malloc(sizeof(lte_phy)); // Allocate memory for each PHY structure.
        if((*phies)[i] == NULL) {
            fprintf(stderr, "Memory allocation failed.\n");
            exit(EXIT_FAILURE);
        }

        (*phies)[i]->ueid = rand();
        // Populate the CCEs and other fields of PHY structure.
        for (int j = 0; j < 5; ++j) {
            (*phies)[i]->cce[j] = rand();
        }
        (*phies)[i]->crc_ind = rand() % 2; // Randomly set CRC Indication.
        (*phies)[i]->crc_flag = rand() % 2; // Randomly set CRC flag.
    }

    pthread_mutex_unlock(&mutex); // Unlock the mutex after we're done.
}
```
