import java.io.*;

public class ShellCommandExecutor {

    public void executeShellCommand(String[] cmdArray, String[] envp, File dir) throws Exception {
        Process process = Runtime.getRuntime().exec(cmdArray, envp, dir);

        BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        System.out.println("Here is the standard output of the command:\n");
        String s;
        while ((s = stdInput.readLine()) != null) {
            System.out.println(s);
        }

        System.out.println("Here is the standard error of the command (if any):\n");
        while ((s = stdError.readLine()) != null) {
            System.out.println(s);
        }

        String fileName = cmdArray[cmdArray.length - 1]; // Consider last element as file name
        File fileToDelete = new File(dir, fileName);
        if (fileToDelete.exists()) {
            boolean deleted = fileToDelete.delete();
            if (!deleted) {
