    }

    data_record *records = malloc(max_records * sizeof(data_record)); // Allocating memory for records array
    if (records == NULL){
        printf("Error: Memory allocation failed for records\n"); 
        free(offsets); 
        free(keys); 
        free(values);
        return;
    }

    for (int i = 0; i < max_records; ++i) {
        records[i].key = keys[i]; // Initialize key in each record
        records[i].value = values[i]; // Initialize value in each record
        records[i].offset = &offsets[i]; // Initialize offset pointer for each record
    }

    printf("Data initialized successfully\n");

    free(records); 
