void deleteCCCI(CCCI* ccci) {
    free(ccci->CCEs);
    free(ccci);
}

int addToList(CCCI *ccci) {
    pthread_mutex_lock(&mutex);

    if (currSize >= MAX_SIZE){ 
        printf("Error: List capacity has been reached.\n"); 
        return -1; // List full.
    }

    // Check for duplicate UEIDs...
    gpointer existing = g_hash_table_lookup(hashTable, &ccci->UEID);
    if (existing != NULL){
        printf("Error: Duplicate UEID.\n");
        return -2; // Duplicate UEID.
    }

    g_hash_table_insert(hashTable, &ccci->UEID, ccci); 
    ++currSize;

    pthread_mutex_unlock(&mutex);
    return 0; // Successfully added.
}

