    data->records = malloc(array_size * sizeof(Record)); // allocate memory for records array
    if (data->records == NULL) {
        free(data->offsets); // free allocated memory in case of failure
        free(data->keys); // free allocated memory in case of failure
        printf("Memory allocation failed for records\n");
