    pthread_mutex_init(&ctxList.mutex, NULL);
}

// Add a UE Context to the list (with thread safety)
void addUEContext(UEContext context) {
    pthread_mutex_lock(&ctxList.mutex);  // Lock mutex for exclusive access

    if (ctxList.count == ctxList.capacity) {
        size_t newCapacity = ctxList.capacity * 2;
