#include <iostream> 

struct ConfigObject {
    std::vector<std::string> fieldNames;
};

void sendMessage(const char* data, size_t len) {
    // Assuming this function sends a message to the parent window
}

void updateDialogField(const std::string& result) {
    // Implement this as per your requirement
}

std::vector<unsigned char> computeMD5Hash(const std::string& input) {
    unsigned char md[16];
    MD5((unsigned char*)input.c_str(), input.length(), md);
    return std::vector<unsigned char>(md, md+16); // Convert to vector of bytes for convenience 
}

void refreshFields(std::forward_list<std::string>& list, const int resourceID, ConfigObject config) {
    bool found = false;
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == std::to_string(resourceID)) { // Assume the string representation of the ID matches 
            *++it = "refreshed"; // insert "refreshed" after the matched ID
            found = true;
            break;
        }
        ++it;
    }
    if (!found) list.insert_after(list.before_begin(), "refreshed"); // If not found, insert at beginning 

    for (const auto& fieldName : config.fieldNames) {
        std::vector<unsigned char> md5Hash = computeMD5Hash(fieldName);

        // Convert MD5 hash to string representation
        std::stringstream ss;
        ss << std::hex << std::setfill('0');
        for (const auto& byte : md5Hash) ss << std::setw(2) << static_cast<unsigned>(byte);

        sendMessage(ss.str().c_str(), ss.str().length()); // Send message with MD5 hash
        updateDialogField(ss.str()); // Update dialog field with the result 
    }
}
```
This code assumes that you have a valid C++ compiler and OpenSSL installed, which is usually the case for most environments. However, it does not handle any potential errors during file loading or parsing. Also, no race conditions are taken into consideration due to the lack of complete information on the task details. In real-world applications, proper error handling mechanisms should be implemented wherever necessary and synchronization strategies may be used depending upon whether the accesses are concurrent or not.
