typedef struct {
    NnfInstance_T *nnfs;
    int size;
    int capacity;
} NnfInstanceList_T;

NnfInstanceList_T* createList(int initialCapacity) {
    if (initialCapacity <= 0) return NULL;

    NnfInstanceList_T *list = malloc(sizeof(NnfInstanceList_T));
    list->nnfs = malloc(sizeof(NnfInstance_T) * initialCapacity);
    list->capacity = initialCapacity;
    list->size = 0;

    return list;
}

void resizeIfNeeded(NnfInstanceList_T *list) {
    if (list->size == list->capacity) {
        list->capacity *= 2;
        list->nnfs = realloc(list->nnfs, sizeof(NnfInstance_T) * list->capacity);
    }
}

void addNNFInstance(NnfInstanceList_T* list, int id, int serviceInfoTag, int configurationKey) {
    srand(time(NULL));  // Initialize random seed

    resizeIfNeeded(list);

    NnfInstance_T newNNF = { .id = id, .serviceInfoTag = rand() % 100, .configurationKey = rand() % 100 };  // Assign random values for serviceInfoTag and configurationKey

    list->nnfs[list->size] = newNNF;
    list->size++;
}
```

