#include <pthread.h>

typedef struct {
    int key;
    float value;
    char string[21];  // extra space for null termination
} dataRecord;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void generateData(long *offsets, int *keys, float *values, char **strings, dataRecord **records, size_t count) {
    if (count > 10000 || count < 1) {  // input validation
        printf("Invalid array count\n");
        return;
    }

    pthread_mutex_lock(&lock);

    srand(time(NULL));
    size_t totalSize = sizeof(long)*count + sizeof(int)*count + sizeof(float)*count + 21*count*sizeof(char) + sizeof(dataRecord)*count;

    if (totalSize > 5000000) { // maximum limit check
        printf("Memory allocation would exceed maximum limit\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    offsets = malloc(sizeof(long)*count);
    keys = calloc(count, sizeof(int));
    values = malloc(sizeof(float)*count);
    strings = malloc(21*count*sizeof(char));
    records = malloc(sizeof(dataRecord)*count);

    if (offsets == NULL || keys == NULL || values == NULL || strings == NULL || records == NULL) {  // error handling
        printf("Memory allocation failed\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    unsigned char randBuf[21];  // buffer for random string generation

    for (size_t i = 0; i < count; ++i) {
        keys[i] = rand() % 1000 + 1;   // int within given range
        values[i] = ((float)rand()/(float)(RAND_MAX)) * 5.0f;  // float within another range

        RAND_bytes(randBuf, 20);  // generate random string of length between 1 and 20
