    *keys = malloc(sizeof(int) * num_records);
    if (*keys == NULL) {
        free(*offsets);
        return -2; // Memory allocation error
    }

    *records = malloc(sizeof(Record*) * num_records);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -2; // Memory allocation error
