    INVALID_SENSOR_NUMBER,
    WEATHER_API_FETCHING_FAILURE
};

typedef struct {
    sensor_data *data;
    size_t dataCount;
    enum WeatherError error;
} WeatherData;

WeatherData fetchAndAllocateSensorData(size_t sensorNumber, float tempLimit) {
    WeatherData weatherData = {NULL, 0, NO_ERROR};

    // Check if sensorNumber is valid
    if (sensorNumber <= 0) {
        weatherData.error = INVALID_SENSOR_NUMBER;
        return weatherData;
    }

    // Allocate memory for sensor data
    weatherData.dataCount = sensorNumber;
    weatherData.data = malloc(sizeof(sensor_data) * sensorNumber);
    if (weatherData.data == NULL) {
        weatherData.error = MEMORY_ALLOCATION_FAILED;
        return weatherData;
    }

    // Initialize random number generator
    srand((unsigned int) time(NULL));

    for (size_t i = 0; i < sensorNumber; ++i) {
        float temp = ((float) rand() / (float) RAND_MAX) * tempLimit;  // Random temperature in range [0, tempLimit]

        // Assume that the weather API provides an ID for each sensor
        char id = 'A' + (char) i;  // Generate a unique ID for each sensor

        // Fetch data from the external weather API
        // If fetching fails, deallocate partially allocated memory and return error
        if (!fetchWeatherData(id, &temp)) {
