    int capacity;
    pthread_mutex_t lock;  // for thread safety
    NFAPI_CRC_INDICATION_PDU_T *list;
} List;

List* create_empty_list() {
    List *l = malloc(sizeof(*l));
    l->size = 0;
    l->capacity = 10;  // start with small capacity to avoid reallocation
    l->list = malloc(l->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&l->lock, NULL);
    return l;
}

void add_element(List *l, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&l->lock);  // acquire lock for thread safety

    if (l->size >= l->capacity) {
        l->capacity *= 2;  // double capacity each time we need to reallocate
        l->list = realloc(l->list, l->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    for (int i = 0; i < l->size; i++) {  // check for duplicates
        if (l->list[i].crc_indication_rel8_tag.rnti == element.crc_indication_rel8_tag.rnti) {
            return;  // discard duplicate
        }
    }

    l->list[l->size++] = element;  // add new element to list

    pthread_mutex_unlock(&l->lock);  // release lock
}
