    list->capacity = INITIAL_CAPACITY;
    list->count = 0;
    list->list = (CCCI **) allocate(list->capacity * sizeof(CCCI *));
    pthread_mutex_init(&list->mutex, NULL);
    memset(list->hashTable, -1, sizeof(int) * (MAX_UEID + 1));
    return list;
}

void addToList(CCCIList *list, uint32_t UEID, bool hasCRC, int numCCEs, CCE **CCEs) {
    assert(numCCEs > 0 && numCCEs <= MAX_CCE);
    pthread_mutex_lock(&list->mutex);

    if (UEID > MAX_UEID || list->hashTable[UEID] != -1) {
        /* Handle error: duplicated UEID or exceeding max number of UEs */
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    if (list->count == list->capacity) {
        /* Resize the list to accommodate more CCCI structures */
        size_t newCapacity = list->capacity * 2;
        list->list = (CCCI **) reallocate(list->list, newCapacity * sizeof(CCCI *));

        if (!list->list) {
            /* Handle memory allocation failure */
            pthread_mutex_unlock(&list->mutex);
            return;
        }

        list->capacity = newCapacity;
    }

    CCCI *ccci = (CCCI *) allocate(sizeof(CCCI));
    ccci->UEID = UEID;
    ccci->hasCRC = hasCRC;
    ccci->numCCEs = numCCEs;
    memcpy(ccci->CCEs, CCEs, numCCEs * sizeof(CCE *));

    list->list[list->count++] = ccci;
    list->hashTable[UEID] = list->count - 1;
    pthread_mutex_unlock(&list->mutex);
}

/* Implement other functions as per requirement */
