void initialize_records(long *offsets, int *keys, double *values, record ***records, int num_records, int seed) {
    srand(seed);

    // Allocate memory for arrays and check if allocation was successful.
    offsets = malloc(num_records * sizeof(long));
    keys = malloc(num_records * sizeof(int));
    values = malloc(num_records * sizeof(double));
