    pthread_mutex_lock(&mutex); // lock thread to ensure safe access of shared resources

    if(errorFlag) {
        logError("An error occurred. Exiting function.");
        return;
    }

    int arraySize = getConfigValue("arraySize", 1000);
    if (arraySize <= 0 || arraySize > INT_MAX / sizeof(DataStructure)) {
        logError("Invalid configuration for array size");
        errorFlag = 1;
        pthread_mutex_unlock(&mutex); // unlock the thread on exit
        return;
    }

    double* values = (double*) malloc(arraySize * sizeof(double));
    char** strings = (char**) malloc(arraySize * sizeof(char*));
    DataStructure* dataArray = (DataStructure*) calloc(arraySize, sizeof(DataStructure));

    if(!values || !strings || !dataArray) {
        logError("Memory allocation failed");
        errorFlag = 1;
        pthread_mutex_unlock(&mutex); // unlock the thread on exit
        return;
    }

    srand(time(NULL));
    int range = getConfigValue("randomRange", 100);
    for (int i=0; i<arraySize; i++) {
        values[i] = ((double) rand() / RAND_MAX) * range;

        strings[i] = malloc(sizeof(char)*256); // assume max string size is 256 bytes
        if(!strings[i]) {
