#include <stdio.h>
#include <stdlib.h>

typedef struct {
    double value;
    char *string;
} data_entry;

int read_data(const char *filename, data_entry **entries, size_t limit) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) return -1; // Failed to open the file.

    size_t count = 0;
    char line[256];
    while (fgets(line, sizeof line, file) != NULL && count < limit) {
        data_entry *entry = malloc(sizeof(data_entry));
        if (entry == NULL) break; // Failed to allocate memory.

        int result = sscanf(line, "%lf %100s", &entry->value, entry->string);
        if (result != 2) { // Failed to parse a line.
            free(entry);
            continue;
        }

        entries[count++] = entry;
    }

    fclose(file);

    int error = 0;
    if (count == limit && !feof(file)) {
        // Exceeded the limit without reaching EOF.
        error = -2;
    }

    if (!error) {
        for (size_t i = 0; i < count; ++i) {
            free(entries[i]->string);
            free(entries[i]);
        }
        free(entries);
    }

    return error ? error : count;
}
```
Please remember to adjust the maximum line size (256 in this case) and string length according to your specific requirements. Note that this code does not handle thread safety, it's just an example of how you might implement such a function. To ensure thread safety, consider using mutexes or other synchronization primitives as necessary.
