async fn handle_connection(mut stream: TcpStream) {
    let mut buffer = [0; 1024];
    loop {
        match stream.read(&mut buffer).await {
            Ok(n) if n == 0 => break, // EOF
            Ok(_n) | Err(ref e) if e.kind() != io::ErrorKind::WouldBlock => { return Err(e); } 
