#include <stdlib.h>
#include <pthread.h> // used for thread-safe data structures and synchronization mechanisms

// Assume the following structure definitions:
typedef struct {
    int RNTI;
} RX_UE_INFORMATION_TAG;

typedef struct {
    int CRCFLAG;
} CRC_INDICATION_REL8_TAG;

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxueinfo;
    CRC_INDICATION_REL8_TAG crcind;
} NFAPI_CRC_INDICATION_PDU_T;

// Define hash table data structure:
typedef struct HashNode {
    int RNTI;
    void* value; // pointer to the actual data stored in the hash table
    struct HashNode *next;
} HashNode;

HashNode **hashTable = NULL; // global hash table
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // global mutex for thread-safe data structures and synchronization mechanisms
int TABLE_SIZE = 1024; // size of the hash table

// Hash function: simple modulo hash function
int hash(int RNTI) {
    return abs(RNTI % TABLE_SIZE);
}

NFAPI_CRC_INDICATION_PDU_T* initAndAllocateList(int N, int randomSeed) {
    // Memory allocation failure check
    NFAPI_CRC_INDICATION_PDU_T *list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        return NULL;
    }

    srand(randomSeed); // set the seed for random number generation
    for (int i = 0; i < N; i++) {
        list[i].rxueinfo.RNTI = rand();
        list[i].crcind.CRCFLAG = rand() % 2;

        // insert into hash table using a separate chaining strategy to handle collisions
        pthread_mutex_lock(&lock); // acquire lock for thread safety
        int index = hash(list[i].rxueinfo.RNTI);
        HashNode *newNode = malloc(sizeof(HashNode)); 
        newNode->RNTI = list[i].rxueinfo.RNTI;
        newNode->value = &list[i];
        newNode->next = hashTable[index]; // add at the beginning for O(1) insertion
        hashTable[index] = newNode; 
        pthread_mutex_unlock(&lock); // release lock after operation
    }

    return list;
}

void freeMemory(NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        HashNode* current = hashTable[i];
        while (current != NULL) {
            HashNode* temp = current;
            current = current->next;
            free(temp); // free each node in the linked list
        }
    }

    free(list); // free the memory allocated for the entire list
}
``` 

