Config config = { .max_memory_usage = 1024 * 1024 }; // 1 MB
char* sensor_names[] = {"Sensor1", "Sensor2", "Sensor3"};
int num_sensors = sizeof(sensor_names) / sizeof(char*);

void free_resources(SensorData* sensors, int size) {
    for (int i = 0; i < size; ++i) {
        if (sensors[i].sensor_name != NULL) {
            free(sensors[i].sensor_name);
            sensors[i].sensor_name = NULL;
        }
    }

    free(sensors);
}

int create_sensor_data(SensorData** data, int num_sensors) {
    if (num_sensors <= 0 || num_sensors > config.max_memory_usage / sizeof(SensorData)) {
        return -1; // Invalid argument or memory limit exceeded
    }

    *data = calloc(num_sensors, sizeof(SensorData));

    if (*data == NULL) {
        return -2; // Out of memory error
    }

    for (int i = 0; i < num_sensors; ++i) {
        int name_length = strlen(sensor_names[i % sizeof(sensor_names)]);

        (*data)[i].timestamp = time(NULL) * 1000 + rand() % 1000; // Random timestamp for simplicity
        (*data)[i].temperature = (float)(rand() % 50); // Random temperature
