```c
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

typedef struct {
    int key;
    double value;
} RecordType;

typedef enum {
    INT_TYPE, 
    LONG_TYPE, 
    DOUBLE_TYPE, 
    RECORD_TYPE
} DataType;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
long total_allocated = 0;
int loggingEnabled = 1; // Change this to enable/disable logging.

void* allocateMemory(DataType type, size_t num_elements) {
    void *ptr = NULL;

    pthread_mutex_lock(&lock);
    if (type == INT_TYPE) {
        int *intArray = malloc(sizeof(int) * num_elements);
        assert(intArray != NULL); // Ensure memory was allocated successfully.

        total_allocated += sizeof(int) * num_elements;
        if (loggingEnabled) {
            printf("Allocated %ld bytes for int array, Total allocated: %ld\n", 
                   sizeof(int) * num_elements, total_allocated);
        }

        ptr = intArray; // Assign to common pointer.
    } else if (type == LONG_TYPE) {
        long *longArray = malloc(sizeof(long) * num_elements);
        assert(longArray != NULL); 

        total_allocated += sizeof(long) * num_elements;
        if (loggingEnabled) {
            printf("Allocated %ld bytes for long array, Total allocated: %ld\n", 
                   sizeof(long) * num_elements, total_allocated);
        }

        ptr = longArray;
    } else if (type == DOUBLE_TYPE) {
        double *doubleArray = malloc(sizeof(double) * num_elements);
        assert(doubleArray != NULL); 

        total_allocated += sizeof(double) * num_elements;
        if (loggingEnabled) {
            printf("Allocated %ld bytes for double array, Total allocated: %ld\n", 
                   sizeof(double) * num_elements, total_allocated);
        }

        ptr = doubleArray;
    } else if (type == RECORD_TYPE) {
        RecordType *recordArray = malloc(sizeof(RecordType) * num_elements);
        assert(recordArray != NULL); 

        total_allocated += sizeof(RecordType) * num_elements;
        if (loggingEnabled) {
            printf("Allocated %ld bytes for record array, Total allocated: %ld\n", 
                   sizeof(RecordType) * num_elements, total_allocated);
        }

        ptr = recordArray;
    } else {
        fprintf(stderr, "Error: Invalid data type\n");
    }

    if (ptr == NULL) {
        // Return partial allocated memory.
        freeAllocatedMemory();
    }

    pthread_mutex_unlock(&lock);
    return ptr;
}

void freeAllocatedMemory() {
    pthread_mutex_lock(&lock);
    total_allocated = 0; // Reset allocation counter.
    pthread_mutex_unlock(&lock);
}
```

In the above code, `pthread_mutex_t` is used to ensure thread-safe memory allocation and deallocation in a multi-threaded environment. The `total_allocated` variable keeps track of total allocated memory size and `loggingEnabled` controls logging. Please note that this implementation does not support dynamic structure definitions, as it would significantly increase the complexity of code.
