['Here is a C code implementing your requirements. The code assumes that each line of the CSV file follows the pattern "key, value" (where key and value are integers). 

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int key;
    float value;
    char* str;
} dataRecord;

void read_and_initialize(char *filename, int **keys, float **values, dataRecord **records) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening the file.\n");
        exit(EXIT_FAILURE);
    }

    int count = 0;
    while (!feof(file))
        if (fgetc(file) == '\n')
            count++;

    rewind(file);

    *keys = malloc(count * sizeof(int));
    *values = malloc(count * sizeof(float));
    *records = malloc(count * sizeof(dataRecord));

    srand((unsigned int) time(NULL));

    for (int i = 0; i < count; i++) {
        if (fscanf(file, "%d,%f", &(*keys)[i], &(*values)[i]) != 2) {
            printf("Invalid data format in the file.\n");
            exit(EXIT_FAILURE);
        }

        (*records)[i].key = (*keys)[i];
        (*records)[i].value = ((float)rand()/(float)(RAND_MAX)) * 10; // random float between 0 and 10

        char buffer[20];
        sprintf(buffer, "%d", (*keys)[i]);
        (*records)[i].str = malloc((strlen(buffer) + 1) * sizeof(char));
        strcpy((*records)[i].str, buffer);
    }

    fclose(file);
}
```
The `read_and_initialize` function takes a file name and three pointers as arguments. The function first counts the number of records in the CSV file. Then it allocates memory for the arrays based on this count, and reads each record from the file to initialize the arrays. It also initializes the string pointer with a dynamically allocated string containing the key as its content. 

