["Here is a basic implementation of such function using POSIX threads (pthreads) for thread safety and C99 standard dynamic memory allocation functions for managing the list of VNF instances and SCPs. This code does not include integration with an external data source or interaction with an external library to validate SCPs, as this would greatly increase the complexity of the implementation without providing a clear-cut specification on how to integrate such functionality:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    float processing_power;
    size_t memory_size;
    float network_bandwidth;
} SCPs, *PSCPs;

typedef struct VNFInstance{
    int vnf_id;
    PSCPs scps;
    struct VNFInstance* next;
} VNFInstance, *PVNFInstance;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
PVNFInstance vnfListHead = NULL;
int numOfInstances = 0;

void add_vnf(int id, PSCPs scps) {
    if (id < 1 || !scps || scps->processing_power <= 0 || 
        scps->memory_size <= 0 || scps->network_bandwidth <= 0) return;

    pthread_mutex_lock(&lock);

    PVNFInstance newNode = (PVNFInstance) malloc(sizeof(VNFInstance));
    if (!newNode) { 
        pthread_mutex_unlock(&lock); 
        return;
    }

    newNode->vnf_id = id;
    newNode->scps = scps;
    newNode->next = NULL;

    if (!vnfListHead) {
        vnfListHead = newNode;
    } else {
        PVNFInstance current = vnfListHead;

        while(current->next) 
            current = current->next;

        current->next = newNode;
    }

    numOfInstances++;

    pthread_mutex_unlock(&lock);
}
```
This implementation ensures thread safety by locking the list operations with a mutex, and efficiently handles memory allocation for each VNF instance. It does not include error handling or input validation beyond checking if the input values are within acceptable ranges. 

