void logMemoryUsage(Collection* collection) {
    FILE* file = fopen("memory.log", "a");
    if (file == NULL) {
        printf("Error opening memory.log for logging\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "[%s] Memory usage: %lu of %lu\n", timestamp, collection->count, collection->capacity);

    fclose(file);
}

Collection* createCollection() {
    Collection* collection = (Collection*)malloc(sizeof(Collection));
    if (collection == NULL) {
        printf("Error allocating memory for the Collection\n");
        return NULL;
    }

    collection->capacity = 100000;
    collection->count = 0;

    collection->offsets = (long*)malloc(collection->capacity * sizeof(long));
    if (collection->offsets == NULL) {
        printf("Error allocating memory for offsets\n");
        free(collection);
        return NULL;
    }

    collection->keys = (int*)malloc(collection->capacity * sizeof(int));
    if (collection->keys == NULL) {
        printf("Error allocating memory for keys\n");
        free(collection->offsets);
        free(collection);
        return NULL;
    }

    collection->records = (Record**)malloc(collection->capacity * sizeof(Record*));
    if (collection->records == NULL) {
        printf("Error allocating memory for records\n");
        free(collection->offsets);
        free(collection->keys);
        free(collection);
        return NULL;
    }

    pthread_mutex_init(&collection->lock, NULL);

    return collection;
}

void addRecord(Collection* collection, int key) {
    if (collection == NULL || key < 0 || key > 1000000) {
        printf("Invalid parameters\n");
        return;
    }

    pthread_mutex_lock(&collection->lock);

    if (collection->count >= collection->capacity) {
        printf("Collection is full\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    long offset = rand() % 1000000 + 1;
    Record* record = (Record*)malloc(sizeof(Record));
    if (record == NULL) {
        printf("Error allocating memory for a new record\n");
        pthread_mutex_unlock(&collection->lock);
        return;
    }

    record->value = offset;
    collection->offsets[collection->count] = offset;
    collection->keys[collection->count] = key;
    collection->records[collection->count++] = record;

    pthread_mutex_unlock(&collection->lock);

    if (((double)collection->count / collection->capacity * 100.0) - ((int)((double)collection->count / collection->capacity * 100)) >= 0.99 ) {
        logMemoryUsage(collection);
    }
}
```
