    RX_UE_INFORMATION_TAG rx_ue_info;
    int RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} FAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    FAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

Node* head = NULL; 
pthread_mutex_t mutexhead = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new node at the end of list.
void insert(FAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&mutexhead);
    Node* temp = (Node*) malloc(sizeof(Node)); 
    temp->data = data;
    temp->next = NULL; 

    if(head == NULL) { // If the list is empty.
        temp->prev = NULL; 
        head = temp; 
        return;
    } 

    Node* temp1 = head;
    while(temp1->next != NULL) { // Traverse to end of the list.
        temp1 = temp1->next;
    }

    temp1->next = temp; 
    temp->prev = temp1;
    pthread_mutex_unlock(&mutexhead);
}

// Load RNTIs from file.
void loadRNTIFromFile(const char *filename) {
    FILE *file = fopen ( filename, "r" );
    if ( file != NULL ) {
        FAPI_CRC_INDICATION_PDU_T pdu;
        while(!feof(file)) { // Load RNTI values from the file.
            fscanf(file, "%d", &pdu.RNTI);

            // Other PDU fields initialization...

            insert(pdu);  // Insert it in doubly linked list.
        }

        fclose ( file );
    } else {
        perror ( filename ); /* why didn't the file open? */
    }
}
