```python
import threading
import random
from time import sleep

class NetworkService(threading.Thread):
    def __init__(self, serviceName, stopMessageQueue):
        super().__init__()
        self._stop_event = threading.Event()
        self._serviceName = serviceName
        self._stopMessageQueue = stopMessageQueue

    def run(self):
        while not self._stop_event.isSet(): # Check if Thread should be terminated
            sleepDelay = random.randint(1, 10) # Random delay between starts and stops
            print("Starting service %s" % self._serviceName)
            sleep(sleepDelay)
            self._stopMessageQueue.put("%s stopped after %d seconds." % (self._serviceName, sleepDelay))
            print("Stopping service %s" % self._serviceName)

    def stop(self):
        self._stop_event.set() # Set the Thread Event to trigger termination of while loop in run method
```
