} CCIStruct;

// Global variable for list of CCIStructs
CCIStruct **list = NULL;
int listSize = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void addToList(char *UEID, CCE *CCEs) {
    pthread_mutex_lock(&lock);

    // Check if UEID already exists in list
    for (int i = 0; i < listSize; i++) {
        if (strcmp(list[i]->UEID, UEID) == 0) {
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Create new CCIStruct and add to list
    CCIStruct *newCCI = malloc(sizeof(CCIStruct));
    newCCI->UEID = strdup(UEID);  // Deep copy UEID
    newCCI->CCEs = CCEs;  // Assuming that CCEs are already allocated and validated
    newCCI->num_CCEs = 0;  // Initialize num_CCEs to zero
    newCCI->CRCIndication = rand() % 2 == 0 ? true : false;  // Randomly set CRC flag

    listSize++;
    list = realloc(list, listSize * sizeof(CCIStruct*));
    list[listSize - 1] = newCCI;

    pthread_mutex_unlock(&lock);
