['The task provided is quite complex to be solved within this format but here's a basic outline of how you might approach it. This code does not include all the constraints mentioned above due to their complexity and length. The real-world solution would require substantial amount of work, testing, and optimization. Also note that DNS querying in C is non-trivial due to its complex nature and the fact that error handling in C is significantly different from languages like Python or Java:

```c
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

typedef struct Node {
    char *hostname;
    struct in_addr ip_address;
    int timestamp; // For LRU policy
    struct Node* next;
} Node;

Node* cache = NULL; // Head of linked list to implement LRU cache.
pthread_mutex_t lock; // To make the cache thread-safe.
int size = 0; // Current size of cache.
const int MAX_CACHE_SIZE = 100; // Maximum size of cache before eviction.
const int DNS_SERVERS[] = {"8.8.8.8", "8.8.4.4"}; // Example of multiple DNS servers.
int currentDnsServerIndex = 0; // Index for round-robin between DNS servers.

// Function to add a new node at the head of cache linked list.
void push(char *hostname, struct in_addr ip_address) {
    pthread_mutex_lock(&lock); // Locking mutex to make this operation atomic and thread-safe.

    Node* temp = (Node*)malloc(sizeof(Node));
    strcpy(temp->hostname, hostname);
    temp->ip_address = ip_address;
    temp->timestamp = 0;
    temp->next = cache; // New node will be at head of list.

    Node* iterator = cache;
    while(iterator != NULL) {
        iterator->timestamp++;
        iterator = iterator->next;
    }

    size++;
    if (size > MAX_CACHE_SIZE) evict(); // Evict oldest entry if cache is full.

    pthread_mutex_unlock(&lock); // Unlocking mutex.
}

// Function to remove the oldest node from the linked list, i.e., the one with timestamp == MAX_CACHE_SIZE.
void evict() {
    if (cache != NULL) {
        pthread_mutex_lock(&lock); // Locking mutex for thread-safety.

        Node* iterator = cache;
        while(iterator->next != NULL && iterator->next->timestamp < MAX_CACHE_SIZE) {
            iterator = iterator->next;
        }

        // Remove node from list if it exists and decrement size.
        if (iterator->next != NULL) {
            Node* temp = iterator->next;
            iterator->next = temp->next;
            free(temp);
            size--;
        }

        pthread_mutex_unlock(&lock); // Unlocking mutex.
    }
}

// Function to lookup a hostname in the cache. If found, updates timestamp and moves it to head of list.
struct in_addr* dnsLookupCache(char *hostname) {
    pthread_mutex_lock(&lock); // Locking mutex for thread-safety.

    Node* iterator = cache;
    while (iterator != NULL && strcmp(iterator->hostname, hostname) != 0) {
        iterator = iterator->next;
    }

    if (iterator != NULL) { // If found in cache.
        struct in_addr* ip_address = &iterator->ip_address;

        iterator->timestamp = 0; // Updating timestamp to make it the most recently used node.
        push(hostname, *ip_address); // Moving this node to head of list as it is being accessed again.

        pthread_mutex_unlock(&lock); // Unlocking mutex.
        return ip_address; 
    } else {
        pthread_mutex_unlock(&lock); // Unlocking mutex.
        return NULL; // Not found in cache.
    }
}

struct in_addr* dnsLookup(char *hostname) {
    struct in_addr* ipAddress = dnsLookupCache(hostname);

    if (ipAddress != NULL) return ipAddress; // If hostname found in cache.

    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    // Do DNS lookup using round-robin strategy among DNS servers.
    if (getaddrinfo(hostname, NULL, &hints, &res) == 0) {
        ipAddress = &((struct sockaddr_in*) res->ai_addr)->sin_addr;

        // Adding found hostname and IP address to the cache.
        push(hostname, *ipAddress); 

        freeaddrinfo(res); // Freeing linked list allocated by getaddrinfo().
    } else {
        printf("Error occurred during DNS lookup.\n");
        return NULL; // Return error if unable to resolve the hostname.
    }

    currentDnsServerIndex = (currentDnsServerIndex + 1) % 2; // Round-robin between DNS servers.

    return ipAddress; // Return resolved IP address.
}
```
']

