int add_profile(UserProfile **profiles, size_t *capacity, size_t *count, UserProfile new_profile) {
    pthread_mutex_lock(&lock); // Lock the mutex to avoid race conditions

    if (*count >= *capacity) { // If the list is full, resize it
        size_t new_capacity = *capacity * 2;

        UserProfile* temp = (UserProfile*)realloc(profiles, sizeof(UserProfile) * new_capacity);
        if (!temp) {
            pthread_mutex_unlock(&lock); // Unlock the mutex and return an error code
            return -1;
        }

        profiles = temp;
        *capacity = new_capacity;
    }

    profiles[(*count)++] = new_profile;

    pthread_mutex_unlock(&lock); // Unlock the mutex after modifying shared data
    return 0;
}

int remove_profile(UserProfile **profiles, size_t *capacity, size_t *count, const char* username) {
    pthread_mutex_lock(&lock); // Lock the mutex to avoid race conditions

    for (size_t i = 0; i < *count; ++i) { // Find the profile with matching username
        if (strcmp(profiles[i].username, username) == 0) {
            free(profiles[i]); // Free memory used by this profile

            for (size_t j = i; j < *count - 1; ++j) { // Shift remaining profiles to fill the gap
                profiles[j] = profiles[j + 1];
            }

            --(*count);
            pthread_mutex_unlock(&lock); // Unlock the mutex after modifying shared data
            return 0;
        }
    }

    pthread_mutex_unlock(&lock); // Unlock the mutex if no matching profile was found
    return -1;
}
