} data_entry;

typedef struct {
    int index;
    data_entry *ptr;
} metadata;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Thread safety

// Allocate and Initialize Array Function
int alloc_init(data_entry **entries, 
               metadata **metadata, 
               int size, 
               double range_min, 
               double range_max, 
               char *configFile) {
    pthread_mutex_lock(&lock); // Acquire the lock to ensure thread safety.

    if (size < 1 || range_min > range_max) {
        syslog(LOG_ERR, "Invalid input parameters");
        return -1;  // Return error code for invalid input parameters
    }

    *entries = calloc(size, sizeof(data_entry));
    if (*entries == NULL) {
        syslog(LOG_ERR, "Memory allocation failed");
        pthread_mutex_unlock(&lock); // Unlock the mutex before returning.
        return -2;  // Return error code for memory allocation failure
    }

    srand((unsigned int)time(NULL));  // Seed the random number generator with current time.

    for (int i = 0; i < size; ++i) {
        (*entries)[i].value = ((double) rand() / RAND_MAX) * (range_max - range_min) + range_min;  // Assign a random value within the given range.

        // Allocate and initialize key based on your requirement.
    }

    *metadata = calloc(size, sizeof(metadata));  // Allocate memory for metadata array.
    if (*metadata == NULL) {
        syslog(LOG_ERR, "Memory allocation failed");
        free(*entries);  // Deallocate entries before returning in case of failure.
        pthread_mutex_unlock(&lock);  // Unlock the mutex before returning.
        return -2;  // Return error code for memory allocation failure
    }

    for (int i = 0; i < size; ++i) {
        (*metadata)[i].index = i;  // Set index.
        (*metadata)[i].ptr = &((*entries)[i]);  // Point to corresponding data_entry.
    }

    FILE *file = fopen(configFile, "r");  // Open the configuration file in read mode.
    if (file == NULL) {
        syslog(LOG_ERR, "Failed to open configuration file");
        free(*metadata);  // Deallocate metadata before returning in case of failure.
        free(*entries);   // Deallocate entries before returning in case of failure.
        pthread_mutex_unlock(&lock);  // Unlock the mutex before returning.
        return -3;  // Return error code for configuration file opening failure
    }

    /* Read from configFile and initialize your data structures */

    fclose(file);  // Close the file after reading is done.

    pthread_mutex_unlock(&lock); // Unlock the mutex before returning.
    return 0;  // Return success code
}

// Deallocate Memory Function
void dealloc_mem(data_entry *entries, metadata *metadata) {
    pthread_mutex_lock(&lock); // Acquire the lock to ensure thread safety.

    free(metadata);  // Free the metadata array.

    for (int i = 0; i < size; ++i) {  // Iterate through each data entry and deallocate its key.
        free((entries + i)->key);
    }
    free(entries);  // Deallocate the entries array.

    pthread_mutex_unlock(&lock); // Unlock the mutex before returning.
}
```
In this code, `data_entry` is a structure that contains a `double` value and a pointer to a `char` key. The `metadata` structure contains an integer index and a pointer to a `data_entry` structure. 

The function `alloc_init` allocates memory for arrays of `data_entry` structures, initializes them with random values within a given range, allocates memory for an array of `metadata` structures, initializes them with the corresponding index and pointers to `data_entry` structures. It also opens a configuration file in read mode. 

The function `dealloc_mem` deallocates all allocated memory.
