```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int value;
} record_t;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

record_t** allocate_and_init(long offset_size, long key_size, long record_size, int *seed) {
    if (offset_size <= 0 || key_size <= 0 || record_size <= 0) return NULL;

    pthread_mutex_lock(&mutex); // Ensure thread safety.

    // Allocate memory for arrays.
    long* offset = malloc(sizeof(long) * offset_size);
    int* key = calloc(key_size, sizeof(int));
    record_t** record = malloc(sizeof(record_t*) * record_size);
    if (offset == NULL || key == NULL || record == NULL) goto error;

    // Initialize random number generator.
    srand(*seed);

    // Populate offset array with unique values.
    for (long i = 0; i < offset_size; ++i) {
        while (1) {
            int value = rand();

            // Ensure the generated value is unique.
            long j;
            for (j = 0; j < i; ++j) {
                if (offset[j] == value) break;
            }

            // If we haven't found a match, store the value and continue to the next iteration.
            if (j == i) {
                offset[i] = value;
                break;
            }
        }
    }

    // Populate key array with unique values.
    for (long i = 0; i < key_size; ++i) {
        while (1) {
            int value = rand();

            long j;
            for (j = 0; j < i; ++j) {
                if (key[j] == value) break;
            }

            if (j == i) {
                key[i] = value;
                break;
            }
        }
    }

    // Populate record array.
    for (long i = 0; i < record_size; ++i) {
        record_t* rec = malloc(sizeof(record_t));

        if (rec == NULL) goto error;

        rec->value = rand();
        record[i] = rec;
    }

    pthread_mutex_unlock(&mutex); // Release lock.

    return record;

error:
    free(offset);
    free(key);
    for (long i = 0; i < record_size; ++i) {
        free(record[i]);
    }
    free(record);

    pthread_mutex_unlock(&mutex); // Release lock.

    return NULL;
}
```
