// Define the maximum number of UEs that can be stored in the list. 
// This value should be adjusted based on system resources and available memory.
#define MAX_UES 1000

typedef struct LTE_Ue_Context {
    int ue_id;
    int rrc_connection_info_tag;
    char security_key[32];
} LTE_Ue_Context_T;

typedef struct UeContextList {
    LTE_Ue_Context_T* list;
    int capacity;
    int size;
    pthread_mutex_t mutex;
    FILE *logFile;
} UeContextList_T;

// Generate a random number within the given range (inclusive)
int generateRandomNumber(int lower, int upper) {
    return (rand() % (upper - lower + 1)) + lower;
}

// Initialize the UE context with random values for UE ID, RRC Connection Information Tag, and Security Key. 
void initializeUeContext(LTE_Ue_Context_T *context) {
    context->ue_id = generateRandomNumber(100000, 999999); // Random number within the range of 100000 to 999999.
    context->rrc_connection_info_tag = generateRandomNumber(1, 65535); // Random number within the range of 1 to 65535 (as per LTE standard).

    for(int i = 0; i < 32; ++i) {
        context->security_key[i] = generateRandomNumber('a', 'z'); // Random lowercase letter.
    }
}

// Initialize the UE context list with a fixed capacity and initialize the mutex for thread safety. 
void initializeUeContextList(UeContextList_T *list, int capacity) {
    srand((unsigned int)time(NULL)); // Seed random number generator.

    list->capacity = capacity;
    list->size = 0;
    list->list = (LTE_Ue_Context_T*) malloc(capacity * sizeof(LTE_Ue_Context_T)); 

    pthread_mutex_init(&list->mutex, NULL); // Initialize the mutex.

    list->logFile = fopen("ueLog.txt", "w"); // Open log file for writing (overwrites existing data).
}

// Add an UE context to the list while managing dynamic growth and thread safety. 
int addUeContext(UeContextList_T *list, LTE_Ue_Context_T context) {
    pthread_mutex_lock(&list->mutex); // Acquire lock for thread safety.

    if (list->size >= list->capacity) {
        // If the list is full, double its capacity. 
        int newCapacity = list->capacity * 2;

        LTE_Ue_Context_T* newList = (LTE_Ue_Context_T*) realloc(list->list, newCapacity * sizeof(LTE_Ue_Context_T)); 

        if (newList == NULL) {
            pthread_mutex_unlock(&list->mutex); // Release lock before returning error code.
            return -1; // Return error code if memory allocation fails.
        }

        list->capacity = newCapacity;
        list->list = newList; 
    }

    list->list[list->size++] = context; // Add the UE context to the list.

    fprintf(list->logFile, "Added UE with ID: %d at timestamp: %ld\n", context.ue_id, time(NULL)); 

    pthread_mutex_unlock(&list->mutex); // Release lock after adding the UE context.

    return list->size - 1; // Return the index of the added UE context.
}

// Serialize the list of UE contexts to a file. 
void serializeUeContextList(UeContextList_T *list, const char *fileName) {
    FILE *file = fopen(fileName, "wb"); // Open the file for writing binary data.

    if (file != NULL) {
        fwrite(&list->size, sizeof(int), 1, file); // Write the number of UE contexts to the file.

        for (int i = 0; i < list->size; ++i) {
            fwrite(&list->list[i], sizeof(LTE_Ue_Context_T), 1, file); // Write each UE context to the file.
        }

        fclose(file); // Close the file after writing all data.
    }
}

// Deserialize the list of UE contexts from a file and add them to the specified UE context list. 
void deserializeUeContextList(UeContextList_T *list, const char *fileName) {
    FILE *file = fopen(fileName, "rb"); // Open the file for reading binary data.

    if (file != NULL) {
        int size;

        fread(&size, sizeof(int), 1, file); // Read the number of UE contexts from the file.

        for (int i = 0; i < size; ++i) {
            LTE_Ue_Context_T context;

            fread(&context, sizeof(LTE_Ue_Context_T), 1, file); // Read each UE context from the file.

            addUeContext(list, context); // Add the read UE context to the list.
        }

        fclose(file); // Close the file after reading all data.
    }
}

// Cleanup and free resources associated with the UE context list. 
void cleanUpUeContextList(UeContextList_T *list) {
    pthread_mutex_destroy(&list->mutex); // Destroy the mutex before freeing memory.

    if (list->list != NULL) {
        free(list->list); // Free the list of UE contexts.
    }

    fclose(list->logFile); // Close the log file after writing all data.
}

// Handle errors gracefully by logging error messages and possibly exiting the program or returning an appropriate error code to indicate failure. This is just a basic example, actual implementation can be more complex and comprehensive.
This code assumes that the LTE standard specifies lowercase letters as valid security keys. Also, it does not check for duplicate UE IDs or other potential errors in real-world usage.
']

