#include <chrono>
#include <random>
#include <atomic>
#include <mutex>
#include <thread>

using namespace std;
using json = nlohmann::json;
namespace asio = boost::asio;
using boost::asio::ip::tcp;
using SensorData = struct sensor_data {
    chrono::system_clock::time_point timestamp;
    float value;
    char buffer[50];
};

atomic<bool> serverUp;
mutex mtx;
vector<SensorData*> sensors;
const int MAX_MEMORY = 1024 * 1024 * 1024; // 1GB
int currentMemory = 0;
chrono::seconds retryInterval(5);
asio::io_context ioContext;
string serverAddress = "localhost";
short serverPort = 8080;
atomic<bool> connectedToServer = false;
const int MAX_CONCURRENT_REQUESTS = 10; // You may adjust this number according to your needs.
semaphore sem(MAX_CONCURRENT_REQUESTS); 

void sendData() {
    if(!connectedToServer) return;
    sem.acquire();
    tcp::socket socket(ioContext);
    asio::connect(socket, tcp::resolver(ioContext).resolve({serverAddress, to_string(serverPort)}));
    for(auto& sensor : sensors) {
        json data = {{"timestamp", chrono::system_clock::to_time_t(sensor->timestamp)}, 
                     {"value", sensor->value},
                     {"buffer", string(sensor->buffer)}};
        asio::write(socket, asio::buffer(data.dump()));
    }
    sem.release();
}

void pingServer() {
    tcp::socket socket(ioContext);
    try{
        asio::connect(socket, tcp::resolver(ioContext).resolve({serverAddress, to_string(serverPort)}));
        serverUp = true;
        connectedToServer = true;
    } catch (...) {
        serverUp = false;
    }
}

void healthCheck() {
    while(true) {
        pingServer();
        if(!serverUp) this_thread::sleep_for(retryInterval);
        else sendData();
    }
}

bool allocateSensorMemory(int numOfSensors){
    lock_guard<mutex> lck (mtx);
    if(currentMemory + sizeof(sensor_data) * numOfSensors > MAX_MEMORY) return false;
    for(int i = 0; i < numOfSensors; ++i) {
        sensors.push_back(new SensorData());
    }
    currentMemory += sizeof(sensor_data) * numOfSensors;
    return true;
}

void deallocateAll() {
    lock_guard<mutex> lck (mtx);
    for(auto& sensor : sensors){
        delete sensor;
    }
    currentMemory = 0;
    sensors.clear();
}

float generateRandomValue(float lowerBound, float upperBound) {
    random_device rd;  
    mt19937 gen(rd()); 
    uniform_real_distribution<> dis(lowerBound, upperBound);
    return dis(gen);
}

void setTimeStamp() {
    lock_guard<mutex> lck (mtx);
    for(auto& sensor : sensors){
        sensor->timestamp = chrono::system_clock::now();
    }
}

TEST(MemoryTest, Test1) {
    ASSERT_TRUE(allocateSensorMemory(5)); //should pass
}

TEST(MemoryTest, Test2) {
    deallocateAll();
    ASSERT_FALSE(allocateSensorMemory(MAX_MEMORY + 10)); // should fail
}

int main() {
    testing::InitGoogleTest();
    RUN_ALL_TESTS();

    vector<string> sensorNames;
    /* 
       Populate the 'sensorNames' vector with actual sensor names from an external module.
       For simplicity we will just use dummy names here for demonstration purposes.
    */
    sensorNames = {"sensor1", "sensor2", "sensor3"};

    allocateSensorMemory(sensorNames.size());

    setTimeStamp();

    float lowerBound = 0; 
    float upperBound = 100;
    for (int i=0; i < sensors.size(); ++i) {
        sensors[i]->value = generateRandomValue(lowerBound, upperBound);
        strcpy(sensors[i]->buffer, sensorNames[i].c_str());
    }

    // Start a thread for health check to periodically ping the server
    thread healthCheckThread(healthCheck);
    healthCheckThread.detach();

    while (true) {
        this_thread::sleep_for(chrono::seconds(1));
    }
}
``` 

