// Load list of EMUs from file.
EMU* loadFromFile(const char* filename, int *NPtr) {
    // Open the file for reading.
    FILE *file = fopen(filename, "r");

    if (file == NULL) return NULL;  // handle error...

    // Get size of the file.
    fseek(file, 0L, SEEK_END);
    long num = ftell(file);
    rewind(file);
    *NPtr = num / sizeof(EMU);

    EMU* emuList = malloc(num);

    // Read each EMU from file.
    for (int i = 0; i < *NPtr; i++) {
