["Here is a basic implementation of the requirements using C and POSIX threads for thread safety. For simplicity, we are assuming that UEIDs and CCIs are integers and do not require dynamic memory allocation or serialization/deserialization support.

```C
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int ueid;
    int num_cce;
    int crc_flag;
} CCCI;

typedef struct Node{
    CCCI ccci;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int total_cce = 0;

void add(int ueid, int num_cce){
    pthread_mutex_lock(&lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->ccci.ueid = ueid;
    newNode->ccci.num_cce = num_cce;
    newNode->ccci.crc_flag = rand() % 2;
    newNode->next = head;
    head = newNode;
    total_cce += num_cce;
    pthread_mutex_unlock(&lock);
}

void remove(int ueid){
    pthread_mutex_lock(&lock);
    Node* current = head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->ccci.ueid == ueid) {
            total_cce -= current->ccci.num_cce;
            if(prev != NULL){
                prev->next = current->next;
            } else{
                head = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&lock);
}

int get_total(){
    int total;
    pthread_mutex_lock(&lock);
    total = total_cce;
    pthread_mutex_unlock(&lock);
    return total;
}
```
