void sendGETRequest(boost::asio::ip::tcp::socket& sock, const std::string& request) {
    boost::system::error_code ec;
    boost::asio::write(sock, boost::asio::buffer(request), ec);
    if (ec) {
        // handle error
    } else {
        std::cout << "GET request sent successfully\n";
    }
