void pingServer(boost::asio::ip::tcp::socket& sock, const std::string& serverIP, int port) {
    boost::system::error_code ec;

    while (true) {
        sendGETRequest(sock, "ping\n");

        // Sleep for some time before sending next ping request
        std::this_thread::sleep_for(std::chrono::seconds(1)); 
    }
}

int main() {
    srand(static_cast<unsigned int>(time(0)));
    boost::asio::io_service ioService;

