    boost::asio::ssl::stream<boost::asio::ip::tcp::socket> socket(io_service, ctx);
    boost::asio::connect(socket.lowest_layer(), endpoint_iterator);

    // Perform SSL handshake
    socket.handshake(boost::asio::ssl::stream_base::client);

    // Write the HTTP request to the server
    std::string const request = "GET / HTTP/1.0\r\nHost: host\r\nAccept: */*\r\nConnection: close\r\n\r\n";
    boost::asio::write(socket, boost::asio::buffer(request));

    // Read the response from the server
    for (;;) {
        std::vector<char> buffer(1024);
        boost::system::error_code error;

        size_t len = socket.read_some(boost::asio::buffer(buffer), error);
        if (error == boost::asio::error::eof) {
            break;
        } else if (error) {
            throw boost::system::system_error(error); 
        }

        std::cout.write(&buffer[0], len);
    }
}
```
