```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <assert.h>

typedef struct {
    int value;
} Record;

void initialize(long *offset, int *keys, Record *records, int size) {

    assert(size > 0); // Validate input parameters 

    srand(time(NULL)); // Initialize random seed for rand() function

    long total_memory = (2L*size + sizeof(Record))*size;
    if (total_memory > MEMORY_LIMIT) {
        fprintf(stderr, "Error: Memory limit exceeded.\n"); // Error handling
        exit(EXIT_FAILURE);
    }

    offset = calloc(size, sizeof(long)); // Dynamic memory allocation for arrays
    keys   = malloc(size * sizeof(int));
    records = malloc(size * sizeof(Record));

    if (offset == NULL || keys == NULL || records == NULL) { 
        fprintf(stderr, "Error: Memory allocation failed.\n"); // Error handling
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < size; ++i) {
        offset[i] = rand(); // Initialize arrays with random values 
        keys[i]   = rand() % MAX_KEYS; 

        records[i].value = rand() % RANGE_VALUES;
    }    
}
```
Please replace `MEMORY_LIMIT`, `MAX_KEYS` and `RANGE_VALUES` with actual numbers. 
