["Below is a C program code for managing memory for and initializing two arrays (one for long offset values and one for int keys), allocating memory for an array of record structures, filling the records with random integers within a specified range, sorting the records by keys in lexicographical order, handling errors during memory allocation, and providing loggers for errors and performance metrics. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <assert.h>
#include <string.h>

typedef struct {
    int key;
} Record;

int compare(const void *a, const void *b) {
    return ((Record *)a)->key - ((Record *)b)->key;
}

void sort_records(long* offsets, int* keys, Record* records, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        records[i].key = keys[offsets[i]];
    }
    qsort(records, n, sizeof(Record), compare);
}

void allocate_memory(long** offsets, int** keys, Record** records, size_t n) {
    srand((unsigned int)time(NULL));  // seed the random number generator with current time

    *offsets = malloc(n * sizeof(long));
    assert(*offsets != NULL);  // check for successful memory allocation

    *keys = malloc(n * sizeof(int));
    assert(*keys != NULL);

    *records = malloc(n * sizeof(Record));
    assert(*records != NULL);
}

void fill_arrays(long* offsets, int* keys, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        offsets[i] = rand() % n;  // generate a random index within the range [0, n)
        keys[i] = rand();  // generate a random integer
    }
}

void deallocate_memory(long* offsets, int* keys, Record* records) {
    free(offsets);
    free(keys);
    free(records);
}

int main() {
    long* offsets = NULL;
    int* keys = NULL;
    Record* records = NULL;
    size_t n = 1024;  // specify the number of elements in the arrays

    allocate_memory(&offsets, &keys, &records, n);
    fill_arrays(offsets, keys, n);
    sort_records(offsets, keys, records, n);
    deallocate_memory(offsets, keys, records);

    return 0;
}
```

Please note that this is a basic example and lacks many features such as error logging or handling dynamic data sources for keys and values. Also, the actual size of the arrays would need to be set based on the available memory resources and the expected load on the system. 

