['The given task is quite extensive, here's a basic implementation of the requested function in C using quicksort algorithm for sorting arrays of records. 

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    double value;
} Record;

// Function to partition array
int partition(Record arr[], int low, int high) {
    double pivot = arr[high].value;
    int i = (low - 1);

    for (int j = low; j <= high- 1; j++){
        if (arr[j].value < pivot) {
            i++;
            Record temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }

    Record temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    return (i + 1);
}

// Function to sort array using quicksort algorithm
void quickSort(Record arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

void initializeAndSortRecords() {
    srand((unsigned int) time(NULL)); // Seed the random number generator.

    long* offsets = malloc(sizeof(long) * 3); // Allocate memory for offsets array.
    if (offsets == NULL) {
        printf("Memory allocation failed for offsets!\n");
        return;
    }

    int* keys = malloc(sizeof(int) * 100); // Allocate memory for keys array.
    if (keys == NULL) {
        printf("Memory allocation failed for keys!\n");
        free(offsets);
        return;
    }

    double* values = malloc(sizeof(double) * 100); // Allocate memory for values array.
    if (values == NULL) {
        printf("Memory allocation failed for values!\n");
        free(offsets);
        free(keys);
        return;
    }

    Record* records = malloc(sizeof(Record) * 100); // Allocate memory for records array.
    if (records == NULL) {
        printf("Memory allocation failed for records!\n");
        free(offsets);
        free(keys);
        free(values);
        return;
    }

    // Initialize arrays with random values within a specified range.
    for (int i = 0; i < 100; ++i) {
        keys[i] = rand() % 100;
        values[i] = ((double)rand() / (double)(RAND_MAX)) * 100;

        Record record;
        record.key = keys[i];
        record.value = values[i];
        records[i] = record;
    }

    clock_t startTime = clock(); // Start timer before sorting.
    quickSort(records, 0, 99); // Sort the array of records based on their corresponding keys.
    double totalTime = (double)(clock() - startTime) / CLOCKS_PER_SEC;

    printf("Time taken for sorting: %f seconds\n", totalTime); // Log time taken for sorting.

    free(offsets); // Free all allocated memory after use to prevent memory leaks.
    free(keys); 
    free(values);
    free(records);
}
```

This is a basic example and does not include batch updates, logging, error handling, or checking of integrity of data from external sources. Please note that this code has not been thoroughly tested, it's just a starting point for your requirements.
']

