    srand(time(NULL));

    for (int i = 0; i < length; i++) {
        doubles[i] = ((double) rand() / RAND_MAX) * 10.0; // Generate random double value
        keys[i] = malloc(sizeof(char) * 2); // Allocate memory for each key
        sprintf(keys[i], "%c", 'a' + rand() % 26); // Assign a random character to the key
    }
}

// Compare function required by qsort for sorting DataPoint structures
int compare_dataPoints(const void* a, const void* b) {
    double diff = ((DataPoint*)a)->value - ((DataPoint*)b)->value;

    if (diff < 0.0) 
        return -1;
    else if (diff > 0.0) 
        return 1;
    else 
        return 0;
}

// Filtering function based on a lexicographical order
void filter_sort(DataPoint* dataPoints, char** keys, int length) {
    for (int i = 0; i < length - 1; i++) {
        if (strcmp(keys[i], keys[i + 1]) > 0) { // If current key is greater than next key in lexicographical order...
            DataPoint temp = dataPoints[i];
            dataPoints[i] = dataPoints[i + 1];
            dataPoints[i + 1] = temp; // Swap the DataPoint structures

            char* tempKey = keys[i];
            keys[i] = keys[i + 1];
            keys[i + 1] = tempKey; // Also swap the corresponding keys
        }
    }
}

int main() {
    int length = 5;

    double* doubles = malloc(length * sizeof(double));
    char** keys = malloc(length * sizeof(char*));

    generate_data(doubles, keys, length);

    DataPoint* dataPoints = malloc(sizeof(DataPoint) * length);

    for (int i = 0; i < length; i++) 
