The `setupLteMacConfig` function could look like this:

```c
#include <openssl/evp.h>
#include "lte_mac_config.h"

EVP_CIPHER *setupLteMacConfig(int range, int mode) {
    OpenSSL_add_all_algorithms();
    EVP_CIPHER *cipher;

    switch (mode) {
        case 1: cipher = EVP_aes_256_ecb(); break;
        case 2: cipher = EVP_aes_256_cbc(); break;
        case 3: cipher = EVP_aes_256_gcm(); break;
        case 4: cipher = EVP_aes_256_ctr(); break;
        default: return NULL; // Invalid mode, handle error here
    }

    if (cipher == NULL) {
        // Handle error here
    }

    // Generate and populate LTE_MAC_Config structures
    LteMacConfig *head = malloc(sizeof(LteMacConfig));
    head->entityId = 0;
    head->configParam1 = "default";
    head->configParam2 = 0;

    for (int i = 1; i < range; i++) {
        LteMacConfig *newNode = malloc(sizeof(LteMacConfig));
        newNode->entityId = i;
        newNode->configParam1 = "default";
        newNode->configParam2 = 0;

        // Add new node to the end of linked list
        LteMacConfig *last = head;
        while (last->next != NULL) {
            last = last->next;
        }
        last->next = newNode;
    }

    return cipher;
}
