    struct ListNode* next;
} ListNode;

typedef struct {
    pthread_mutex_t mutex;
    int size;
    int max_size;
    int memory_usage;
    ListNode* head;
} CCCIList;

void init_list(CCCIList* list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->size = 0;
    list->max_size = DEFAULT_MAX_CCCIS; // You can make it configurable.
    list->memory_usage = 0;
    list->head = NULL;
}

void add_ccci(CCCIList* list, CCCI ccci) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->max_size) {
        syslog(LOG_ERR, "Error: Maximum number of CCCIs reached. Cannot add.");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    ListNode* new_node = malloc(sizeof(ListNode));
    if (!new_node) {
        syslog(LOG_ERR, "Error: Memory allocation failed. Cannot add CCCI.");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    new_node->ccci = ccci;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    // Calculate memory usage according to your structure's size.
    list->memory_usage += sizeof(CCCI); 

    if (list->memory_usage > MAX_MEMORY_USAGE) {
        syslog(LOG_ERR, "Error: Memory usage limit exceeded.");

        // Remove the last node to balance memory usage.
        ListNode* temp = list->head;
        while (temp && temp->next && temp->next->next) {
            temp = temp->next;
        }

        if (temp != NULL) {
            free(temp->next);
            temp->next = NULL;
            list->size--;
        }
    } else {
        syslog(LOG_INFO, "Info: CCCI added successfully.");
    }

    pthread_mutex_unlock(&list->mutex);
}
