int totalPackets = 0;
int capacity;

void* generatePackets(void* arg) {
    int initialBufferSize = *((int*)arg);

    // initialize list with initial size
    packetList = (L2_Packet**)malloc(sizeof(L2_Packet*) * initialBufferSize);
    if (!packetList) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    capacity = initialBufferSize;

    srand(time(0)); // seed random number generator

    // generate packets
    while (1) {
        pthread_mutex_lock(&mutex);

        if (totalPackets >= capacity) {
            packetList = realloc(packetList, sizeof(L2_Packet*) * capacity * 2);
            if (!packetList) {
                fprintf(stderr, "Memory allocation failed\n");
                return NULL;
            }

            capacity *= 2;
        }

        L2_Packet* packet = (L2_Packet*)malloc(sizeof(L2_Packet));
        if (!packet) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        // populate the MAC header with unique address
        for (int i = 0; i < 6; ++i) {
            packet->mac_header.data[i] = rand() % 256;
        }

        // ensure no two consecutive packets have the same MAC address
        if (totalPackets > 0 && memcmp(packetList[totalPackets - 1]->mac_header.data, packet->mac_header.data, 6) == 0) {
            free(packet); // ensure memory is freed correctly
            continue;
        }

        // populate the PHY header with random payload size
        int payloadSize = 100 + rand() % (1000 - 100 + 1);
        packet->phy_header.payloadSize = payloadSize;

        packet->data_payload = malloc(payloadSize); // allocate memory for data payload
        if (!packet->data_payload) {
            fprintf(stderr, "Memory allocation failed\n");
            return NULL;
        }

        packetList[totalPackets] = packet;
        ++totalPackets;

        pthread_mutex_unlock(&mutex);
    }

    return (void*)(long)totalPackets; // return total number of packets generated as a long integer
}
