Here's a general outline of the solution in C using pthread for thread safety and cJSON for JSON serialization. Note that this is not a complete implementation but rather a starting point:

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include "cjson/cJSON.h"

typedef struct {
    int key;
} Record;

// Mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void *generateData(size_t offsetSize, size_t keySize, size_t recordSize, int minVal, int maxVal, void **offsets, void **keys, Record **records, double **values) {
    // Input validation
    if (offsetSize <= 0 || keySize <= 0 || recordSize <= 0 || minVal > maxVal) {
        return NULL;
    }

    srand(time(NULL));  // Initialize random number generator

    *offsets = malloc(sizeof(long) * offsetSize);
    *keys = calloc(keySize, sizeof(int));
    *records = calloc(recordSize, sizeof(Record));

    // Error handling for memory allocation failures
    if (*offsets == NULL || *keys == NULL || *records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    // Generate unique keys
    int key;
    for (size_t i = 0; i < recordSize; ) {
        pthread_mutex_lock(&mutex);  // Lock mutex before accessing shared data
        key = rand() % (maxVal - minVal + 1) + minVal;

        int j;
        for (j = 0; j < i; j++) {
            if ((*records)[j].key == key) break;
        }

        // If the key is unique, assign it to the record and increment counter
        if (j == i) {
            (*records)[i].key = key;
            i++;
        }
        pthread_mutex_unlock(&mutex);  // Unlock mutex after shared data access
    }

    return *keys;
}
```
This function will only assign keys to records if they are unique, ensuring that no two records have the same key value. It's important to note that this solution is not optimized for performance and has potential scalability issues. You may need to rethink your approach or use a different strategy depending on your specific requirements.
