    char* ranConnectionInfoTag;
    int securityKey;
} UEContext;

UEContext* createUEContext(int N) {
    if (N <= 0) return NULL;

    srand(time(NULL));
    UEContext *list = malloc(sizeof(UEContext)*N);
    for (int i = 0; i < N; i++) {
        list[i].ueId = rand();

        char* randomStr = generateRandomString(16);  // Function to generate a random string of length 16.
        if (!randomStr) {
            free(list);
            return NULL;  // Error in generating random string.
        }
        list[i].ranConnectionInfoTag = randomStr;

        list[i].securityKey = rand();
    }

    return list;
}

int addUEContext(UEContext** list, int* currentSize, int* maxSize) {
    if (*currentSize >= *maxSize) {
        *maxSize *= 2;  // Growing dynamically.
        UEContext* temp = realloc(*list, sizeof(UEContext)*(*maxSize));
        if (!temp) return -1;  // Error in memory allocation.

        *list = temp;
    }

    (*list)[*currentSize].ueId = rand();
    char* randomStr = generateRandomString(16);
    if (!randomStr) {
        free(*list);
        return -2;  // Error in generating random string.
    }
    (*list)[*currentSize].ranConnectionInfoTag = randomStr;

    (*list)[*currentSize].securityKey = rand();
    (*currentSize)++;

    return 0;  // Successfully added UE context.
}

int removeUEContext(UEContext** list, int indexToRemove, int* currentSize) {
    if (indexToRemove < 0 || indexToRemove >= *currentSize) {
        return -1;  // Invalid index to remove.
    }

    free((*list)[indexToRemove].ranConnectionInfoTag);
    for(int i = indexToRemove; i < (*currentSize)-1; i++) {
        (*list)[i] = (*list)[i+1];  // Shifting array elements.
    }

    (*currentSize)--;
    UEContext* temp = realloc(*list, sizeof(UEContext)*(*currentSize));
    if (!temp && *currentSize != 0) {  // Error in memory allocation.
        return -2;
    }

    *list = temp;

    return 0;  // Successfully removed UE context.
}
```

