void initialize_crypto(const char *config) {
    FILE *file = fopen(config, "r");
    if (!file) {
        // Handle error: unable to open configuration file.
        return;
    }

    char algorithm[256];
    while (fgets(algorithm, sizeof(algorithm), file)) {
        algorithm[strcspn(algorithm, "\n")] = 0;  // Remove trailing newline.

        EVP_add_digest(EVP_get_digestbyname(algorithm));
        if (ERR_get_error()) {
            // Handle error: unable to load algorithm from OpenSSL.
            continue;
        }
    }

    fclose(file);
}

void initialize_data(double rangeMin, double rangeMax) {
    srand((unsigned int) time(NULL));  // Seed the random number generator.

    const int numDataPoints = 1024;
    data_point *data = calloc(numDataPoints, sizeof(*data));
    if (!data) {
        // Handle error: unable to allocate memory for data array.
        return;
    }

    double rangeSpread = rangeMax - rangeMin;
    for (int i = 0; i < numDataPoints; ++i) {
        double randomValueInRange = ((double) rand() / RAND_MAX) * rangeSpread + rangeMin;

        data[i].value = randomValueInRange;
        data[i].key = i;

        // Reuse existing label string if possible.
        char *label = labels[labelIndex];
        if (label == NULL) {
            label = calloc(16, sizeof(*label));
            if (!label) {
                // Handle error: unable to allocate memory for label string.
                continue;
            }

            sprintf(label, "Label%d", i);
            labels[labelIndex] = label;
        }

        data[i].label = label;
        labelIndex = (labelIndex + 1) % 1024;
    }

    // Do something with the data...
}
```
