typedef struct {
    int LTE_PHY_TRANSPORT_BLOCK_TAG;
    int CRCFLAG;
} LTE_PHY_TRANSPORT_BLOCK_T;

int create_blocks(LTE_PHY_TRANSPORT_BLOCK_T **list, size_t *size) {
    srand((unsigned int)time(NULL)); // Seed the random number generator

    if (*list == NULL) {
        *size = 10;  // Initial list capacity
        *list = (LTE_PHY_TRANSPORT_BLOCK_T*) malloc(*size * sizeof(LTE_PHY_TRANSPORT_BLOCK_T));
    } else if (*size % 2 == 0) {  // If the list is full, double its size
        *list = (LTE_PHY_TRANSPORT_BLOCK_T*) realloc(*list, *size * 2 * sizeof(LTE_PHY_TRANSPORT_BLOCK_T));

        if (*list == NULL) { // Handle memory allocation failure
            perror("Memory allocation failed");
            return -1;
        }

        *size = *size * 2;
    }

    for (int i = 0; i < *size / 2; ++i) { // Assign values to half of the list
        (*list)[i].LTE_PHY_TRANSPORT_BLOCK_TAG = rand();  // Randomly generate tag
        (*list)[i].CRCFLAG = rand() % 2;  // Randomly set CRCFLAG
