void initialize(long* offsets, size_t offsetSize, int* keys, size_t keySize, 
                 Record** records, size_t recordSize, int minValue, int maxValue) {
    srand((unsigned int)time(NULL)); // seed the random number generator

    for (size_t i = 0; i < offsetSize; ++i)
        offsets[i] = rand();

    for (size_t i = 0; i < keySize; ++i)
