    for (size_t i = 0; i < recordSize; ++i){
        (*records)[i].value = minValue + rand() % ((maxValue + 1) - minValue);  // Random value in the range [minValue, maxValue]
    }

    pthread_mutex_unlock(&mutex);
}
```
In this code:
