['Here's a sample C function named `initializeDataStructures` fulfilling the specified requirements:

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} record;

static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;

int initializeDataStructures(long* offsets, size_t num_offsets, int** keys, 
                             size_t num_keys, record*** records, 
                             size_t num_records, int min_val, int max_val) {
    // Lock the mutex to prevent concurrent access and race conditions.
    if (pthread_mutex_lock(&mtx) != 0) {
        printf("Failed to lock mutex\n");
        return -1;
    }

    *offsets = malloc(num_offsets * sizeof(long));
    if (*offsets == NULL) {
        printf("Failed to allocate memory for offsets\n");
        pthread_mutex_unlock(&mtx); // Unlock the mutex before returning.
        return -1;
    }

    *keys = malloc(num_keys * sizeof(int));
    if (*keys == NULL) {
        printf("Failed to allocate memory for keys\n");
        free(*offsets); // Free already allocated memory before returning.
        pthread_mutex_unlock(&mtx); // Unlock the mutex before returning.
        return -1;
    }

    *records = malloc(num_records * sizeof(record*));
    if (*records == NULL) {
        printf("Failed to allocate memory for records\n");
        free(*offsets); // Free already allocated memory before returning.
        free(*keys); // Free already allocated memory before returning.
        pthread_mutex_unlock(&mtx); // Unlock the mutex before returning.
        return -1;
    }

    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            printf("Failed to allocate memory for record %zu\n", i);
             // Free already allocated records before returning.
            for (--i; i >= 0; --i)
                free((*records)[i]);
            free(*offsets);
            free(*keys);
            pthread_mutex_unlock(&mtx); 
            return -1;
        }
        (*records)[i]->value = rand() % (max_val - min_val + 1) + min_val;
    }

    // Unlock the mutex after successful memory allocation and record initialization.
    pthread_mutex_unlock(&mtx); 
    return 0;
}
```
This function follows best practices for dynamic memory management, including freeing allocated memory in case of allocation failures and using a mutex to prevent race conditions when multiple threads might access the shared data structures simultaneously. 

Please note that this is a basic example. Depending on your system's requirements and architecture, you may need more sophisticated methods of synchronization. For instance, you could use atomic operations for simpler concurrent data structures or consider using readers-writer locks if performance becomes an issue. Always ensure to test and benchmark your code thoroughly before integrating it into a larger system.
