['```c
#include <stdlib.h>
#include <string.h>

typedef struct packet {
    size_t length;
    int type;
    char* data;
} Packet;

typedef struct {
    Packet** packets;
    size_t totalPackets;
    size_t allocatedPackets;
    size_t memoryUsageLimit;
    size_t currentMemoryUsage;
} PacketList;

enum ErrorCode {
    ERR_SUCCESS,
    ERR_MEMORY_ALLOCATION_FAILED,
    ERR_MEMORY_LIMIT_EXCEEDED
};

int initPacketList(PacketList* list, size_t memoryUsageLimit) {
    list->packets = NULL;
    list->totalPackets = 0;
    list->allocatedPackets = 0;
    list->memoryUsageLimit = memoryUsageLimit;
    list->currentMemoryUsage = 0;

    return ERR_SUCCESS;
}

int addPacket(PacketList* list, size_t length, int type, const char* data) {
    if (list->currentMemoryUsage + sizeof(Packet*) > list->memoryUsageLimit) {
        return ERR_MEMORY_LIMIT_EXCEEDED;
    }

    Packet* packet = malloc(sizeof(Packet));
    if (!packet) {
        return ERR_MEMORY_ALLOCATION_FAILED;
    }

    list->currentMemoryUsage += sizeof(Packet);
    packet->length = length;
    packet->type = type;

    if (data != NULL) {
        packet->data = malloc(length * sizeof(char));
        if (!packet->data) {
            free(packet);
            list->currentMemoryUsage -= sizeof(Packet);
            return ERR_MEMORY_ALLOCATION_FAILED;
        }

        memcpy(packet->data, data, length * sizeof(char));
        list->currentMemoryUsage += length * sizeof(char);
    } else {
        packet->data = NULL;
    }

    if (list->totalPackets == list->allocatedPackets) {
        size_t newSize = list->allocatedPackets == 0 ? 1 : list->allocatedPackets * 2;
        Packet** newArray = realloc(list->packets, newSize * sizeof(Packet*));

        if (!newArray) {
            free(packet->data);
            free(packet);
            list->currentMemoryUsage -= sizeof(Packet) + length * sizeof(char);
            return ERR_MEMORY_ALLOCATION_FAILED;
        }

        list->allocatedPackets = newSize;
        list->packets = newArray;
    }

    list->packets[list->totalPackets] = packet;
    list->totalPackets++;

    return ERR_SUCCESS;
}

void freePacketList(PacketList* list) {
    for (size_t i = 0; i < list->totalPackets; ++i) {
        if (list->packets[i]->data != NULL) {
            free(list->packets[i]->data);
            list->currentMemoryUsage -= sizeof(char) * list->packets[i]->length;
        }

        free(list->packets[i]);
    }

    if (list->totalPackets > 0) {
        free(list->packets);
        list->currentMemoryUsage -= sizeof(Packet*) * list->allocatedPackets;
    }
}
```
