void* populateList(ThreadSafeList *tsl, int n) {
    if (n <= 0) {
        return NULL; // Error handling for invalid parameter.
    }

    NFAPI_CRC_INDICATION_PDU_T **list = malloc(sizeof(*list) * n); 

    if (!list) {
        return NULL; // Error handling for memory allocation failure.
    }

    srand(time(NULL));
    pthread_mutex_init(&tsl->mutex, NULL);

    for (int i = 0; i < n; ++i) {
        list[i] = malloc(sizeof(**list));

        if (!list[i]) {
            // Memory allocation failure. Clean up and return NULL. 
            for (--i; i >= 0; --i) {
                free(list[i]);
            }

