        list[i]->RX_UE_INFORMATION_TAG = 'A' + rand() % 26; // Randomly set tag.
        list[i]->RNTI = rand(); // Randomly set RNTI.
    }

    pthread_mutex_lock(&tsl->mutex);
    tsl->list = list;
    tsl->len = n;
    pthread_mutex_unlock(&tsl->mutex);

    return tsl;
}
