void sendPostRequest(std::vector<SensorData> data) {
    MockDataProcessor mockDataProcessor;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (mockDataProcessor.ProcessData(data)) {
            std::lock_guard<std::mutex> lock(mtx);
            ++successDataEntries;
            break;
        } else {
            ++retries;
            int sleepTime = std::pow(2, retries) * 1000; // Exponential backoff.
            std::this_thread::sleep_for(std::chrono::milliseconds(sleepTime));
        }
    }

    if (retries == MAX_RETRIES) {
        std::lock_guard<std::mutex> lock(mtx);
        ++failedDataEntries;
    }
