    CCCI* newCCCI = malloc(sizeof(CCCI));
    if (newCCCI == NULL) {
        free(newCces);
        return NULL;
    }

    newCCCI->ueid = ueid;
    newCCCI->cces = newCces;
    newCCCI->crc = crc;

    pthread_mutex_lock(&mutex);
