// Define maximum number of CCCI structures and unique UEIDs
#define MAX_UE 1000
#define MAX_CCE 10

typedef struct {
    int id;
} UEID;

typedef struct {
    // Add fields for CCE elements here
} CCE;

typedef struct {
    UEID ueid;
    CCE cces[MAX_CCE];
    size_t count;
} CCCI;

// Array-based hash table implementation to store UEIDs and their corresponding indices in the CCCI array
typedef struct {
    UEID ueids[MAX_UE];
    int indices[MAX_UE];
    pthread_mutex_t lock;
} HashTable;

HashTable hashTable;

// Array to store all CCCI structures
static CCCI cccis[MAX_UE] = {0};

int addCCCI(CCCI *ccci) {
    // Acquire the lock before modifying the hash table and the array
    pthread_mutex_lock(&hashTable.lock);

    if (hashTable.count >= MAX_UE) {
        fprintf(stderr, "Maximum number of CCCI structures reached.\n");
        return -1;
    }

    // Check for duplicate UEIDs
    int index = hashTable.indices[ccci->ueid];
    if (index != -1) {
        fprintf(stderr, "Duplicate UEID found: %d\n", ccci->ueid);
        return -1;
    }

    // Add CCCI to the array and update the hash table
    index = hashTable.count;
    memcpy(&cccis[index], ccci, sizeof(CCCI));
    hashTable.indices[hashTable.count] = index;
    hashTable.ueids[hashTable.count++] = ccci->ueid;

    // Release the lock after modifying the array and hash table
    pthread_mutex_unlock(&hashTable.lock);

    return 0;
}
```

