typedef struct NFAPI_CRC_INDICATION_PDU_TAG {
    RX_UE_INFORMATION_T ueInfo;
    CRC_INDICATION_REL8_T crcIndication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    struct Node* prev;
} Node;

// Function to generate a new node for the list
Node* createNewNode(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    newNode->data = data;
    newNode->next = NULL;
    newNode->prev = NULL;

    return newNode;
}

// Function to add a node at the end of the list
void appendNode(Node** head, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = createNewNode(data);

    if (*head == NULL) {
        *head = newNode;
        return;
    }

    Node* last = *head;

    while (last->next != NULL) 
        last = last->next;

    last->next = newNode;
    newNode->prev = last;
}

// The main function that creates and populates the list with N elements
void createListOfN(int n, Node** head) {
    srand((unsigned int) time(NULL)); // seeding random number generator

    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        // Generate random RNTI and CRCFLAG
        pdu.ueInfo.rnti = rand();
        pdu.crcIndication.crcFlag = rand() % 2;

        appendNode(head, pdu);
    }
}
```

